export function fabaoDbKeyToSourceType(key: string): SourceType {
  if (key === 'court_case') return 'judgment';
  if (key === 'regulation' || key === 'legislation' || key === 'labor') return 'law';
  if (key === 'journal' || key === 'lawyer') return 'article';
  if (key === 'case' || key === 'typical' || key === 'guiding') return 'case';
  return 'case';
}

