function snippetFrom(title: string, extra: string) {
  return `标题: ${title}。${extra}`;
}

/** 基于参考来源扩展生成匹配结果 mock（工具召回的全部候选，数量多于参考来源） */
export function buildMockMatchResults(referenceSources: ReferenceSourceItem[]): ReferenceSourceItem[] {
  const TARGET_MIN = 38;
  const extras: ReferenceSourceItem[] = [];
  let extraN = 0;
  const extraNeeded = Math.max(TARGET_MIN - referenceSources.length, 12);

  for (let i = 0; i < extraNeeded; i++) {
    const base = referenceSources[i % referenceSources.length];
    extras.push({
      ...base,
      id: `match-recall-${++extraN}`,
      citedMark: undefined,
      userPinned: false,
      title: base.title,
      snippet: snippetFrom(base.title, '工具召回候选条目，演示匹配结果列表展示。'),
      hitSnippet:
        base.hitSnippet ??
        `与「${base.title}」相关的候选命中内容：本轮检索工具召回的扩展结果，用于演示匹配结果 Tab 与参考来源 Tab 的数量差异及状态标签展示。`,
    });
  }

  return [...referenceSources, ...extras];
}

