/** 将匹配结果分配到条件组，并按目标数量切分 */
function assignMatchResultsToConditionGroups(
  items: ReferenceSourceItem[],
  groupTargets: number[]
): { matchResults: ReferenceSourceItem[]; matchConditionGroups: MatchConditionGroup[] } {
  const defs = MOCK_MATCH_GROUP_DEFS;
  const matchResults: ReferenceSourceItem[] = [];
  const matchConditionGroups: MatchConditionGroup[] = [];
  let start = 0;

  defs.forEach((def, gi) => {
    const target = groupTargets[gi] ?? 0;
    const slice = items.slice(start, start + target);
    start += target;
    slice.forEach((item) => {
      matchResults.push({ ...item, conditionGroupId: def.id });
    });
    matchConditionGroups.push({ ...def, count: slice.length });
  });

  if (start < items.length) {
    const lastGroup = matchConditionGroups[matchConditionGroups.length - 1];
    const rest = items.slice(start);
    rest.forEach((item) => {
      matchResults.push({ ...item, conditionGroupId: lastGroup.id });
    });
    lastGroup.count += rest.length;
  }

  return { matchResults, matchConditionGroups };
}

