import React from 'react';
import {
  Check,
  ChevronLeft,
  ChevronRight,
  Clock,
  Cpu,
  List,
  Loader2,
  Sparkles,
} from 'lucide-react';
import SearchReportResultCard, { type SearchReportResultCardVariant } from './SearchReportResultCard';
import {
  SEARCH_REPORT_MAIN_STEPS,
  buildSearchReportExecutionLogs,
  getSearchReportStepIndex,
  type SearchReportGeneratedDocument,
  type SearchReportJob,
} from './searchReportExecution';

type SearchReportExecutionPanelProps = {
  job: SearchReportJob;
  taskIndex: number;
  taskCount: number;
  onPrevTask?: () => void;
  onNextTask?: () => void;
  reportResultCardVariant?: SearchReportResultCardVariant;
  onOpenDocument?: (doc: SearchReportGeneratedDocument) => void;
};

const SearchReportExecutionPanel: React.FC<SearchReportExecutionPanelProps> = ({
  job,
  taskIndex,
  taskCount,
  onPrevTask,
  onNextTask,
  reportResultCardVariant = 'large',
  onOpenDocument,
}) => {
  const isTaskCompleted = job.status === 'completed';
  const currentStepIndex = getSearchReportStepIndex(job.progress, isTaskCompleted);
  const executionLogs = buildSearchReportExecutionLogs(
    job.progress,
    isTaskCompleted,
    job.sourceCount,
    job.sourceScope
  );
  const showProcessDetail =
    isTaskCompleted || job.status === 'failed' || job.progress >= 2;
  const showExecutionDetailPanel = reportResultCardVariant === 'large';
  const canPrevTask = taskIndex > 0;
  const canNextTask = taskIndex < taskCount - 1;

  return (
    <div className="animate-in fade-in slide-in-from-bottom-2 overflow-hidden rounded-2xl border border-slate-200 bg-slate-50/50 duration-300">
      <div className="flex shrink-0 items-center justify-between gap-2 px-4 py-3 sm:px-5">
        <div className="flex min-w-0 flex-1 items-center gap-2.5">
          <div className="rounded-lg bg-indigo-100 p-1.5 text-indigo-600">
            <Sparkles size={16} strokeWidth={2.5} />
          </div>
          <h3 className="min-w-0 truncate text-[14px] font-extrabold text-slate-800">
            {job.title}
          </h3>
          {job.status === 'generating' ? (
            <span className="shrink-0 animate-pulse rounded-md bg-blue-100 px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wider text-blue-600">
              执行中
            </span>
          ) : null}
          {job.status === 'completed' ? (
            <span className="shrink-0 rounded-md bg-emerald-100 px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wider text-emerald-600">
              已完成
            </span>
          ) : null}
          {job.status === 'failed' ? (
            <span className="shrink-0 rounded-md bg-red-100 px-2 py-0.5 text-[10px] font-extrabold uppercase tracking-wider text-red-600">
              失败
            </span>
          ) : null}
        </div>

        {taskCount > 1 ? (
          <div className="flex shrink-0 items-center gap-1">
            <span className="mr-1 text-[11px] font-bold tabular-nums text-slate-500">
              任务 {taskIndex + 1} / {taskCount}
            </span>
            <button
              type="button"
              onClick={onPrevTask}
              disabled={!canPrevTask}
              aria-label="上一个任务"
              className="rounded-md p-1 text-slate-500 transition hover:bg-slate-200/80 hover:text-slate-800 disabled:cursor-not-allowed disabled:opacity-30"
            >
              <ChevronLeft size={16} strokeWidth={2.5} />
            </button>
            <button
              type="button"
              onClick={onNextTask}
              disabled={!canNextTask}
              aria-label="下一个任务"
              className="rounded-md p-1 text-slate-500 transition hover:bg-slate-200/80 hover:text-slate-800 disabled:cursor-not-allowed disabled:opacity-30"
            >
              <ChevronRight size={16} strokeWidth={2.5} />
            </button>
          </div>
        ) : null}
      </div>

      {showProcessDetail ? (
        <div
          className={`flex animate-in fade-in flex-col px-4 pb-5 pt-1 duration-300 sm:px-5 ${
            showExecutionDetailPanel ? 'h-[260px] gap-6 md:flex-row' : 'gap-3'
          }`}
        >
          <div
            className={`relative flex flex-col overflow-hidden ${
              showExecutionDetailPanel ? 'min-h-0 flex-1 pr-2' : 'w-full'
            }`}
          >
            <div className="mb-4 flex shrink-0 items-center gap-2 text-[11px] font-extrabold uppercase tracking-widest text-slate-400">
              <List size={14} className="text-slate-400" />
              <span>执行步骤</span>
            </div>
            <div className="no-scrollbar relative flex-1 space-y-4 overflow-y-auto pb-2">
              <div className="absolute bottom-2 left-[9px] top-2 z-0 w-[2px] bg-slate-100" />
              {SEARCH_REPORT_MAIN_STEPS.map((step, idx) => {
                const isCompleted = idx < currentStepIndex || isTaskCompleted;
                const isActive = idx === currentStepIndex && !isTaskCompleted;
                const isPending = idx > currentStepIndex && !isTaskCompleted;
                return (
                  <div key={step} className="relative z-10 flex items-start gap-3">
                    <div className="mt-0.5 shrink-0 rounded-full bg-transparent shadow-[0_0_0_4px_#f8fafc]">
                      {isCompleted ? (
                        <div className="flex h-5 w-5 items-center justify-center rounded-full bg-emerald-100 text-emerald-600">
                          <Check size={10} strokeWidth={4} />
                        </div>
                      ) : null}
                      {isActive ? (
                        <div className="flex h-5 w-5 items-center justify-center rounded-full bg-blue-100 text-blue-600">
                          <Loader2 size={10} strokeWidth={3} className="animate-spin" />
                        </div>
                      ) : null}
                      {isPending ? (
                        <div className="flex h-5 w-5 items-center justify-center rounded-full border-2 border-slate-200 bg-white text-slate-300">
                          <Clock size={8} strokeWidth={3} />
                        </div>
                      ) : null}
                    </div>
                    <div
                      className={`flex flex-col pt-0.5 ${
                        isActive ? 'text-blue-700' : isCompleted ? 'text-slate-700' : 'text-slate-400'
                      }`}
                    >
                      <span className="line-clamp-1 text-[12px] font-extrabold leading-snug">
                        {idx + 1}. {step}
                      </span>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>

          {showExecutionDetailPanel ? (
            <div className="relative flex h-full min-h-0 flex-1 flex-col overflow-hidden rounded-xl bg-[#1e293b] p-4 shadow-inner">
              <div className="mb-2 flex shrink-0 items-center justify-between border-b border-slate-700 pb-2">
                <div className="flex items-center gap-2 text-[10px] font-extrabold uppercase tracking-widest text-slate-400">
                  <Cpu size={12} className="text-emerald-400" />
                  <span>执行详情</span>
                </div>
                {!isTaskCompleted ? (
                  <span className="flex items-center gap-1.5 text-[10px] font-extrabold text-emerald-400">
                    <span className="h-1.5 w-1.5 animate-ping rounded-full bg-emerald-400" />
                    运行中
                  </span>
                ) : null}
              </div>

              <div className="custom-scrollbar flex flex-1 flex-col space-y-2.5 overflow-y-auto pb-2 pr-1 font-mono text-[11px]">
                {executionLogs.map((log, i) => (
                  <div
                    key={`${i}-${log.text}`}
                    className={`flex animate-in fade-in slide-in-from-bottom-1 items-start gap-2 ${
                      log.active
                        ? 'font-bold text-emerald-400'
                        : log.type === 'success'
                          ? 'text-blue-400'
                          : log.type === 'warning'
                            ? 'text-amber-400'
                            : 'text-slate-400'
                    }`}
                  >
                    <span className="mt-0.5 select-none opacity-50">{`>`}</span>
                    <span className="flex-1 whitespace-pre-wrap leading-relaxed">{log.text}</span>
                    {log.active ? (
                      <span className="ml-1 mt-0.5 inline-block h-3 w-1.5 shrink-0 animate-pulse bg-emerald-400 align-middle" />
                    ) : null}
                  </div>
                ))}
                <div className="mt-auto" />
              </div>
            </div>
          ) : null}
        </div>
      ) : null}

      {!isTaskCompleted ? (
        <div className="h-0.5 w-full shrink-0 bg-slate-100">
          <div
            className="h-full bg-blue-600 transition-all duration-300"
            style={{ width: `${job.progress}%` }}
          />
        </div>
      ) : null}

      {isTaskCompleted && job.generatedDocument ? (
        <div className="border-t border-slate-200 bg-white px-4 py-4 sm:px-5">
          <p className="mb-2.5 text-[11px] font-extrabold uppercase tracking-wide text-slate-400">
            执行结果
          </p>
          <SearchReportResultCard
            document={job.generatedDocument}
            variant={reportResultCardVariant}
            onOpen={onOpenDocument}
          />
        </div>
      ) : null}
    </div>
  );
};

export default SearchReportExecutionPanel;
