import React from 'react';
import type { RegulatoryReviewMemo, RegulatorySeverity } from './mockReviewMemo';

type Props = {
  memo: RegulatoryReviewMemo;
};

const SEVERITY_STYLE: Record<
  RegulatorySeverity,
  { badge: string; cell: string }
> = {
  高: { badge: 'bg-red-50 text-red-700 ring-red-200', cell: 'text-red-700' },
  中: { badge: 'bg-amber-50 text-amber-700 ring-amber-200', cell: 'text-amber-700' },
  低: { badge: 'bg-slate-50 text-slate-600 ring-slate-200', cell: 'text-slate-600' },
};

function SectionHeading({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="mb-3 mt-9 border-b border-slate-200 pb-2 text-[16px] font-extrabold tracking-wide text-slate-900 first:mt-0">
      {children}
    </h2>
  );
}

function MetaRow({ label, value }: { label: string; value: string }) {
  return (
    <tr>
      <td className="w-[112px] border border-slate-200 bg-slate-50 px-3 py-2.5 text-[12.5px] font-extrabold text-slate-600">
        {label}
      </td>
      <td className="border border-slate-200 px-3 py-2.5 text-[13px] font-medium leading-relaxed text-slate-800">
        {value}
      </td>
    </tr>
  );
}

/**
 * 制度合规审查交付物预览：模拟 Word 审查备忘录版式
 * （封面元信息表 + 分节正文 + 问题清单表 + 建议条款）
 */
export default function RegulatoryReviewMemoPreview({ memo }: Props) {
  return (
    <div className="w-full max-w-[860px] shrink-0">
      <article className="min-h-[1100px] rounded-sm border border-gray-200 bg-white px-10 py-12 shadow-md sm:px-14 sm:py-14 lg:px-16 lg:py-16">
        {/* 封面标题 */}
        <header className="mb-8 text-center">
          <h1 className="text-[20px] font-extrabold leading-snug tracking-wide text-slate-900 sm:text-[22px]">
            {memo.documentTitle}
          </h1>
          <p className="mt-2 text-[18px] font-extrabold tracking-[0.12em] text-sky-700">
            {memo.subtitle}
          </p>
        </header>

        {/* 元信息表 */}
        <table className="mb-2 w-full border-collapse">
          <tbody>
            <MetaRow label="审查日期" value={memo.reviewDate} />
            <MetaRow label="审查结论" value={memo.conclusion} />
            <MetaRow label="风险概览" value={memo.riskSummary} />
            <MetaRow label="审查范围" value={memo.reviewScope} />
            <MetaRow label="来源状态" value={memo.sourceStatus} />
          </tbody>
        </table>

        <SectionHeading>审查备注</SectionHeading>
        <p className="text-[13.5px] font-medium leading-[1.9] text-slate-700">{memo.reviewNotes}</p>

        <SectionHeading>总体结论</SectionHeading>
        <p className="rounded-lg border border-sky-100 bg-sky-50/60 px-4 py-3 text-[13.5px] font-bold leading-[1.9] text-slate-800">
          {memo.overallConclusion}
        </p>

        <SectionHeading>关键风险</SectionHeading>
        <ol className="list-decimal space-y-2 pl-5 text-[13.5px] font-medium leading-[1.85] text-slate-700">
          {memo.keyRisks.map((risk, index) => (
            <li key={index} className="pl-1">
              {risk}
            </li>
          ))}
        </ol>

        <SectionHeading>问题清单</SectionHeading>
        <div className="overflow-x-auto rounded-lg border border-slate-200">
          <table className="w-full min-w-[720px] border-collapse text-left">
            <thead>
              <tr className="bg-slate-50">
                {['优先级', '条款/命中原文', '风险说明', '法律依据', '修改建议'].map((h) => (
                  <th
                    key={h}
                    className="border-b border-slate-200 px-2.5 py-2.5 text-[11px] font-extrabold tracking-wide text-slate-500"
                  >
                    {h}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {memo.issues.map((issue) => {
                const style = SEVERITY_STYLE[issue.severity];
                return (
                  <tr
                    key={issue.id}
                    className="align-top hover:bg-slate-50/70"
                  >
                    <td className="border-b border-slate-100 px-2.5 py-3">
                      <span
                        className={`inline-flex rounded-md px-1.5 py-0.5 text-[11px] font-extrabold ring-1 ${style.badge}`}
                      >
                        {issue.severity}
                      </span>
                    </td>
                    <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold leading-relaxed text-slate-800">
                      {issue.clauseHit}
                    </td>
                    <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium leading-relaxed text-slate-600">
                      {issue.riskDetail}
                    </td>
                    <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium leading-relaxed text-slate-500">
                      {issue.legalBasis}
                    </td>
                    <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium leading-relaxed text-slate-700">
                      {issue.suggestion}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        </div>

        <SectionHeading>建议条款</SectionHeading>
        <div className="space-y-4">
          {memo.suggestedClauses.map((clause) => (
            <div
              key={clause.id}
              className="overflow-hidden rounded-xl border border-slate-200"
            >
              <div className="border-b border-sky-100 bg-sky-50/70 px-4 py-2.5 text-[13px] font-extrabold text-sky-800">
                {clause.title}
              </div>
              <p className="px-4 py-3.5 text-[13px] font-medium leading-[1.9] text-slate-700">
                {clause.body}
              </p>
            </div>
          ))}
        </div>

        <SectionHeading>待确认事项与发布门槛</SectionHeading>
        <ol className="list-decimal space-y-2 pl-5 text-[13.5px] font-medium leading-[1.85] text-slate-700">
          {memo.pendingItems.map((item, index) => (
            <li key={index} className="pl-1">
              {item}
            </li>
          ))}
        </ol>

        <SectionHeading>本次主要依据</SectionHeading>
        <p className="text-[12.5px] font-medium leading-[1.9] text-slate-600">
          {memo.mainReferences}
        </p>
      </article>
    </div>
  );
}
