export default function CivilCaseAnalysisModal({
  open,
  onClose,
  sources = [],
  conclusions = [],
  onStartReport,
}: CivilCaseAnalysisModalProps) {
  const materialsPanelRef = useRef<HTMLDivElement>(null);
  const [caseInfoTab, setCaseInfoTab] = useState<CaseInfoTab>('manual');
  const [caseInfoText, setCaseInfoText] = useState('');
  const [caseInfoWorkspaceFile, setCaseInfoWorkspaceFile] = useState<WorkspaceFileSelection | null>(null);
  const [direction, setDirection] = useState<AnalysisDirection[]>(['full']);
  const [materialSelections, setMaterialSelections] = useState<WorkspaceFileSelection[]>([]);
  const [materialsPanelOpen, setMaterialsPanelOpen] = useState(false);

  const allMaterialFiles = useMemo(() => {
    const fromSources = sources.filter(isDesensitizableSource).map((s) => ({
      origin: 'source' as const,
      id: s.id,
      title: s.title,
    }));
    const fromConclusions = conclusions.filter(isDesensitizableConclusion).map((c) => ({
      origin: 'conclusion' as const,
      id: c.id,
      title: c.title,
    }));
    return [...fromSources, ...fromConclusions];
  }, [sources, conclusions]);

  useEffect(() => {
    if (!open) return;
    setCaseInfoTab('manual');
    setCaseInfoText('');
    setCaseInfoWorkspaceFile(null);
    setDirection(['full']);
    setMaterialSelections(allMaterialFiles);
    setMaterialsPanelOpen(false);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  useEffect(() => {
    if (!materialsPanelOpen) return;
    const onPointerDown = (e: MouseEvent) => {
      if (materialsPanelRef.current && !materialsPanelRef.current.contains(e.target as Node)) {
        setMaterialsPanelOpen(false);
      }
    };
    document.addEventListener('mousedown', onPointerDown);
    return () => document.removeEventListener('mousedown', onPointerDown);
  }, [materialsPanelOpen]);

  const materialsAllSelected =
    allMaterialFiles.length > 0 && allMaterialFiles.every((f) => isMaterialSelected(f));
  const materialsSomeSelected =
    !materialsAllSelected && allMaterialFiles.some((f) => isMaterialSelected(f));

  const scopeLabel =
    direction.length === 0
      ? '全流程分析'
      : direction.map((d) => DIRECTION_LABELS[d]).join(' / ');

  if (!open) return null;

  function isMaterialSelected(file: WorkspaceFileSelection): boolean {
    return materialSelections.some((s) => isSameWorkspaceSelection(s, file));
  }

  const toggleDirection = (key: AnalysisDirection) => {
    setDirection((prev) => {
      if (key === 'full') return ['full'];
      const rest = prev.filter((d) => d !== 'full');
      if (rest.includes(key)) {
        // 已选中：多于一个时可取消该项；只剩一个时保留，保证至少一项处于选中
        return rest.length > 1 ? rest.filter((d) => d !== key) : rest;
      }
      return [...rest, key];
    });
  };

  const handleCaseInfoWorkspaceToggle = (file: WorkspaceFileSelection) => {
    if (caseInfoWorkspaceFile && isSameWorkspaceSelection(caseInfoWorkspaceFile, file)) {
      setCaseInfoWorkspaceFile(null);
      return;
    }
    setCaseInfoWorkspaceFile(file);
  };

  const handleMaterialToggle = (file: WorkspaceFileSelection) => {
    setMaterialSelections((prev) =>
      prev.some((s) => isSameWorkspaceSelection(s, file))
        ? prev.filter((s) => !isSameWorkspaceSelection(s, file))
        : [...prev, file]
    );
  };

  const handleMaterialSelectAll = () => {
    if (materialsAllSelected) setMaterialSelections([]);
    else setMaterialSelections(allMaterialFiles);
  };

  const handleStart = () => {
    onStartReport({
      direction: submitDirection,
      materials: materialSelections,
      caseInfoText: caseInfoTab === 'manual' ? caseInfoText : '',
      caseInfoWorkspaceFile: caseInfoTab === 'workspace' ? caseInfoWorkspaceFile : undefined,
      caseInfoSource: caseInfoTab === 'workspace' ? 'workspace' : 'manual',
      searchScope: 'all',
    });
  };

  const submitDirection: AnalysisDirection[] = direction.length > 0 ? direction : ['full'];

  return (
    <div
      className="fixed inset-0 z-[600] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="flex h-[720px] max-h-[86vh] w-[980px] flex-col overflow-hidden rounded-[32px] bg-white shadow-2xl animate-in zoom-in-95 font-bold"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="z-10 flex shrink-0 items-center justify-between border-b border-gray-100 bg-white p-6">
          <div className="flex items-center gap-3">
            <div className="rounded-xl bg-orange-50 p-2 text-orange-600">
              <Gavel size={24} strokeWidth={2.5} />
            </div>
            <div>
              <h3 className="text-xl font-extrabold text-slate-800">案件研究</h3>
              <p className="mt-0.5 text-[12px] font-bold text-slate-400">
                描述案情信息并选择分析范围，案件材料可从工作空间勾选（可不选）
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-full bg-slate-50 p-2 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
          >
            <X size={20} />
          </button>
        </div>

        <div className="custom-scrollbar flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto px-6 py-5">
          {/* 1. 案情信息 */}
          <section className="shrink-0">
            <div className="mb-2.5 flex items-center justify-between gap-3">
              <h4 className="text-[14px] font-extrabold text-slate-800">
                案情信息 <span className="text-orange-500">*</span>
              </h4>
              <div className="flex items-center rounded-xl border border-slate-200 bg-slate-50/80 p-1">
                <button
                  type="button"
                  onClick={() => setCaseInfoTab('manual')}
                  className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-[12px] font-bold transition-colors ${
                    caseInfoTab === 'manual' ? 'bg-white text-orange-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <FileText size={14} strokeWidth={2.5} />
                  手动输入
                </button>
                <button
                  type="button"
                  onClick={() => setCaseInfoTab('workspace')}
                  className={`inline-flex items-center gap-1.5 rounded-lg px-3 py-2 text-[12px] font-bold transition-colors ${
                    caseInfoTab === 'workspace' ? 'bg-white text-orange-700 shadow-sm' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <FolderOpen size={14} strokeWidth={2.5} />
                  工作空间文件
                </button>
              </div>
            </div>

            {caseInfoTab === 'manual' ? (
              <div className="flex h-[300px] flex-col overflow-hidden rounded-2xl border border-slate-200 bg-white">
                <textarea
                  value={caseInfoText}
                  onChange={(e) => {
                    if (e.target.value.length > MAX_CASE_INFO_CHARS) return;
                    setCaseInfoText(e.target.value);
                  }}
                  placeholder={CASE_INFO_PLACEHOLDER}
                  className="min-h-0 flex-1 w-full resize-none bg-transparent px-4 py-3 text-[13px] font-medium leading-relaxed text-slate-800 outline-none placeholder:text-slate-300"
                />
                <div className="flex shrink-0 items-center justify-between border-t border-slate-100 bg-slate-50/60 px-3 py-2">
                  <button
                    type="button"
                    onClick={() => setCaseInfoText(SAMPLE_CASE_INFO)}
                    className="inline-flex items-center gap-1.5 text-[12px] font-bold text-orange-600 hover:underline"
                  >
                    <Sparkles size={13} strokeWidth={2.5} />
                    查看样例
                  </button>
                  <div className="flex items-center gap-3 text-[12px] font-medium text-slate-400">
                    <span>
                      {caseInfoText.length} / {MAX_CASE_INFO_CHARS}
                    </span>
                    <button
                      type="button"
                      onClick={() => setCaseInfoText('')}
                      className="inline-flex items-center gap-1 text-slate-500 hover:text-slate-700"
                    >
                      <X size={13} strokeWidth={2.5} />
                      清空
                    </button>
                  </div>
                </div>
              </div>
            ) : (
              <div className="flex h-[300px] flex-col">
                <div className="min-h-0 flex-1">
                  <WorkspaceFilePicker
                    sources={sources}
                    conclusions={conclusions}
                    selected={caseInfoWorkspaceFile ? [caseInfoWorkspaceFile] : []}
                    onToggle={handleCaseInfoWorkspaceToggle}
                    accent="rose"
                    selectableCountLabel="可作为案情信息的文件"
                    emptySourcesText="暂无可选的来源文件（仅支持已就绪的文档类文件）"
                    emptyConclusionsText="暂无可选的生成结果（仅支持已完成的结果）"
                  />
                </div>
                <p className="mt-1.5 shrink-0 text-[11px] font-medium text-slate-400">
                  从工作空间选择 1 份文件作为案情信息，便于复用已有起诉状、案情摘要或证据目录。
                </p>
              </div>
            )}
          </section>

          {/* 2. 分析范围 */}
          <section className="shrink-0">
            <h4 className="mb-2.5 text-[14px] font-extrabold text-slate-800">分析范围</h4>
            <div className="grid grid-cols-2 gap-2.5 lg:grid-cols-4">
              {DIRECTION_OPTIONS.map((opt) => {
                const selected = direction.includes(opt.key);
                return (
                  <button
                    key={opt.key}
                    type="button"
                    onClick={() => toggleDirection(opt.key)}
                    className={`rounded-2xl border px-3.5 py-3 text-left transition-all ${
                      selected
                        ? 'border-orange-300 bg-orange-50/70 shadow-sm'
                        : 'border-slate-200 bg-white hover:border-orange-200 hover:bg-orange-50/40'
                    }`}
                  >
                    <div className="flex items-center justify-between gap-2">
                      <span className={`text-[14px] font-extrabold ${selected ? 'text-orange-700' : 'text-slate-700'}`}>
                        {opt.label}
                      </span>
                      {opt.key === 'full' ? (
                        <Sparkles size={14} className="text-orange-500" strokeWidth={2.5} />
                      ) : (
                        <Target size={14} className="text-slate-400" strokeWidth={2.5} />
                      )}
                    </div>
                    <p className="mt-1 text-[11px] font-medium leading-relaxed text-slate-500">{opt.desc}</p>
                  </button>
                );
              })}
            </div>
          </section>
        </div>

        <div className="flex shrink-0 items-center justify-end gap-3 border-t border-slate-100 bg-white px-6 py-4">
          <p className="mr-auto text-[12px] font-medium text-slate-400">分析范围：{scopeLabel}</p>

          <div ref={materialsPanelRef} className="relative">
            <button
              type="button"
              onClick={() => setMaterialsPanelOpen((v) => !v)}
              className={`inline-flex items-center gap-1.5 rounded-2xl border px-4 py-2.5 text-[13px] font-bold transition-all ${
                materialsPanelOpen
                  ? 'border-orange-200 bg-orange-50 text-orange-700'
                  : 'border-slate-200 bg-white text-slate-600 hover:border-orange-200 hover:bg-orange-50/60 hover:text-orange-700'
              }`}
            >
              <Library size={15} strokeWidth={2.5} />
              案件材料
              {materialSelections.length > 0 ? (
                <span className="rounded-md bg-orange-100 px-1.5 py-0.5 text-[11px] font-extrabold text-orange-700">
                  {materialSelections.length}
                </span>
              ) : null}
              <ChevronDown
                size={14}
                strokeWidth={2.5}
                className={`transition-transform ${materialsPanelOpen ? 'rotate-180' : ''}`}
              />
            </button>

            {materialsPanelOpen ? (
              <div
                className="absolute bottom-full right-0 z-[80] mb-2 w-[300px] overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-xl animate-in fade-in zoom-in-95 origin-bottom-right"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="flex items-center justify-between gap-2 border-b border-orange-50 bg-orange-50/70 px-3 py-2">
                  <span className="text-[12px] font-bold text-orange-700/80">来源文件（默认全选）</span>
                  <button
                    type="button"
                    disabled={allMaterialFiles.length === 0}
                    onClick={handleMaterialSelectAll}
                    className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border transition-colors ${
                      allMaterialFiles.length === 0
                        ? 'cursor-not-allowed border-slate-200 bg-slate-50'
                        : materialsAllSelected
                          ? 'border-orange-600 bg-orange-600 text-white'
                          : materialsSomeSelected
                            ? 'border-orange-600 bg-orange-100 text-orange-600'
                            : 'border-slate-300 bg-white hover:border-orange-400'
                    }`}
                    aria-label={materialsAllSelected ? '取消全选' : '全选'}
                    title={materialsAllSelected ? '取消全选' : '全选'}
                  >
                    {materialsAllSelected ? (
                      <Check size={10} strokeWidth={3} />
                    ) : materialsSomeSelected ? (
                      <span className="h-0.5 w-2 rounded-full bg-orange-600" />
                    ) : null}
                  </button>
                </div>
                <div className="custom-scrollbar max-h-[320px] overflow-y-auto px-1.5 pb-1.5">
                  {allMaterialFiles.length === 0 ? (
                    <div className="px-2 py-5 text-center text-[11px] font-medium text-slate-400">
                      暂无来源文件
                    </div>
                  ) : (
                    <div className="space-y-0.5">
                      {allMaterialFiles.map((file) => {
                        const selected = isMaterialSelected(file);
                        return (
                          <button
                            key={`${file.origin}-${file.id}`}
                            type="button"
                            onClick={() => handleMaterialToggle(file)}
                            className={`flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-slate-600 transition-colors ${
                              selected ? 'bg-orange-50/70' : 'hover:bg-slate-50'
                            }`}
                          >
                            <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-lg bg-slate-50 text-slate-500">
                              {file.origin === 'conclusion' ? (
                                <Sparkles size={13} strokeWidth={2.5} />
                              ) : (
                                <FileText size={13} strokeWidth={2.5} />
                              )}
                            </span>
                            <span className="min-w-0 flex-1">
                              <span className="block truncate text-[12px] font-bold text-slate-700">{file.title}</span>
                              <span className="block truncate text-[10px] font-medium text-slate-400">
                                {fileSubtitle(file)}
                              </span>
                            </span>
                            <span
                              className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border ${
                                selected ? 'border-orange-600 bg-orange-600 text-white' : 'border-slate-300 bg-white'
                              }`}
                              aria-hidden
                            >
                              {selected ? <Check size={10} strokeWidth={3} /> : null}
                            </span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
              </div>
            ) : null}
          </div>

          <button
            type="button"
            onClick={handleStart}
            className="rounded-2xl px-6 py-2.5 text-[13px] font-bold transition-all bg-orange-600 text-white shadow-lg shadow-orange-200 hover:bg-orange-700 active:scale-95"
          >
            开始分析
          </button>
        </div>
      </div>
    </div>
  );
}
