import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import {
  ArrowLeft,
  Check,
  ChevronDown,
  Edit3,
  FileText,
  FolderOpen,
  FolderUp,
  Library,
  Link as LinkIcon,
  Settings,
  ShieldCheck,
  Trash2,
  X,
} from 'lucide-react';
import WorkspaceFilePicker, {
  isSameWorkspaceSelection,
  type WorkspaceFileSelection,
  type WorkspacePickerConclusion,
  type WorkspacePickerSource,
} from '../Desensitize/WorkspaceFilePicker';
import type {
  ContractReviewStartPayload,
  ReviewBasisItem,
  ReviewTarget,
} from './contractReviewTypes';
import PlaybookOnboardingWizard from './PlaybookOnboardingWizard';
import {
  ContractPlaybook,
  DEFAULT_PLAYBOOK,
  createPlaybookFromAnswers,
  hasAnyAnswer,
  loadDefaultPlaybook,
  loadPlaybooks,
  loadPreferredPlaybookId,
  markOnboardingSeen,
  saveDefaultPlaybookAnswers,
  savePlaybooks,
  savePreferredPlaybookId,
  snapshotPlaybook,
  updatePlaybookFromAnswers,
} from './playbookOnboarding';

type ModalStep = 'main' | 'onboarding' | 'edit' | 'default-settings';
type UploadTab = 'local' | 'workspace';

type ContractRiskModalProps = {
  open: boolean;
  onClose: () => void;
  sources?: WorkspacePickerSource[];
  conclusions?: WorkspacePickerConclusion[];
  onStartReview: (payload: ContractReviewStartPayload) => void;
};

const MAX_TARGETS = 1;
const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024;
const ACCEPT_EXTENSIONS = ['.doc', '.docx'] as const;
const ACCEPT_ATTR = ACCEPT_EXTENSIONS.join(',');
/** 有文件后上传区高度回退值（与智能脱敏一致） */
const UPLOAD_SECTION_HEIGHT_FALLBACK = 360;
/** 空态上传区最小高度，避免矮视口下图标/文案被挤压 */
const UPLOAD_SECTION_MIN_HEIGHT = 220;

function workspaceTargetKey(selection: WorkspaceFileSelection): string {
  return `workspace:${selection.origin}:${selection.id}`;
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function getFileExtension(name: string): string {
  const idx = name.lastIndexOf('.');
  return idx >= 0 ? name.slice(idx).toLowerCase() : '';
}

function validateLocalFile(file: File): string | null {
  const ext = getFileExtension(file.name);
  if (!ACCEPT_EXTENSIONS.includes(ext as (typeof ACCEPT_EXTENSIONS)[number])) {
    return '仅支持 doc、docx 格式';
  }
  if (file.size > MAX_FILE_SIZE_BYTES) return '单个文件不超过 10M';
  return null;
}

function targetTitle(t: ReviewTarget): string {
  return t.kind === 'local' ? t.name : t.selection.title;
}

function targetSourceLabel(t: ReviewTarget): string {
  if (t.kind === 'local') return '本地文件';
  return t.selection.origin === 'source' ? '工作空间 · 来源文件' : '工作空间 · 生成结果';
}

function targetFormat(t: ReviewTarget): string {
  if (t.kind === 'local') {
    const ext = getFileExtension(t.name).replace('.', '').toUpperCase();
    return ext || 'FILE';
  }
  return (t.fileType || 'FILE').toUpperCase();
}

function buildDefaultBasis(sources: WorkspacePickerSource[]): ReviewBasisItem[] {
  // 审查依据不限格式：所有已勾选来源均默认纳入（含链接/法宝等）
  return sources
    .filter((s) => (s as { checked?: boolean }).checked)
    .map((s) => ({
      key: workspaceTargetKey({ origin: 'source', id: s.id, title: s.title }),
      selection: { origin: 'source' as const, id: s.id, title: s.title },
      fileType: s.type,
      status: s.status || 'ready',
    }));
}

function basisSourceIcon(type: string | undefined) {
  if (type === 'url' || type === 'fb') {
    return <LinkIcon size={14} strokeWidth={2} className="shrink-0 text-slate-400" />;
  }
  return <FileText size={14} strokeWidth={2} className="shrink-0 text-slate-400" />;
}

export default function ContractRiskModal({
  open,
  onClose,
  sources = [],
  conclusions = [],
  onStartReview,
}: ContractRiskModalProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const uploadTabListRef = useRef<HTMLDivElement>(null);
  const localTabRef = useRef<HTMLButtonElement>(null);
  const workspaceTabRef = useRef<HTMLButtonElement>(null);
  const uploadSectionRef = useRef<HTMLElement>(null);
  const basisPanelRef = useRef<HTMLDivElement>(null);

  const [step, setStep] = useState<ModalStep>('main');
  const [activeTab, setActiveTab] = useState<UploadTab>('local');
  const [tabPillStyle, setTabPillStyle] = useState({ left: 4, width: 0 });
  const [pendingTargets, setPendingTargets] = useState<ReviewTarget[]>([]);
  const [basisItems, setBasisItems] = useState<ReviewBasisItem[]>([]);
  const [basisPanelOpen, setBasisPanelOpen] = useState(false);
  const [uploadSectionHeight, setUploadSectionHeight] = useState<number | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [basisError, setBasisError] = useState<string | null>(null);

  const [playbooks, setPlaybooks] = useState<ContractPlaybook[]>([]);
  const [defaultPlaybook, setDefaultPlaybook] = useState<ContractPlaybook>(() => loadDefaultPlaybook());
  const [selectedPlaybookId, setSelectedPlaybookId] = useState(DEFAULT_PLAYBOOK.id);
  const [editingPlaybookId, setEditingPlaybookId] = useState<string | null>(null);
  const [playbookToDelete, setPlaybookToDelete] = useState<ContractPlaybook | null>(null);

  useEffect(() => {
    if (!open) return;
    const saved = loadPlaybooks();
    const defaultPb = loadDefaultPlaybook();
    setPlaybooks(saved);
    setDefaultPlaybook(defaultPb);
    setStep('main');
    setActiveTab('local');
    setPendingTargets([]);
    setBasisItems(buildDefaultBasis(sources));
    setBasisPanelOpen(false);
    setUploadSectionHeight(null);
    setIsDragging(false);
    setUploadError(null);
    setBasisError(null);
    setEditingPlaybookId(null);
    setPlaybookToDelete(null);

    const preferred = loadPreferredPlaybookId();
    const preferredExists =
      preferred === DEFAULT_PLAYBOOK.id || saved.some((p) => p.id === preferred);
    setSelectedPlaybookId(preferredExists ? preferred : DEFAULT_PLAYBOOK.id);
    // 仅在打开时初始化；打开后 sources 变化不重置用户已选内容
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  useLayoutEffect(() => {
    if (!open || step !== 'main') return;
    const list = uploadTabListRef.current;
    const activeBtn = activeTab === 'local' ? localTabRef.current : workspaceTabRef.current;
    if (!list || !activeBtn) return;
    const listRect = list.getBoundingClientRect();
    const btnRect = activeBtn.getBoundingClientRect();
    setTabPillStyle({
      left: btnRect.left - listRect.left,
      width: btnRect.width,
    });
  }, [open, step, activeTab]);

  const remainingSlots = MAX_TARGETS - pendingTargets.length;
  const atCapacity = remainingSlots <= 0;
  /** 默认空态一屏展示；有待审查文件后改为整页滚动（与脱敏一致） */
  const isEmptyState = pendingTargets.length === 0;

  // 与脱敏一致：空态 flex-1 测高，有文件后锁定该高度，避免上传区变矮/空态微小溢出滚动
  useLayoutEffect(() => {
    if (!open || step !== 'main' || !isEmptyState) return;
    const el = uploadSectionRef.current;
    if (!el) return;
    const measure = () => {
      const h = Math.round(el.getBoundingClientRect().height);
      if (h > 0) setUploadSectionHeight(Math.max(h, UPLOAD_SECTION_MIN_HEIGHT));
    };
    measure();
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(measure) : null;
    ro?.observe(el);
    window.addEventListener('resize', measure);
    return () => {
      ro?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, [open, step, isEmptyState, activeTab]);

  useEffect(() => {
    if (!basisPanelOpen) return;
    const onPointerDown = (e: MouseEvent) => {
      if (basisPanelRef.current && !basisPanelRef.current.contains(e.target as Node)) {
        setBasisPanelOpen(false);
      }
    };
    document.addEventListener('mousedown', onPointerDown);
    return () => document.removeEventListener('mousedown', onPointerDown);
  }, [basisPanelOpen]);

  const workspaceSelections = useMemo(
    () =>
      pendingTargets
        .filter((t): t is Extract<ReviewTarget, { kind: 'workspace' }> => t.kind === 'workspace')
        .map((t) => t.selection),
    [pendingTargets]
  );

  /** 审查依据：展示全部工作空间来源，不限制格式 */
  const basisSourceOptions = sources;

  const visibleBasis = useMemo(
    () =>
      basisItems.filter(
        (b) =>
          b.selection.origin === 'source' &&
          !pendingTargets.some(
            (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, b.selection)
          )
      ),
    [basisItems, pendingTargets]
  );

  /** 可勾选为依据的来源（排除已在待审查对象中的） */
  const selectableBasisSources = useMemo(
    () =>
      basisSourceOptions.filter(
        (source) =>
          !pendingTargets.some(
            (t) =>
              t.kind === 'workspace' &&
              isSameWorkspaceSelection(t.selection, {
                origin: 'source',
                id: source.id,
                title: source.title,
              })
          )
      ),
    [basisSourceOptions, pendingTargets]
  );

  const basisAllSelected =
    selectableBasisSources.length > 0 &&
    selectableBasisSources.every((source) =>
      basisItems.some(
        (b) =>
          b.selection.origin === 'source' &&
          String(b.selection.id) === String(source.id)
      )
    );
  const basisSomeSelected =
    !basisAllSelected &&
    selectableBasisSources.some((source) =>
      basisItems.some(
        (b) =>
          b.selection.origin === 'source' &&
          String(b.selection.id) === String(source.id)
      )
    );

  const editingPlaybook = playbooks.find((p) => p.id === editingPlaybookId) || null;
  const canStart = pendingTargets.length > 0 && !!selectedPlaybookId;

  if (!open) return null;

  const persistPlaybooks = (next: ContractPlaybook[]) => {
    setPlaybooks(next);
    savePlaybooks(next);
  };

  const switchTab = (tab: UploadTab) => {
    setActiveTab(tab);
    setUploadError(null);
    setIsDragging(false);
  };

  const addLocalFiles = (fileList: FileList | File[]) => {
    const files = Array.from(fileList);
    if (files.length === 0) return;
    const next = [...pendingTargets];
    let rejectedFormat = false;
    let rejectedSize = false;
    let rejectedCapacity = false;

    for (const file of files) {
      if (next.length >= MAX_TARGETS) {
        rejectedCapacity = true;
        break;
      }
      const error = validateLocalFile(file);
      if (error === '仅支持 doc、docx 格式') {
        rejectedFormat = true;
        continue;
      }
      if (error === '单个文件不超过 10M') {
        rejectedSize = true;
        continue;
      }
      const duplicated = next.some(
        (t) => t.kind === 'local' && t.name === file.name && t.size === file.size
      );
      if (duplicated) continue;
      next.push({
        key: `local:${file.name}:${file.size}:${file.lastModified}:${next.length}`,
        kind: 'local',
        name: file.name,
        size: file.size,
      });
    }

    if (rejectedCapacity) setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
    else if (rejectedFormat) setUploadError('仅支持 doc、docx 格式');
    else if (rejectedSize) setUploadError('单个文件不超过 10M');
    else setUploadError(null);
    setPendingTargets(next);
  };

  const handleDropZoneClick = () => {
    if (atCapacity) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    fileInputRef.current?.click();
  };

  const handleLocalFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files?.length) return;
    addLocalFiles(files);
    e.target.value = '';
  };

  const handleWorkspaceToggle = (file: WorkspaceFileSelection) => {
    const exists = pendingTargets.some(
      (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file)
    );
    if (exists) {
      setUploadError(null);
      setPendingTargets((prev) =>
        prev.filter(
          (t) => !(t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file))
        )
      );
      return;
    }
    if (pendingTargets.length >= MAX_TARGETS) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    const sourceMeta = sources.find((s) => String(s.id) === String(file.id) && file.origin === 'source');
    const conclusionMeta = conclusions.find(
      (c) => String(c.id) === String(file.id) && file.origin === 'conclusion'
    );
    setPendingTargets((prev) => [
      ...prev,
      {
        key: workspaceTargetKey(file),
        kind: 'workspace',
        selection: file,
        fileType: sourceMeta?.type || conclusionMeta?.type,
        status: sourceMeta?.status || conclusionMeta?.status || 'ready',
      },
    ]);
    // 不从 basisItems 移除：展示/提交侧用 visibleBasis 排除待审查对象。
    // 这样从待审查对象移除后，默认带入或用户已勾选的依据会自动恢复；
    // 用户曾主动取消的依据仍保持未选。
  };

  const removePendingTarget = (key: string) => {
    setPendingTargets((prev) => prev.filter((t) => t.key !== key));
    setUploadError(null);
  };

  const handleBasisToggle = (file: WorkspaceFileSelection) => {
    if (file.origin !== 'source') return;
    const inTargets = pendingTargets.some(
      (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file)
    );
    if (inTargets) {
      setBasisError('该文件已在待审查对象中，不能作为审查依据');
      return;
    }
    const exists = basisItems.some((b) => isSameWorkspaceSelection(b.selection, file));
    if (exists) {
      setBasisError(null);
      setBasisItems((prev) => prev.filter((b) => !isSameWorkspaceSelection(b.selection, file)));
      return;
    }
    setBasisError(null);
    const sourceMeta = sources.find((s) => String(s.id) === String(file.id));
    setBasisItems((prev) => [
      ...prev,
      {
        key: workspaceTargetKey(file),
        selection: { ...file, origin: 'source' },
        fileType: sourceMeta?.type,
        status: sourceMeta?.status || 'ready',
      },
    ]);
  };

  const handleBasisSelectAll = () => {
    setBasisError(null);
    if (selectableBasisSources.length === 0) return;
    if (basisAllSelected) {
      const selectableIds = new Set(selectableBasisSources.map((s) => String(s.id)));
      setBasisItems((prev) =>
        prev.filter(
          (b) => !(b.selection.origin === 'source' && selectableIds.has(String(b.selection.id)))
        )
      );
      return;
    }
    setBasisItems((prev) => {
      const next = [...prev];
      for (const source of selectableBasisSources) {
        const selection: WorkspaceFileSelection = {
          origin: 'source',
          id: source.id,
          title: source.title,
        };
        const exists = next.some((b) => isSameWorkspaceSelection(b.selection, selection));
        if (exists) continue;
        next.push({
          key: workspaceTargetKey(selection),
          selection,
          fileType: source.type,
          status: source.status || 'ready',
        });
      }
      return next;
    });
  };

  const startEditPlaybook = (e: React.MouseEvent, pb: ContractPlaybook) => {
    e.stopPropagation();
    setEditingPlaybookId(pb.id);
    setStep('edit');
  };

  const openDefaultPlaybookSettings = (e: React.MouseEvent) => {
    e.stopPropagation();
    setEditingPlaybookId(null);
    setStep('default-settings');
  };

  const goMain = () => {
    setStep('main');
    setEditingPlaybookId(null);
    setBasisPanelOpen(false);
    setBasisError(null);
  };

  const handleCreateComplete = (answers: Parameters<typeof createPlaybookFromAnswers>[0]) => {
    markOnboardingSeen();
    if (!hasAnyAnswer(answers)) {
      goMain();
      return;
    }
    const pb = createPlaybookFromAnswers(answers);
    persistPlaybooks([pb, ...playbooks]);
    setSelectedPlaybookId(pb.id);
    savePreferredPlaybookId(pb.id);
    goMain();
  };

  const handleEditComplete = (answers: Parameters<typeof updatePlaybookFromAnswers>[1]) => {
    if (!editingPlaybookId) {
      goMain();
      return;
    }
    const next = playbooks.map((pb) =>
      pb.id === editingPlaybookId ? updatePlaybookFromAnswers(pb, answers) : pb
    );
    persistPlaybooks(next);
    setSelectedPlaybookId(editingPlaybookId);
    savePreferredPlaybookId(editingPlaybookId);
    goMain();
  };

  const handleDefaultSettingsComplete = (answers: Parameters<typeof createPlaybookFromAnswers>[0]) => {
    saveDefaultPlaybookAnswers(answers);
    setDefaultPlaybook(loadDefaultPlaybook());
    setSelectedPlaybookId(DEFAULT_PLAYBOOK.id);
    savePreferredPlaybookId(DEFAULT_PLAYBOOK.id);
    goMain();
  };

  const confirmDeletePlaybook = () => {
    if (!playbookToDelete) return;
    const next = playbooks.filter((p) => p.id !== playbookToDelete.id);
    persistPlaybooks(next);
    if (selectedPlaybookId === playbookToDelete.id) {
      setSelectedPlaybookId(DEFAULT_PLAYBOOK.id);
      savePreferredPlaybookId(DEFAULT_PLAYBOOK.id);
    }
    setPlaybookToDelete(null);
  };

  const resolveSelectedPlaybook = (): ContractPlaybook => {
    if (selectedPlaybookId === DEFAULT_PLAYBOOK.id) return defaultPlaybook;
    return playbooks.find((p) => p.id === selectedPlaybookId) || defaultPlaybook;
  };

  const handleStartReview = () => {
    if (!canStart) return;
    const playbook = snapshotPlaybook(resolveSelectedPlaybook());
    savePreferredPlaybookId(selectedPlaybookId);
    const payload: ContractReviewStartPayload = {
      playbook,
      targets: pendingTargets.map((t) => ({
        key: t.key,
        title: targetTitle(t),
        sourceLabel:
          t.kind === 'local'
            ? `本地文件 · ${formatFileSize(t.size)}`
            : targetSourceLabel(t),
        format: targetFormat(t),
      })),
      basis: visibleBasis.map((b) => ({
        key: b.key,
        title: b.selection.title,
        sourceLabel: '工作空间 · 来源文件',
        format: (b.fileType || 'FILE').toUpperCase(),
      })),
    };
    onStartReview(payload);
  };

  const headerTitle =
    step === 'onboarding'
      ? '新建审查手册'
      : step === 'edit'
        ? '编辑审查手册'
        : step === 'default-settings'
          ? '默认审查手册'
          : '合同审查';

  const headerSub =
    step === 'onboarding'
      ? '配置审查立场与审查清单后生成手册'
      : step === 'edit'
        ? editingPlaybook?.name || '调整选项后保存配置'
        : step === 'default-settings'
          ? '配置默认审查立场与审查清单，保存后应用于自动审查'
          : '选择审查对象与审查手册，可选补充审查依据';

  const allPlaybooksForSelect: ContractPlaybook[] = [defaultPlaybook, ...playbooks];

  return (
    <div
      className="fixed inset-0 z-[600] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="flex h-[800px] max-h-[85vh] w-[960px] flex-col overflow-hidden rounded-[32px] bg-white shadow-2xl animate-in zoom-in-95 font-bold"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="z-10 flex shrink-0 items-center justify-between border-b border-gray-100 bg-white p-6">
          <div className="flex items-center gap-3">
            {step !== 'main' ? (
              <button
                type="button"
                onClick={goMain}
                className="-ml-2 mr-1 rounded-xl p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
              >
                <ArrowLeft size={20} strokeWidth={2.5} />
              </button>
            ) : null}
            <div className="rounded-xl bg-indigo-50 p-2 text-indigo-600">
              <ShieldCheck size={24} strokeWidth={2.5} />
            </div>
            <div>
              <h3 className="text-xl font-extrabold text-slate-800">{headerTitle}</h3>
              <p className="mt-0.5 text-[12px] font-bold text-slate-400">{headerSub}</p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-full bg-slate-50 p-2 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
          >
            <X size={20} />
          </button>
        </div>

        {step === 'onboarding' ? (
          <PlaybookOnboardingWizard
            mode="create"
            onCancel={goMain}
            onComplete={handleCreateComplete}
          />
        ) : null}

        {step === 'edit' && editingPlaybook ? (
          <PlaybookOnboardingWizard
            mode="edit"
            initialAnswers={editingPlaybook.answers || {}}
            onCancel={goMain}
            onComplete={handleEditComplete}
          />
        ) : null}

        {step === 'default-settings' ? (
          <PlaybookOnboardingWizard
            mode="edit"
            initialAnswers={defaultPlaybook.answers || {}}
            onCancel={goMain}
            onComplete={handleDefaultSettingsComplete}
          />
        ) : null}

        {step === 'main' ? (
          <>
            <div className="custom-scrollbar flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto px-6 py-5">
              {/* 1. 选择审查对象：空态 flex-1 + 最小高度；有文件后沿用空态测高（与脱敏一致） */}
              <section
                ref={uploadSectionRef}
                className={`flex flex-col ${isEmptyState ? 'min-h-0 flex-1' : 'shrink-0'}`}
                style={
                  !isEmptyState
                    ? { height: uploadSectionHeight || UPLOAD_SECTION_HEIGHT_FALLBACK }
                    : { minHeight: UPLOAD_SECTION_MIN_HEIGHT }
                }
              >
                <div className="mb-3 flex shrink-0 items-center justify-between gap-3">
                  <h4 className="text-[14px] font-extrabold text-slate-800">选择审查对象</h4>
                  <div
                    ref={uploadTabListRef}
                    className="relative flex items-center rounded-xl border border-slate-200 bg-slate-50/80 p-1"
                  >
                    <span
                      aria-hidden
                      className="pointer-events-none absolute bottom-1 top-1 rounded-lg bg-white shadow-sm transition-[left,width] duration-300 ease-out"
                      style={{ left: tabPillStyle.left, width: tabPillStyle.width }}
                    />
                    <button
                      ref={localTabRef}
                      type="button"
                      onClick={() => switchTab('local')}
                      className={`relative z-10 inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[12px] font-bold transition-colors ${
                        activeTab === 'local' ? 'text-indigo-700' : 'text-slate-500 hover:text-slate-700'
                      }`}
                    >
                      <FolderUp size={14} strokeWidth={2.5} />
                      本地上传
                    </button>
                    <button
                      ref={workspaceTabRef}
                      type="button"
                      onClick={() => switchTab('workspace')}
                      className={`relative z-10 inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[12px] font-bold transition-colors ${
                        activeTab === 'workspace'
                          ? 'text-indigo-700'
                          : 'text-slate-500 hover:text-slate-700'
                      }`}
                    >
                      <FolderOpen size={14} strokeWidth={2.5} />
                      工作空间文件
                    </button>
                  </div>
                </div>

                <div className="flex min-h-0 flex-1 flex-col">
                  {activeTab === 'local' ? (
                    <div className="flex min-h-0 flex-1 flex-col animate-in fade-in duration-200">
                      <div
                        role="button"
                        tabIndex={0}
                        onClick={handleDropZoneClick}
                        onKeyDown={(e) => {
                          if (e.key === 'Enter' || e.key === ' ') {
                            e.preventDefault();
                            handleDropZoneClick();
                          }
                        }}
                        onDragOver={(e) => {
                          e.preventDefault();
                          setIsDragging(true);
                        }}
                        onDragLeave={(e) => {
                          e.preventDefault();
                          setIsDragging(false);
                        }}
                        onDrop={(e) => {
                          e.preventDefault();
                          setIsDragging(false);
                          if (e.dataTransfer.files?.length) addLocalFiles(e.dataTransfer.files);
                        }}
                        className={`relative flex min-h-[180px] flex-1 cursor-pointer flex-col items-center justify-center rounded-2xl border border-dashed px-6 py-6 text-center transition-all ${
                          isDragging
                            ? 'border-indigo-400 bg-indigo-50/80 shadow-sm'
                            : 'border-slate-200 bg-gradient-to-b from-slate-50/80 to-white hover:border-indigo-300 hover:bg-indigo-50/40'
                        }`}
                      >
                        <div className="relative mb-3 flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-indigo-500 to-indigo-600 text-white shadow-md shadow-indigo-200">
                          <FolderUp size={26} strokeWidth={2.25} />
                          <span className="absolute -bottom-1 -right-1 flex h-6 w-6 items-center justify-center rounded-full bg-white shadow-sm ring-2 ring-indigo-100">
                            <ShieldCheck size={12} className="text-indigo-600" strokeWidth={2.5} />
                          </span>
                        </div>
                        <p className="shrink-0 text-[15px] font-extrabold text-slate-800">
                          拖拽或{' '}
                          <button
                            type="button"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleDropZoneClick();
                            }}
                            className="text-indigo-600 underline-offset-2 hover:underline"
                          >
                            选择文件
                          </button>{' '}
                          至此处
                        </p>
                        <p className="mt-2 max-w-[520px] shrink-0 text-[12px] font-medium leading-relaxed text-slate-400">
                          支持7W字以内的doc、docx格式文件，限1份合同文件，大小10M内
                        </p>
                        <input
                          ref={fileInputRef}
                          type="file"
                          className="hidden"
                          accept={ACCEPT_ATTR}
                          onChange={handleLocalFileChange}
                        />
                      </div>
                      {uploadError ? (
                        <p className="mt-2 shrink-0 text-[12px] font-bold text-red-500">{uploadError}</p>
                      ) : null}
                    </div>
                  ) : (
                    <div className="flex min-h-0 flex-1 flex-col animate-in fade-in duration-200">
                      <p className="mb-2.5 shrink-0 text-[12px] font-medium text-slate-400">
                        本地与工作空间合计最多 {MAX_TARGETS} 份合同文件
                        {atCapacity ? '（已达上限）' : `（还可添加 ${remainingSlots} 份）`}
                      </p>
                      <div className="min-h-0 flex-1">
                        <WorkspaceFilePicker
                          sources={sources}
                          conclusions={conclusions}
                          selected={workspaceSelections}
                          onToggle={handleWorkspaceToggle}
                          disableAdd={atCapacity}
                          accent="indigo"
                          selectableCountLabel="可选文件"
                          emptySourcesText="暂无可选的来源文件（仅支持已就绪的文档类文件）"
                          emptyConclusionsText="暂无可选的生成结果（仅支持已完成的结果）"
                        />
                      </div>
                      {uploadError ? (
                        <p className="mt-2 shrink-0 text-[12px] font-bold text-red-500">{uploadError}</p>
                      ) : null}
                    </div>
                  )}
                </div>
              </section>

              {/* 2. 待审查对象 */}
              <section className="shrink-0">
                <div className="mb-2.5 flex items-center justify-between gap-3">
                  <h4 className="text-[14px] font-extrabold text-slate-800">待审查对象</h4>
                  <span className="text-[12px] font-bold text-slate-400">
                    {pendingTargets.length}/{MAX_TARGETS}
                  </span>
                </div>
                {isEmptyState ? (
                  <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50/50 px-4 py-5 text-center text-[12px] font-medium text-slate-400">
                    从上方本地上传或工作空间选择文件后，将在此汇总展示
                  </div>
                ) : (
                  <div className="grid grid-cols-1 gap-2.5 sm:grid-cols-2">
                    {pendingTargets.map((target) => {
                      const title = targetTitle(target);
                      // 与智能脱敏「待脱敏对象」副标题保持一致
                      const subtitle =
                        target.kind === 'local'
                          ? `本地文件 · ${formatFileSize(target.size)}`
                          : target.selection.origin === 'source'
                            ? '工作空间文件 · 来源文件'
                            : '工作空间文件 · 生成结果';
                      return (
                        <div
                          key={target.key}
                          className="flex items-center gap-3 rounded-2xl border border-slate-200 bg-white px-3.5 py-2.5 shadow-sm"
                        >
                          <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-indigo-50 text-indigo-600">
                            <FileText size={16} strokeWidth={2.5} />
                          </span>
                          <div className="min-w-0 flex-1">
                            <div className="truncate text-[13px] font-bold text-slate-800">{title}</div>
                            <div className="truncate text-[11px] font-medium text-slate-400">
                              {subtitle}
                            </div>
                          </div>
                          <button
                            type="button"
                            onClick={() => removePendingTarget(target.key)}
                            className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                            aria-label={`移除 ${title}`}
                          >
                            <X size={15} />
                          </button>
                        </div>
                      );
                    })}
                  </div>
                )}
              </section>

              {/* 3. 审查手册（与脱敏「脱敏规则」同层） */}
              <section className="shrink-0">
                <div className="mb-2.5 flex items-center gap-2">
                  <ShieldCheck size={16} className="text-indigo-600" strokeWidth={2.5} />
                  <h4 className="text-[14px] font-extrabold text-slate-800">审查手册</h4>
                </div>
                <div className="grid grid-cols-1 gap-2.5">
                  {allPlaybooksForSelect.map((pb) => {
                    const selected = selectedPlaybookId === pb.id;
                    const isDefault = Boolean(pb.isDefault);
                    return (
                      <div
                        key={pb.id}
                        className={`group relative flex w-full items-center gap-3 rounded-2xl border px-4 py-3.5 transition-all ${
                          selected
                            ? 'border-indigo-300 bg-indigo-50/70 shadow-sm'
                            : 'border-slate-200 bg-white'
                        }`}
                      >
                        <button
                          type="button"
                          onClick={() => setSelectedPlaybookId(pb.id)}
                          className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full border-2 transition-colors ${
                            selected ? 'border-indigo-600 bg-indigo-600' : 'border-slate-300 bg-white'
                          }`}
                          aria-label={selected ? '已选中' : '选择手册'}
                        >
                          {selected ? <Check size={12} className="text-white" strokeWidth={3} /> : null}
                        </button>
                        <button
                          type="button"
                          onClick={() => setSelectedPlaybookId(pb.id)}
                          className="min-w-0 flex-1 text-left"
                        >
                          <div className="flex flex-wrap items-center gap-2">
                            <span className="text-[14px] font-extrabold text-slate-800">{pb.name}</span>
                            {isDefault ? (
                              <span className="rounded-md bg-white px-1.5 py-0.5 text-[10px] font-extrabold text-indigo-600 ring-1 ring-indigo-200">
                                默认
                              </span>
                            ) : null}
                          </div>
                          <p className="mt-1.5 line-clamp-2 text-[12px] font-medium leading-relaxed text-slate-500">
                            {pb.desc}
                          </p>
                        </button>
                        {isDefault ? (
                          <div className="relative shrink-0 group/settings">
                            <button
                              type="button"
                              onClick={openDefaultPlaybookSettings}
                              className="flex h-9 w-9 items-center justify-center rounded-xl border border-slate-200 bg-white text-slate-400 transition-all hover:border-indigo-200 hover:bg-indigo-50 hover:text-indigo-600"
                              aria-label="配置默认审查手册"
                            >
                              <Settings size={16} strokeWidth={2.5} />
                            </button>
                            <span
                              role="tooltip"
                              className="pointer-events-none absolute right-0 bottom-full z-20 mb-2 whitespace-nowrap rounded-lg bg-slate-800 px-2.5 py-1.5 text-[11px] font-bold text-white opacity-0 shadow-lg transition-opacity duration-150 group-hover/settings:opacity-100"
                            >
                              配置默认审查手册
                              <span className="absolute right-3 top-full border-4 border-transparent border-t-slate-800" />
                            </span>
                          </div>
                        ) : (
                          <div className="flex shrink-0 items-center gap-1 opacity-0 transition-opacity group-hover:opacity-100">
                            <button
                              type="button"
                              onClick={(e) => startEditPlaybook(e, pb)}
                              className="rounded-full bg-slate-100 p-1.5 text-slate-400 hover:bg-indigo-100 hover:text-indigo-600"
                              title="编辑审查手册"
                            >
                              <Edit3 size={14} strokeWidth={2.5} />
                            </button>
                            <button
                              type="button"
                              onClick={(e) => {
                                e.stopPropagation();
                                setPlaybookToDelete(pb);
                              }}
                              className="rounded-full bg-slate-100 p-1.5 text-slate-400 hover:bg-red-100 hover:text-red-500"
                              title="删除审查手册"
                            >
                              <Trash2 size={14} strokeWidth={2.5} />
                            </button>
                          </div>
                        )}
                      </div>
                    );
                  })}
                </div>
              </section>
            </div>

            <div className="flex shrink-0 items-center justify-end gap-3 border-t border-slate-100 bg-white px-6 py-4">
              {!canStart ? (
                <p className="mr-auto text-[12px] font-bold text-slate-400">
                  请至少选择 1 个待审查对象并选定审查手册
                </p>
              ) : (
                <p className="mr-auto text-[12px] font-medium text-slate-400">
                  {visibleBasis.length > 0
                    ? `已选 ${visibleBasis.length} 个审查依据（来源文件）`
                    : '未选审查依据时，将仅基于合同正文与审查手册'}
                </p>
              )}
              <div ref={basisPanelRef} className="relative">
                <button
                  type="button"
                  onClick={() => {
                    setBasisError(null);
                    setBasisPanelOpen((v) => !v);
                  }}
                  className={`inline-flex items-center gap-1.5 rounded-2xl border px-4 py-2.5 text-[13px] font-bold transition-all ${
                    basisPanelOpen
                      ? 'border-indigo-200 bg-indigo-50 text-indigo-700'
                      : 'border-slate-200 bg-white text-slate-600 hover:border-indigo-200 hover:bg-indigo-50/60 hover:text-indigo-700'
                  }`}
                >
                  <Library size={15} strokeWidth={2.5} />
                  审查依据
                  {visibleBasis.length > 0 ? (
                    <span className="rounded-md bg-indigo-100 px-1.5 py-0.5 text-[11px] font-extrabold text-indigo-700">
                      {visibleBasis.length}
                    </span>
                  ) : null}
                  <ChevronDown
                    size={14}
                    strokeWidth={2.5}
                    className={`transition-transform ${basisPanelOpen ? 'rotate-180' : ''}`}
                  />
                </button>
                {basisPanelOpen ? (
                  <div
                    className="absolute bottom-full right-0 z-[80] mb-2 w-[260px] overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-xl animate-in fade-in zoom-in-95 origin-bottom-right"
                    onClick={(e) => e.stopPropagation()}
                  >
                    <div className="flex items-center justify-between gap-2 border-b border-indigo-50 bg-indigo-50/70 px-3 py-2">
                      <span className="text-[12px] font-bold text-indigo-700/80">来源</span>
                      <button
                        type="button"
                        disabled={selectableBasisSources.length === 0}
                        onClick={handleBasisSelectAll}
                        className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border transition-colors ${
                          selectableBasisSources.length === 0
                            ? 'cursor-not-allowed border-slate-200 bg-slate-50'
                            : basisAllSelected
                              ? 'border-indigo-600 bg-indigo-600 text-white'
                              : basisSomeSelected
                                ? 'border-indigo-600 bg-indigo-100 text-indigo-600'
                                : 'border-slate-300 bg-white hover:border-indigo-400'
                        }`}
                        aria-label={basisAllSelected ? '取消全选' : '全选来源'}
                        title={basisAllSelected ? '取消全选' : '全选'}
                      >
                        {basisAllSelected ? (
                          <Check size={10} strokeWidth={3} />
                        ) : basisSomeSelected ? (
                          <span className="h-0.5 w-2 rounded-full bg-indigo-600" />
                        ) : null}
                      </button>
                    </div>
                    {/* 约 10 条单行来源高度，超出再滚动 */}
                    <div className="custom-scrollbar max-h-[320px] overflow-y-auto px-1.5 pb-1.5">
                      {basisSourceOptions.length === 0 ? (
                        <div className="px-2 py-5 text-center text-[11px] font-medium text-slate-400">
                          暂无来源文件
                        </div>
                      ) : (
                        <div className="space-y-0.5">
                          {basisSourceOptions.map((source) => {
                            const selection: WorkspaceFileSelection = {
                              origin: 'source',
                              id: source.id,
                              title: source.title,
                            };
                            const inTargets = pendingTargets.some(
                              (t) =>
                                t.kind === 'workspace' &&
                                isSameWorkspaceSelection(t.selection, selection)
                            );
                            const selected =
                              !inTargets &&
                              basisItems.some((b) => isSameWorkspaceSelection(b.selection, selection));
                            return (
                              <button
                                key={String(source.id)}
                                type="button"
                                disabled={inTargets}
                                title={inTargets ? '已在待审查对象中' : source.title}
                                onClick={() => handleBasisToggle(selection)}
                                className={`flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-slate-600 transition-colors ${
                                  inTargets
                                    ? 'cursor-not-allowed opacity-40'
                                    : 'hover:bg-slate-50'
                                }`}
                              >
                                {basisSourceIcon(source.type)}
                                <span className="min-w-0 flex-1 truncate text-[12px] font-medium">
                                  {source.title}
                                </span>
                                <span
                                  className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border ${
                                    selected
                                      ? 'border-indigo-600 bg-indigo-600 text-white'
                                      : 'border-slate-300 bg-white'
                                  }`}
                                  aria-hidden
                                >
                                  {selected ? <Check size={10} strokeWidth={3} /> : null}
                                </span>
                              </button>
                            );
                          })}
                        </div>
                      )}
                    </div>
                    {basisError ? (
                      <p className="border-t border-slate-100 px-3 py-1.5 text-[11px] font-bold text-red-500">
                        {basisError}
                      </p>
                    ) : null}
                  </div>
                ) : null}
              </div>
              <button
                type="button"
                disabled={!canStart}
                onClick={handleStartReview}
                className={`rounded-2xl px-6 py-2.5 text-[13px] font-bold transition-all ${
                  canStart
                    ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95'
                    : 'cursor-not-allowed bg-slate-100 text-slate-300'
                }`}
              >
                开始审查
              </button>
            </div>
          </>
        ) : null}
      </div>

      {playbookToDelete ? (
        <div
          className="fixed inset-0 z-[700] flex items-center justify-center bg-slate-900/40 backdrop-blur-md animate-in fade-in"
          onClick={() => setPlaybookToDelete(null)}
        >
          <div
            className="w-[400px] rounded-[32px] bg-white p-8 shadow-2xl animate-in zoom-in-95 font-bold"
            onClick={(e) => e.stopPropagation()}
          >
            <div className="flex flex-col items-center text-center">
              <div className="mb-5 flex h-16 w-16 items-center justify-center rounded-full bg-red-50 text-red-500">
                <Trash2 size={32} strokeWidth={2.5} />
              </div>
              <h3 className="mb-2 text-xl font-extrabold text-slate-800">确认删除吗？</h3>
              <p className="px-4 text-sm font-bold text-gray-400">
                您正在操作：<span className="text-slate-600">{playbookToDelete.name}</span>。
                <br />
                删除后该审查手册将无法恢复。
              </p>
            </div>
            <div className="mt-8 flex flex-col gap-2 px-4 pb-2 font-bold">
              <button
                type="button"
                onClick={confirmDeletePlaybook}
                className="w-full rounded-2xl bg-red-500 py-4 text-white shadow-lg hover:bg-red-600"
              >
                确认删除
              </button>
              <button
                type="button"
                onClick={() => setPlaybookToDelete(null)}
                className="w-full rounded-2xl py-3.5 text-gray-400 hover:bg-slate-50"
              >
                我再想想
              </button>
            </div>
          </div>
        </div>
      ) : null}
    </div>
  );
}
