import type {
  AnalysisDirection,
  CiteItem,
  CivilCaseReport,
  CivilCaseStartPayload,
  SearchScope,
} from './civilCaseTypes';
import type { WorkspaceFileSelection } from '../Desensitize/WorkspaceFilePicker';

function todayLabel(): string {
  const d = new Date();
  const pad = (n: number) => String(n).padStart(2, '0');
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
}

function directionLabel(direction: AnalysisDirection[]): string {
  if (direction.includes('full')) return '全流程分析';
  const map: Record<string, string> = {
    research: '案件基础分析',
    evidence: '证据梳理',
    strategy: '策略制定',
  };
  return direction.map((d) => map[d]).join(' / ');
}

function searchLabel(scope: SearchScope): string {
  const map: Record<string, string> = {
    statute: '仅法规、司法解释检索与核验',
    cases: '仅类案检索与核验',
    all: '法规、司法解释与类案并检',
    none: '不主动检索（仅基于已有材料分析）',
  };
  return map[scope];
}

function buildCites(scope: SearchScope, materials: WorkspaceFileSelection[]): CiteItem[] {
  const cites: CiteItem[] = [];
  if (scope !== 'none') {
    if (scope === 'statute' || scope === 'all') {
      cites.push({
        title: '《中华人民共和国民法典》第五百七十七条（违约责任）',
        kind: 'law',
        note: '现行有效已核验',
      });
      cites.push({
        title: '《中华人民共和国民法典》第六百二十六条（价款支付）',
        kind: 'law',
        note: '现行有效已核验',
      });
    }
    if (scope === 'cases' || scope === 'all') {
      cites.push({
        title: '（2023）沪 01 民终 0000 号 买卖合同纠纷',
        kind: 'case',
        note: '已核验案号。标的、争点与你方相近，审级一致',
      });
      cites.push({
        title: '最高人民法院指导性案例 15 号：徐工集团等买卖合同纠纷案',
        kind: 'case',
        note: '已核验。裁判要旨与本案质量异议期间的争点相关',
      });
    }
  }
  materials.forEach((m, i) => {
    cites.push({
      title: m.title,
      kind: 'material',
      note: i === 0 ? '用户材料（已读取）' : '用户材料（已读取）',
    });
  });
  return cites;
}

