/** 生成面向产品预览的结构化报告 + 一份紧凑的 Markdown 摘要（作为结论卡内容/可编辑正文） */
export function buildMockCivilCaseReport(payload: CivilCaseStartPayload): CivilCaseReport {
  const { direction, meta, materials, searchScope } = payload;
  const caseName = meta?.caseName || payload.caseInfoWorkspaceFile?.title || '民事案件';
  const documentTitle = caseName === '民事案件' ? '民事案件研究报告' : `民事案件研究报告：${caseName}`;
  const isFull = direction.includes('full');
  const has = (d: AnalysisDirection) => isFull || direction.includes(d);

  const caseInfoText =
    payload.caseInfoText?.trim() ||
    (payload.caseInfoWorkspaceFile
      ? `（案情信息来自工作空间文件：${payload.caseInfoWorkspaceFile.title}）`
      : '（未提供文字案情信息，请以所选案件材料为准）');

  const cites = buildCites(searchScope || 'all', materials);
  const report: CivilCaseReport = {
    documentTitle,
    subtitle: '民事案件研究报告（原型）',
    caseName,
    caseInfoText,
    ourSide: meta?.ourSide || '待补全',
    claimType: meta?.claimType || '待补全',
    venue: meta?.venue || '待补全',
    stage: meta?.stage || '待补全',
    directionLabel: directionLabel(direction),
    searchLabel: searchLabel(searchScope || 'all'),
    reviewDate: todayLabel(),
    cites,
    conclusion:
      '总体而言，我方基础请求权较为清晰，但“验收标准是否书面化”与“质量异议期间”是现阶段最主要的两个不确定点。',
    unCovered: '未展开类案裁判趋势；未评估执行风险。',
    nextSteps: ['确认验收标准是否有书面/双方确认文件', '确认质量异议是否超期', '补齐证据后与对方沟通或进入质证准备'],
    mainReferences: '法规与案例以本次检索/核验结果为准；用户材料用于事实与证据判断。',
    markdown: '',
  };

  if (has('research')) report.research = buildResearch();
  if (has('evidence')) report.evidence = buildEvidence();
  if (has('strategy')) report.strategy = buildStrategy();

  report.markdown = buildMarkdown(report);
  return report;
}

function bulletList(items: string[]): string {
  return items.map((i) => `- ${i}`).join('\n');
}

function buildMarkdown(report: CivilCaseReport): string {
  const lines: string[] = [];
  lines.push(`# ${report.documentTitle}（截至 ${report.reviewDate}）`);
  lines.push('');
  lines.push('## 一、案件基本信息与本次分析范围');
  lines.push(`- 当事人及我方立场：${report.ourSide}`);
  lines.push(`- 案由/法律关系、管辖地及程序阶段：${report.claimType}；${report.venue}；${report.stage}`);
  lines.push(`- 本次用户选择的核心分析范围：${report.directionLabel}`);
  lines.push(`- 案情信息：${report.caseInfoText}`);
  lines.push('');
  lines.push('## 二、法规、司法解释与类案检索核验');
  lines.push(bulletList(report.cites.map((c) => `${c.title}（${c.note}）`)));
  lines.push('');
  lines.push(`> （本摘要由原型生成，完整结构化章节请在前端「案件研究报告」预览中查看。）`);
  lines.push('');
  lines.push('## 六、综合结论、风险提示与下一步');
  lines.push(`- 结论：${report.conclusion}`);
  lines.push(`- 未覆盖：${report.unCovered}`);
  lines.push('- 下一步：');
  lines.push(bulletList(report.nextSteps));
  lines.push('');
  lines.push('> 本报告由律爱多（北大法宝旗下 AI 法律产品）生成，仅供法律分析与业务决策参考；最终结论请以已核验来源及专业人员意见为准。更多法律能力，请前往律爱多：[https://ai.pkulaw.com/apps/lawyerAssist/](https://ai.pkulaw.com/apps/lawyerAssist/)');
  return lines.join('\n');
}
