import React, { useEffect } from 'react';
import { Bot } from 'lucide-react';
import ModelSelector from './ModelSelector';
import SearchInput from './SearchInput';
import SearchResultsView from './SearchResultsView';
import { useSearchLogic } from './useSearchLogic';

const SUGGESTION_TAGS = ['夫妻共同财产', '撤销监护权', '合伙企业的法律责任'];

type SearchModuleProps = {
  /** 侧栏再次点击「智能检索」时递增，用于从结果页回到检索首页 */
  composeResetToken?: number;
};

const SearchModule: React.FC<SearchModuleProps> = ({ composeResetToken = 0 }) => {
  const {
    query,
    setQuery,
    submit,
    phase,
    submittedQuery,
    followUp,
    setFollowUp,
    searchMode,
    setSearchMode,
    sources,
    toggleSource,
    modelId,
    setModelId,
    thinkingEnabled,
    setThinkingEnabled,
    modelDisplayLabel,
    applySuggestion,
    newSearch,
    submitFollowUp,
  } = useSearchLogic();

  useEffect(() => {
    if (composeResetToken > 0) newSearch();
  }, [composeResetToken, newSearch]);

  return (
    <main className="flex min-h-0 flex-1 flex-col overflow-hidden font-bold animate-in fade-in bg-white">
      {/* 顶栏：与律爱多主站风格对齐 */}
      <header className="flex h-[52px] flex-shrink-0 items-center justify-between gap-4 border-b border-gray-100 bg-white px-5 shadow-sm z-10">
        <div className="flex min-w-0 items-center gap-3">
          <span className="truncate text-[15px] font-extrabold tracking-tight text-slate-800">智能检索</span>
          <ModelSelector
            modelId={modelId}
            onModelChange={setModelId}
            thinkingEnabled={thinkingEnabled}
            onThinkingChange={setThinkingEnabled}
          />
        </div>
        <div className="hidden items-center gap-4 text-[12px] font-bold text-slate-500 md:flex">
          <button type="button" className="transition hover:text-blue-600">
            北大法宝
          </button>
          <button type="button" className="transition hover:text-blue-600">
            帮助中心
          </button>
          <button type="button" className="transition hover:text-blue-600">
            多端使用
          </button>
          <span className="text-slate-300">|</span>
          <div className="flex items-center gap-2">
            <span className="text-slate-600">我的个人账户</span>
            <span className="rounded-full border border-amber-200 bg-amber-50 px-2 py-0.5 text-[10px] font-extrabold text-amber-800">
              个人版-VIP
            </span>
          </div>
          <span className="max-w-[120px] truncate text-slate-400">律爱多产品团队</span>
        </div>
      </header>

      {phase === 'compose' ? (
        <div className="relative min-h-0 flex-1 overflow-y-auto custom-scrollbar bg-gradient-to-b from-sky-50/90 via-[#eef4fb] to-slate-100/60">
          <div className="mx-auto flex min-h-[calc(100vh-52px)] w-full max-w-4xl flex-col justify-center px-5 py-10 md:px-8">
            <div className="mb-6 flex justify-end pr-1">
              <div className="flex max-w-full items-start gap-3">
                <div className="max-w-[min(100%,280px)] rounded-2xl rounded-tr-sm border border-blue-100 bg-white px-4 py-3 text-[13px] font-bold leading-relaxed text-slate-700 shadow-md shadow-blue-100/80">
                  您好，我是你的智能助手，快来使用智能检索吧！
                </div>
                <div
                  className="flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-blue-500 to-blue-600 text-white shadow-lg shadow-blue-300/50"
                  aria-hidden
                >
                  <Bot size={30} strokeWidth={2} />
                </div>
              </div>
            </div>

            <SearchInput
              value={query}
              onChange={setQuery}
              onSubmit={submit}
              searchMode={searchMode}
              onSearchModeChange={setSearchMode}
              sources={sources}
              onToggleSource={toggleSource}
            />

            <div className="mx-auto mt-10 w-full max-w-3xl">
              <p className="mb-3 text-center text-[12px] font-bold text-slate-500">可以试试这样检索：</p>
              <div className="flex flex-wrap justify-center gap-2">
                {SUGGESTION_TAGS.map((tag) => (
                  <button
                    key={tag}
                    type="button"
                    onClick={() => applySuggestion(tag)}
                    className="rounded-full border border-slate-200/90 bg-white/90 px-4 py-2 text-[12px] font-bold text-slate-600 shadow-sm transition hover:border-blue-200 hover:bg-blue-50/90 hover:text-blue-700"
                  >
                    {tag}
                  </button>
                ))}
              </div>
            </div>
          </div>
        </div>
      ) : (
        <SearchResultsView
          submittedQuery={submittedQuery}
          modelId={modelId}
          thinkingEnabled={thinkingEnabled}
          searchMode={searchMode}
          setSearchMode={setSearchMode}
          sources={sources}
          toggleSource={toggleSource}
          followUp={followUp}
          setFollowUp={setFollowUp}
          onFollowUpSubmit={submitFollowUp}
          onNewSearch={newSearch}
        />
      )}
    </main>
  );
};

export default SearchModule;
