import { toUniqueFieldIdsFromSelectionKeys, getSensitiveField } from './desensitizeRules';

/** 识别：解析中 → 识别中 → 识别完成；脱敏：脱敏中 → 脱敏完成 */
export type DesensitizePhase =
  | 'parsing'
  | 'recognizing'
  | 'recognized'
  | 'masking'
  | 'masked'
  /** @deprecated 兼容旧数据，等同 recognized */
  | 'completed';

export type DesensitizeTargetPayload = {
  key: string;
  title: string;
  sourceLabel: string;
};

export type StartRecognizePayload = {
  targets: DesensitizeTargetPayload[];
  selectedFieldKeys: string[];
  /** recognize：识别后停在识别完成；direct-mask：解析→识别→脱敏一气呵成 */
  mode?: 'recognize' | 'direct-mask';
};

export type HighlightPart = {
  text: string;
  /** 敏感命中，预览中以橙红色标记 */
  sensitive?: boolean;
  /** 已脱敏替换后的片段 */
  masked?: boolean;
  /** 识别结果中被忽略，脱敏时跳过 */
  ignored?: boolean;
  fieldLabel?: string;
  /** 用于结果列表定位 */
  hitId?: string;
};

export type MaskBuildOptions = {
  /** 脱敏时跳过的命中 id（annotate 生成的 hit-N） */
  ignoredHitIds?: Iterable<string>;
};

function toIgnoredSet(ignoredHitIds?: Iterable<string>): Set<string> {
  return new Set(ignoredHitIds || []);
}

export type RecognizeHit = {
  id: string;
  fieldLabel: string;
  text: string;
};

export type RecognizeDocBlock =
  | { type: 'title'; text: string }
  | { type: 'meta'; parts: HighlightPart[] }
  | { type: 'heading'; text: string }
  | { type: 'paragraph'; parts: HighlightPart[] }
  | {
      type: 'table';
      headers: string[];
      /** 每个单元格为可混合高亮的文本片段 */
      rows: HighlightPart[][][];
    };

export type RecognizeDocument = {
  title: string;
  hitCount: number;
  blocks: RecognizeDocBlock[];
};

/** 根据进度映射识别阶段：解析中 → 识别中 → 识别完成 */
export function getDesensitizePhase(progress: number, status?: string): DesensitizePhase {
  if (status === 'completed' || progress >= 100) return 'recognized';
  if (progress < 35) return 'parsing';
  return 'recognizing';
}

/** 直接脱敏：解析中 → 识别中 → 脱敏中 → 脱敏完成（不在识别完成停留） */
export function getDirectMaskPhase(progress: number, status?: string): DesensitizePhase {
  if (status === 'completed' || progress >= 100) return 'masked';
  if (progress < 30) return 'parsing';
  if (progress < 55) return 'recognizing';
  return 'masking';
}

export function getDesensitizePhaseLabel(phase?: DesensitizePhase | string | null): string {
  if (phase === 'parsing') return '解析中';
  if (phase === 'recognizing') return '识别中';
  if (phase === 'masking') return '脱敏中';
  if (phase === 'masked') return '脱敏完成';
  if (phase === 'recognized' || phase === 'completed') return '识别完成';
  return '识别完成';
}

export function isDesensitizeRecognized(phase?: string | null): boolean {
  return phase === 'recognized' || phase === 'completed';
}

export function isDesensitizeMasked(phase?: string | null): boolean {
  return phase === 'masked';
}

export type DesensitizeCardView = {
  state: 'recognizing' | 'recognized' | 'masking' | 'masked' | 'other';
  badge: string;
  /** 完成态辅助文案；进行中不走此字段 */
  helper: string | null;
  showStartMask: boolean;
};

/** 右侧结果卡片展示态（避免 job/phase 不一致时 UI 错乱） */
export function getDesensitizeCardView(conclusion: {
  status?: string;
  desensitizePhase?: string | null;
  desensitizeJob?: string | null;
  content?: string | null;
  maskedDocument?: { hitCount?: number } | null;
  recognizeDocument?: { hitCount?: number } | null;
}): DesensitizeCardView {
  const hitCount =
    conclusion.maskedDocument?.hitCount ??
    conclusion.recognizeDocument?.hitCount ??
    0;

  const masking =
    conclusion.status === 'generating' &&
    (conclusion.desensitizeJob === 'mask' || conclusion.desensitizePhase === 'masking');

  const masked =
    conclusion.desensitizePhase === 'masked' ||
    (!!conclusion.maskedDocument && conclusion.status === 'completed') ||
    (conclusion.status === 'completed' &&
      (conclusion.desensitizeJob === 'mask' || conclusion.desensitizeJob === 'direct-mask')) ||
    (conclusion.status === 'completed' &&
      typeof conclusion.content === 'string' &&
      (conclusion.content.startsWith('已处理敏感信息') ||
        // 异常残留：进度文案未替换时，完成态也按脱敏完成展示
        conclusion.content.startsWith('正在脱敏')));

  if (masking) {
    return { state: 'masking', badge: '脱敏中', helper: null, showStartMask: false };
  }

  if (masked) {
    return {
      state: 'masked',
      badge: '脱敏完成',
      helper: `已处理敏感信息 ${hitCount} 处`,
      showStartMask: false,
    };
  }

  if (conclusion.status === 'generating') {
    return {
      state: 'recognizing',
      badge: getDesensitizePhaseLabel(conclusion.desensitizePhase),
      helper: null,
      showStartMask: false,
    };
  }

  if (conclusion.status === 'completed') {
    return {
      state: 'recognized',
      badge: '识别完成',
      helper:
        conclusion.content && !conclusion.content.startsWith('正在脱敏')
          ? conclusion.content
          : `已识别敏感信息约 ${hitCount} 处，点击查看文档高亮预览`,
      showStartMask: true,
    };
  }

  return { state: 'other', badge: '', helper: null, showStartMask: false };
}

export type MaskMethod = 'LABEL' | 'MASK';

/** LABEL 类展示标签（部分字段标签名与字段名不同） */
const LABEL_DISPLAY: Record<string, string> = {
  年龄: '[年龄]',
  性别: '[性别]',
  出生日期: '[出生日期]',
  地址: '[地址]',
  健康状况: '[健康状况]',
  公司名称: '[公司名称]',
  金额: '[金额]',
  股东出资比例: '[出资比例]',
  日期: '[业务日期]',
};

const LABEL_FIELDS = new Set(Object.keys(LABEL_DISPLAY));

export function getMaskMethod(fieldLabel?: string): MaskMethod {
  if (fieldLabel && LABEL_FIELDS.has(fieldLabel)) return 'LABEL';
  return 'MASK';
}

function stars(n: number): string {
  return '*'.repeat(Math.max(n, 0));
}

/** 保留前 head、后 tail，中间替换为 * */
function keepHeadTail(text: string, head: number, tail: number): string {
  const t = text.trim();
  if (!t) return '';
  if (t.length <= head + tail) {
    if (t.length <= 1) return '*';
    return `${t[0]}${stars(t.length - 1)}`;
  }
  return `${t.slice(0, head)}${stars(t.length - head - tail)}${t.slice(-tail)}`;
}

function keepHead(text: string, head: number): string {
  const t = text.trim();
  if (!t) return '';
  if (t.length <= head) return stars(t.length);
  return `${t.slice(0, head)}${stars(t.length - head)}`;
}

function maskPersonName(text: string): string {
  const t = text.trim();
  if (!t) return '';
  if (t.length === 1) return '*';
  if (t.length === 2) return `${t[0]}*`;
  return `${t[0]}${stars(t.length - 2)}${t[t.length - 1]}`;
}

function maskPhoneOrFax(text: string): string {
  const t = text.trim();
  // 010-65881234 → 010-65****34
  const m = t.match(/^(\d{3,4}-)(\d+)(.*)$/);
  if (m) {
    const body = m[2];
    if (body.length <= 4) return `${m[1]}${stars(body.length)}${m[3] || ''}`;
    return `${m[1]}${body.slice(0, 2)}${stars(body.length - 4)}${body.slice(-2)}${m[3] || ''}`;
  }
  return keepHeadTail(t.replace(/\s/g, ''), 3, 2);
}

function maskEmail(text: string): string {
  const t = text.trim();
  const [user = '', domain = ''] = t.split('@');
  if (!domain) return keepHead(t, 1);
  const u = user[0] || '*';
  return `${u}${stars(Math.max(user.length - 1, 4))}@${domain}`;
}

function maskOrgCode(text: string): string {
  // AB12345-C → AB*****-C
  const t = text.trim();
  const m = t.match(/^(.{2})(.+)(.)$/);
  if (!m || t.length < 5) return keepHeadTail(t, 2, 2);
  return `${m[1]}${stars(m[2].length)}${m[3]}`;
}

function maskContractNo(text: string): string {
  // HXZL-FW-2023-0918 → HXZL-****-****-0918 或保留前缀与末尾
  const t = text.trim();
  const parts = t.split(/([-_/])/);
  if (parts.length >= 3) {
    const last = parts[parts.length - 1];
    const first = parts[0];
    return `${first}${parts.slice(1, -1).map((p) => (/^[-_/]$/.test(p) ? p : stars(Math.max(p.length, 2)))).join('')}${last}`;
  }
  return keepHeadTail(t, 4, 4);
}

function maskCaseNoSafe(text: string): string {
  // 更稳妥：年份保留，其余连续数字中间打码
  return text.replace(/\d+/g, (digits) => {
    if (digits.length === 4 && /^(19|20)\d{2}$/.test(digits)) return digits;
    if (digits.length <= 2) return `${digits[0] || '*'}${stars(Math.max(digits.length - 1, 0))}`;
    return keepHeadTail(digits, 1, 1);
  });
}

function maskPatentAppNo(text: string): string {
  // 保留前 4 位年份、末尾 2 位
  const t = text.replace(/\s/g, '');
  return keepHeadTail(t, 4, 2);
}

function maskPatentNo(text: string): string {
  // 保留 ZL 前缀、年份与末尾校验位
  const t = text.trim();
  const m = t.match(/^(ZL)?(\d{4})(.*?)(.)$/i);
  if (!m) return keepHeadTail(t, 4, 1);
  const prefix = m[1] || '';
  const year = m[2];
  const mid = m[3] || '';
  return `${prefix}${year}${stars(Math.max(mid.length, 2))}${m[4]}`;
}

function maskCopyrightNo(text: string): string {
  // 保留前缀/类型标识/末尾 2 位
  const t = text.trim();
  if (t.length <= 6) return keepHeadTail(t, 2, 2);
  return `${t.slice(0, 2)}${stars(t.length - 4)}${t.slice(-2)}`;
}

function maskTradeSecretId(text: string): string {
  // 保留前缀和年份，后续编号脱敏
  const t = text.trim();
  const m = t.match(/^([A-Za-z\u4e00-\u9fff-]*)((?:19|20)\d{2})(.*)$/);
  if (!m) return keepHeadTail(t, 4, 0);
  return `${m[1]}${m[2]}${stars(Math.max(m[3].length, 2))}`;
}

function maskSoftwareCopyright(text: string): string {
  // 保留年份、SR 标识、末尾 2 位
  const t = text.trim();
  const m = t.match(/^((?:19|20)\d{2})(.*?)(SR)(.*?)(.{2})$/i);
  if (!m) return keepHeadTail(t, 4, 2);
  return `${m[1]}${stars(Math.max(m[2].length, 1))}${m[3]}${stars(Math.max(m[4].length, 1))}${m[5]}`;
}

function maskInsuranceNo(text: string): string {
  const t = text.trim();
  const m = t.match(/^([A-Za-z]*)((?:19|20)\d{2})(.*?)([A-Za-z0-9]{2,6})$/);
  if (!m) return keepHeadTail(t, 4, 3);
  return `${m[1]}${m[2]}${stars(Math.max(m[3].length, 2))}${m[4]}`;
}

function maskTaxCertNo(text: string): string {
  // 保留前缀/年份/后 4 位
  const t = text.trim();
  const m = t.match(/^(\D*)((?:19|20)\d{2})(.*)(.{4})$/);
  if (!m) return keepHeadTail(t, 4, 4);
  return `${m[1]}${m[2]}****${m[4]}`;
}

/**
 * 按字段规则生成原型脱敏文本
 * - LABEL：统一替换为标签
 * - MASK：保留部分字符，其余为 *
 */
export function maskSensitiveText(text: string, fieldLabel?: string): string {
  const label = fieldLabel || '敏感信息';
  if (LABEL_FIELDS.has(label)) {
    return LABEL_DISPLAY[label] || `[${label}]`;
  }

  const raw = text ?? '';
  const compact = raw.replace(/\s/g, '');

  switch (label) {
    case '姓名':
      return maskPersonName(raw);
    case '身份证号码':
    case '社保登记号':
      return keepHeadTail(compact, 6, 4);
    case '固定电话/传真':
      return maskPhoneOrFax(raw);
    case '手机号码':
      return keepHeadTail(compact, 3, 4);
    case '银行账号':
    case '外汇账户账号':
      return keepHeadTail(compact, 6, 4);
    case '电子邮箱':
      return maskEmail(raw);
    case '邮政编码':
      return keepHead(compact, 2);
    case '车牌号码':
      return keepHead(raw.trim(), 4);
    case '社交账号':
      return keepHead(raw.trim(), 1);
    case '完税证明编号':
      return maskTaxCertNo(raw);
    case '公积金账号':
    case '营业执照注册号':
    case '纳税人识别号':
      return keepHeadTail(compact, 4, 4);
    case '统一社会信用代码':
      return keepHeadTail(compact, 4, 4);
    case '组织机构代码':
      return maskOrgCode(raw);
    case '开户许可证号':
      return keepHeadTail(compact, 5, 4);
    case '银行联行号':
      return keepHeadTail(compact, 3, 3);
    case '合同编号':
      return maskContractNo(raw);
    case '案号':
      return maskCaseNoSafe(raw);
    case '保险单号':
      return maskInsuranceNo(raw);
    case '专利申请号':
      return maskPatentAppNo(raw);
    case '专利号':
      return maskPatentNo(raw);
    case '商标号':
      return keepHeadTail(compact, 2, 2);
    case '域名注册证书编号':
      return keepHeadTail(compact, 2, 4);
    case '著作权登记号':
      return maskCopyrightNo(raw);
    case '商业秘密标识号':
      return maskTradeSecretId(raw);
    case '软件著作权登记号':
      return maskSoftwareCopyright(raw);
    default:
      return keepHeadTail(compact || raw, 2, 2);
  }
}

export type MaskResultItem = {
  id: string;
  fieldLabel: string;
  originalText: string;
  maskedText: string;
  maskMethod: MaskMethod;
};

/** 从识别文档生成脱敏对照清单（原文 → 脱敏结果；忽略项不进入清单） */
export function buildMaskResultItems(
  recognizeDocument: RecognizeDocument,
  options?: MaskBuildOptions
): MaskResultItem[] {
  const ignored = toIgnoredSet(options?.ignoredHitIds);
  const { hits } = annotateRecognizeDocument(recognizeDocument);
  return hits
    .filter((hit) => !ignored.has(hit.id))
    .map((hit) => ({
      id: hit.id,
      fieldLabel: hit.fieldLabel,
      originalText: hit.text,
      maskedText: maskSensitiveText(hit.text, hit.fieldLabel),
      maskMethod: getMaskMethod(hit.fieldLabel),
    }));
}

function maskParts(parts: HighlightPart[], ignored: Set<string>): HighlightPart[] {
  return parts.map((part) => {
    if (!part.sensitive) return part;
    if (part.hitId && ignored.has(part.hitId)) {
      // 忽略：保留原文，不打脱敏标记
      return {
        ...part,
        sensitive: false,
        masked: false,
        ignored: true,
      };
    }
    return {
      ...part,
      text: maskSensitiveText(part.text, part.fieldLabel),
      sensitive: false,
      masked: true,
      ignored: false,
    };
  });
}

/** 在已标注文档上标记忽略态，供识别预览灰显 */
export function applyIgnoredHitsToDocument(
  document: RecognizeDocument,
  ignoredHitIds?: Iterable<string>
): RecognizeDocument {
  const ignored = toIgnoredSet(ignoredHitIds);
  if (ignored.size === 0) return document;

  const markParts = (parts: HighlightPart[]): HighlightPart[] =>
    parts.map((part) =>
      part.hitId && ignored.has(part.hitId) ? { ...part, ignored: true } : { ...part, ignored: false }
    );

  const blocks = document.blocks.map((block) => {
    if (block.type === 'meta' || block.type === 'paragraph') {
      return { ...block, parts: markParts(block.parts) };
    }
    if (block.type === 'table') {
      return {
        ...block,
        rows: block.rows.map((row) => row.map((cell) => markParts(cell))),
      };
    }
    return block;
  });
  return { ...document, blocks };
}

/** 基于识别文档生成脱敏后预览文档（先标注 hitId，便于清单定位） */
export function buildMockMaskedDocument(
  recognizeDocument: RecognizeDocument,
  options?: MaskBuildOptions
): RecognizeDocument {
  const ignored = toIgnoredSet(options?.ignoredHitIds);
  const { document: annotated, hits } = annotateRecognizeDocument(recognizeDocument);
  const maskedHits = hits.filter((h) => !ignored.has(h.id));
  const blocks = annotated.blocks.map((block) => {
    if (block.type === 'meta' || block.type === 'paragraph') {
      return { ...block, parts: maskParts(block.parts, ignored) };
    }
    if (block.type === 'table') {
      return {
        ...block,
        rows: block.rows.map((row) => row.map((cell) => maskParts(cell, ignored))),
      };
    }
    return block;
  });
  return {
    ...annotated,
    hitCount: maskedHits.length,
    blocks,
  };
}

export function buildMockMaskedContent(hitCount: number): string {
  return `已处理敏感信息 ${hitCount} 处，点击查看脱敏后文档`;
}

function hit(text: string, fieldLabel: string, enabled: Set<string>): HighlightPart {
  if (enabled.size === 0 || enabled.has(fieldLabel)) {
    return { text, sensitive: true, fieldLabel };
  }
  return { text };
}

function plain(text: string): HighlightPart {
  return { text };
}

function countHits(blocks: RecognizeDocBlock[]): number {
  let n = 0;
  const walk = (parts: HighlightPart[]) => {
    parts.forEach((p) => {
      if (p.sensitive) n += 1;
    });
  };
  blocks.forEach((b) => {
    if (b.type === 'meta' || b.type === 'paragraph') walk(b.parts);
    if (b.type === 'table') {
      b.rows.forEach((row) => row.forEach((cell) => walk(cell)));
    }
  });
  return n;
}

function annotateParts(
  parts: HighlightPart[],
  hits: RecognizeHit[],
  counter: { value: number }
): HighlightPart[] {
  return parts.map((part) => {
    if (!part.sensitive) return part;
    const id = `hit-${counter.value++}`;
    hits.push({
      id,
      fieldLabel: part.fieldLabel || '敏感信息',
      text: part.text.replace(/\n/g, ' ').trim(),
    });
    return { ...part, hitId: id };
  });
}

/** 为敏感命中写入 hitId，并导出结果列表（与预览标记顺序一致） */
export function annotateRecognizeDocument(document: RecognizeDocument): {
  document: RecognizeDocument;
  hits: RecognizeHit[];
} {
  const hits: RecognizeHit[] = [];
  const counter = { value: 0 };
  const blocks = document.blocks.map((block) => {
    if (block.type === 'meta' || block.type === 'paragraph') {
      return { ...block, parts: annotateParts(block.parts, hits, counter) };
    }
    if (block.type === 'table') {
      return {
        ...block,
        rows: block.rows.map((row) =>
          row.map((cell) => annotateParts(cell, hits, counter))
        ),
      };
    }
    return block;
  });
  return {
    document: {
      ...document,
      blocks,
      hitCount: hits.length || document.hitCount,
    },
    hits,
  };
}

/** 卡片摘要文案 */
export function buildMockRecognizedContent(
  title: string,
  selectedFieldKeys: string[]
): string {
  const doc = buildMockRecognizedDocument(title, selectedFieldKeys);
  return `已识别敏感信息约 ${doc.hitCount} 处，点击查看文档高亮预览`;
}

