export type DesensitizeRule = {
  id: string;
  name: string;
  description: string;
  /** 是否为系统默认规则包（默认选中） */
  isDefault?: boolean;
};

export type SensitiveMatcher = {
  type: 'regex' | 'semantic';
  value: string;
};

/** 唯一敏感字段（ruleId 全局唯一；跨分类复用时共享同一 id） */
export type SensitiveField = {
  id: string;
  name: string;
  /** 系统内置标识 */
  builtin?: boolean;
  matchers: SensitiveMatcher[];
};

export type SensitiveCategory = {
  id: string;
  name: string;
  /** 引用唯一字段 id；同一 id 可出现在多个分类中 */
  fieldIds: string[];
};

/** 默认脱敏规则卡片；后续可扩展自定义规则 */
export const DEFAULT_DESENSITIZE_RULES: DesensitizeRule[] = [
  {
    id: 'default-pii',
    name: '默认脱敏规则',
    description: '识别姓名、身份证号、手机号、地址、银行卡号、邮箱等常见敏感信息并脱敏',
    isDefault: true,
  },
];

const semantic = (): SensitiveMatcher => ({ type: 'semantic', value: '系统内置' });
const regex = (value: string): SensitiveMatcher => ({ type: 'regex', value });

/**
 * 接口正则：仅按双换行（`\n\n` / `\\n\\n`）拆成多条备选模式。
 * 单换行可能只是正则正文格式（如案号），不拆分。
 */
function regexFromApi(pattern: string): SensitiveMatcher[] {
  return pattern
    .split(/\n\n|\\n\\n/)
    .map((p) => p.trim())
    .filter(Boolean)
    .map((p) => regex(p));
}

function withApiRegex(pattern: string): SensitiveMatcher[] {
  return [...regexFromApi(pattern), semantic()];
}

