/** 跨分类复用的唯一字段 id */
export const SHARED_SENSITIVE_FIELD_IDS = ['postcode', 'address', 'bank-account'] as const;

export function getSensitiveField(fieldId: string): SensitiveField | undefined {
  return SENSITIVE_FIELDS_BY_ID[fieldId];
}

/** 唯一 ruleId 列表（38）——执行脱敏时使用，避免复用字段重复处理 */
export function getAllUniqueFieldIds(
  categories: SensitiveCategory[] = DEFAULT_SENSITIVE_CATEGORIES
): string[] {
  const ids = new Set<string>();
  categories.forEach((c) => c.fieldIds.forEach((id) => ids.add(id)));
  return Array.from(ids);
}

/** UI 展示条目数（41）——含复用字段在各分类中的重复展示 */
export function getDisplayFieldCount(
  categories: SensitiveCategory[] = DEFAULT_SENSITIVE_CATEGORIES
): number {
  return categories.reduce((sum, c) => sum + c.fieldIds.length, 0);
}

/**
 * UI 勾选键：categoryId::fieldId
 * 复用字段在不同分类下独立勾选，执行时再收敛为唯一 fieldId
 */
export function makeSelectionKey(categoryId: string, fieldId: string): string {
  return `${categoryId}::${fieldId}`;
}

export function parseSelectionKey(key: string): { categoryId: string; fieldId: string } {
  const sep = key.indexOf('::');
  if (sep < 0) return { categoryId: '', fieldId: key };
  return { categoryId: key.slice(0, sep), fieldId: key.slice(sep + 2) };
}

/** 全部 UI 勾选键（41）——默认全选 */
export function getAllSelectionKeys(
  categories: SensitiveCategory[] = DEFAULT_SENSITIVE_CATEGORIES
): string[] {
  return categories.flatMap((c) => c.fieldIds.map((fieldId) => makeSelectionKey(c.id, fieldId)));
}

/** 某分类下的全部勾选键 */
export function getCategorySelectionKeys(category: SensitiveCategory): string[] {
  return category.fieldIds.map((fieldId) => makeSelectionKey(category.id, fieldId));
}

/** UI 已选条数（按分类独立计数，复用字段可计多次） */
export function countDisplaySelected(
  selectedKeys: string[],
  categories: SensitiveCategory[] = DEFAULT_SENSITIVE_CATEGORIES
): number {
  const selected = new Set(selectedKeys);
  return getAllSelectionKeys(categories).filter((key) => selected.has(key)).length;
}

/**
 * 从 UI 勾选键收敛为执行用唯一 fieldId：
 * 复用字段只要在任一分类被勾选，执行时只跑一次
 */
export function toUniqueFieldIdsFromSelectionKeys(selectedKeys: string[]): string[] {
  return Array.from(new Set(selectedKeys.map((key) => parseSelectionKey(key).fieldId)));
}

/** @deprecated 使用 getAllUniqueFieldIds；保留别名兼容旧调用 */
export function getAllSensitiveFieldIds(
  categories: SensitiveCategory[] = DEFAULT_SENSITIVE_CATEGORIES
): string[] {
  return getAllUniqueFieldIds(categories);
}

export function countSensitiveFields(
  categories: SensitiveCategory[] = DEFAULT_SENSITIVE_CATEGORIES
): number {
  return getDisplayFieldCount(categories);
}
