import React, { useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import {
  Check,
  ChevronDown,
  FileText,
  FolderOpen,
  FolderUp,
  Library,
  Link as LinkIcon,
  Scale,
  ShieldCheck,
  X,
} from 'lucide-react';
import WorkspaceFilePicker, {
  isSameWorkspaceSelection,
  type WorkspaceFileSelection,
  type WorkspacePickerConclusion,
  type WorkspacePickerSource,
} from '../Desensitize/WorkspaceFilePicker';
import type {
  RegulatoryReviewStartPayload,
  ReviewBasisItem,
  ReviewTarget,
} from './regulatoryReviewTypes';
import { DEFAULT_REVIEW_SCOPE, snapshotScope } from './reviewScopes';

type UploadTab = 'local' | 'workspace';

type RegulatoryReviewModalProps = {
  open: boolean;
  onClose: () => void;
  sources?: WorkspacePickerSource[];
  conclusions?: WorkspacePickerConclusion[];
  onStartReview: (payload: RegulatoryReviewStartPayload) => void;
};

const MAX_TARGETS = 10;
const MAX_FILE_SIZE_BYTES = 100 * 1024 * 1024;
const ACCEPT_EXTENSIONS = ['.txt', '.doc', '.docx', '.pdf'] as const;
const ACCEPT_ATTR = ACCEPT_EXTENSIONS.join(',');
const UPLOAD_SECTION_HEIGHT_FALLBACK = 360;
/** 空态上传区最小高度，避免矮视口下图标/文案被挤压 */
const UPLOAD_SECTION_MIN_HEIGHT = 220;

function workspaceTargetKey(selection: WorkspaceFileSelection): string {
  return `workspace:${selection.origin}:${selection.id}`;
}

function formatFileSize(bytes: number): string {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
}

function getFileExtension(name: string): string {
  const idx = name.lastIndexOf('.');
  return idx >= 0 ? name.slice(idx).toLowerCase() : '';
}

function validateLocalFile(file: File): string | null {
  const ext = getFileExtension(file.name);
  if (!ACCEPT_EXTENSIONS.includes(ext as (typeof ACCEPT_EXTENSIONS)[number])) {
    return '仅支持 txt、doc、docx、纯文本 pdf 格式';
  }
  if (file.size > MAX_FILE_SIZE_BYTES) return '单个文件不超过 100MB';
  return null;
}

function targetTitle(t: ReviewTarget): string {
  return t.kind === 'local' ? t.name : t.selection.title;
}

function targetSourceLabel(t: ReviewTarget): string {
  if (t.kind === 'local') return '本地文件';
  return t.selection.origin === 'source' ? '工作空间 · 来源文件' : '工作空间 · 生成结果';
}

function targetFormat(t: ReviewTarget): string {
  if (t.kind === 'local') {
    const ext = getFileExtension(t.name).replace('.', '').toUpperCase();
    return ext || 'FILE';
  }
  return (t.fileType || 'FILE').toUpperCase();
}

function buildDefaultBasis(sources: WorkspacePickerSource[]): ReviewBasisItem[] {
  return sources
    .filter((s) => (s as { checked?: boolean }).checked)
    .map((s) => ({
      key: workspaceTargetKey({ origin: 'source', id: s.id, title: s.title }),
      selection: { origin: 'source' as const, id: s.id, title: s.title },
      fileType: s.type,
      status: s.status || 'ready',
    }));
}

function basisSourceIcon(type: string | undefined) {
  if (type === 'url' || type === 'fb') {
    return <LinkIcon size={14} strokeWidth={2} className="shrink-0 text-slate-400" />;
  }
  return <FileText size={14} strokeWidth={2} className="shrink-0 text-slate-400" />;
}

export default function RegulatoryReviewModal({
  open,
  onClose,
  sources = [],
  conclusions = [],
  onStartReview,
}: RegulatoryReviewModalProps) {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const uploadTabListRef = useRef<HTMLDivElement>(null);
  const localTabRef = useRef<HTMLButtonElement>(null);
  const workspaceTabRef = useRef<HTMLButtonElement>(null);
  const uploadSectionRef = useRef<HTMLElement>(null);
  const basisPanelRef = useRef<HTMLDivElement>(null);

  const [activeTab, setActiveTab] = useState<UploadTab>('local');
  const [tabPillStyle, setTabPillStyle] = useState({ left: 4, width: 0 });
  const [pendingTargets, setPendingTargets] = useState<ReviewTarget[]>([]);
  const [basisItems, setBasisItems] = useState<ReviewBasisItem[]>([]);
  const [basisPanelOpen, setBasisPanelOpen] = useState(false);
  const [uploadSectionHeight, setUploadSectionHeight] = useState<number | null>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [basisError, setBasisError] = useState<string | null>(null);

  useEffect(() => {
    if (!open) return;
    setActiveTab('local');
    setPendingTargets([]);
    setBasisItems(buildDefaultBasis(sources));
    setBasisPanelOpen(false);
    setUploadSectionHeight(null);
    setIsDragging(false);
    setUploadError(null);
    setBasisError(null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [open]);

  useLayoutEffect(() => {
    if (!open) return;
    const list = uploadTabListRef.current;
    const activeBtn = activeTab === 'local' ? localTabRef.current : workspaceTabRef.current;
    if (!list || !activeBtn) return;
    const listRect = list.getBoundingClientRect();
    const btnRect = activeBtn.getBoundingClientRect();
    setTabPillStyle({
      left: btnRect.left - listRect.left,
      width: btnRect.width,
    });
  }, [open, activeTab]);

  const remainingSlots = MAX_TARGETS - pendingTargets.length;
  const atCapacity = remainingSlots <= 0;
  /** 默认空态一屏展示；有待审查文件后改为整页滚动（与合同/脱敏一致） */
  const isEmptyState = pendingTargets.length === 0;

  // 与脱敏/合同一致：空态 flex-1 测高，有文件后锁定该高度，避免上传区变矮
  useLayoutEffect(() => {
    if (!open || !isEmptyState) return;
    const el = uploadSectionRef.current;
    if (!el) return;
    const measure = () => {
      const h = Math.round(el.getBoundingClientRect().height);
      if (h > 0) setUploadSectionHeight(Math.max(h, UPLOAD_SECTION_MIN_HEIGHT));
    };
    measure();
    const ro = typeof ResizeObserver !== 'undefined' ? new ResizeObserver(measure) : null;
    ro?.observe(el);
    window.addEventListener('resize', measure);
    return () => {
      ro?.disconnect();
      window.removeEventListener('resize', measure);
    };
  }, [open, isEmptyState, activeTab]);

  useEffect(() => {
    if (!basisPanelOpen) return;
    const onPointerDown = (e: MouseEvent) => {
      if (basisPanelRef.current && !basisPanelRef.current.contains(e.target as Node)) {
        setBasisPanelOpen(false);
      }
    };
    document.addEventListener('mousedown', onPointerDown);
    return () => document.removeEventListener('mousedown', onPointerDown);
  }, [basisPanelOpen]);

  const workspaceSelections = useMemo(
    () =>
      pendingTargets
        .filter((t): t is Extract<ReviewTarget, { kind: 'workspace' }> => t.kind === 'workspace')
        .map((t) => t.selection),
    [pendingTargets]
  );

  const basisSourceOptions = sources;

  const visibleBasis = useMemo(
    () =>
      basisItems.filter(
        (b) =>
          b.selection.origin === 'source' &&
          !pendingTargets.some(
            (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, b.selection)
          )
      ),
    [basisItems, pendingTargets]
  );

  const selectableBasisSources = useMemo(
    () =>
      basisSourceOptions.filter(
        (source) =>
          !pendingTargets.some(
            (t) =>
              t.kind === 'workspace' &&
              isSameWorkspaceSelection(t.selection, {
                origin: 'source',
                id: source.id,
                title: source.title,
              })
          )
      ),
    [basisSourceOptions, pendingTargets]
  );

  const basisAllSelected =
    selectableBasisSources.length > 0 &&
    selectableBasisSources.every((source) =>
      basisItems.some(
        (b) => b.selection.origin === 'source' && String(b.selection.id) === String(source.id)
      )
    );
  const basisSomeSelected =
    !basisAllSelected &&
    selectableBasisSources.some((source) =>
      basisItems.some(
        (b) => b.selection.origin === 'source' && String(b.selection.id) === String(source.id)
      )
    );

  const canStart = pendingTargets.length > 0;

  if (!open) return null;

  const switchTab = (tab: UploadTab) => {
    setActiveTab(tab);
    setUploadError(null);
    setIsDragging(false);
  };

  const addLocalFiles = (fileList: FileList | File[]) => {
    const files = Array.from(fileList);
    if (files.length === 0) return;
    const next = [...pendingTargets];
    let rejectedFormat = false;
    let rejectedSize = false;
    let rejectedCapacity = false;

    for (const file of files) {
      if (next.length >= MAX_TARGETS) {
        rejectedCapacity = true;
        break;
      }
      const error = validateLocalFile(file);
      if (error === '仅支持 txt、doc、docx、纯文本 pdf 格式') {
        rejectedFormat = true;
        continue;
      }
      if (error === '单个文件不超过 100MB') {
        rejectedSize = true;
        continue;
      }
      const duplicated = next.some(
        (t) => t.kind === 'local' && t.name === file.name && t.size === file.size
      );
      if (duplicated) continue;
      next.push({
        key: `local:${file.name}:${file.size}:${file.lastModified}:${next.length}`,
        kind: 'local',
        name: file.name,
        size: file.size,
      });
    }

    if (rejectedCapacity) setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
    else if (rejectedFormat) setUploadError('仅支持 txt、doc、docx、纯文本 pdf 格式');
    else if (rejectedSize) setUploadError('单个文件不超过 100MB');
    else setUploadError(null);
    setPendingTargets(next);
  };

  const handleDropZoneClick = () => {
    if (atCapacity) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    fileInputRef.current?.click();
  };

  const handleLocalFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files?.length) return;
    addLocalFiles(files);
    e.target.value = '';
  };

  const handleWorkspaceToggle = (file: WorkspaceFileSelection) => {
    const exists = pendingTargets.some(
      (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file)
    );
    if (exists) {
      setUploadError(null);
      setPendingTargets((prev) =>
        prev.filter(
          (t) => !(t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file))
        )
      );
      return;
    }
    if (pendingTargets.length >= MAX_TARGETS) {
      setUploadError(`最多选择 ${MAX_TARGETS} 个文件`);
      return;
    }
    setUploadError(null);
    const sourceMeta = sources.find((s) => String(s.id) === String(file.id) && file.origin === 'source');
    const conclusionMeta = conclusions.find(
      (c) => String(c.id) === String(file.id) && file.origin === 'conclusion'
    );
    setPendingTargets((prev) => [
      ...prev,
      {
        key: workspaceTargetKey(file),
        kind: 'workspace',
        selection: file,
        fileType: sourceMeta?.type || conclusionMeta?.type,
        status: sourceMeta?.status || conclusionMeta?.status || 'ready',
      },
    ]);
  };

  const removePendingTarget = (key: string) => {
    setPendingTargets((prev) => prev.filter((t) => t.key !== key));
    setUploadError(null);
  };

  const handleBasisToggle = (file: WorkspaceFileSelection) => {
    if (file.origin !== 'source') return;
    const inTargets = pendingTargets.some(
      (t) => t.kind === 'workspace' && isSameWorkspaceSelection(t.selection, file)
    );
    if (inTargets) {
      setBasisError('该文件已在待审查对象中，不能作为审查依据');
      return;
    }
    const exists = basisItems.some((b) => isSameWorkspaceSelection(b.selection, file));
    if (exists) {
      setBasisError(null);
      setBasisItems((prev) => prev.filter((b) => !isSameWorkspaceSelection(b.selection, file)));
      return;
    }
    setBasisError(null);
    const sourceMeta = sources.find((s) => String(s.id) === String(file.id));
    setBasisItems((prev) => [
      ...prev,
      {
        key: workspaceTargetKey(file),
        selection: { ...file, origin: 'source' },
        fileType: sourceMeta?.type,
        status: sourceMeta?.status || 'ready',
      },
    ]);
  };

  const handleBasisSelectAll = () => {
    setBasisError(null);
    if (selectableBasisSources.length === 0) return;
    if (basisAllSelected) {
      const selectableIds = new Set(selectableBasisSources.map((s) => String(s.id)));
      setBasisItems((prev) =>
        prev.filter(
          (b) => !(b.selection.origin === 'source' && selectableIds.has(String(b.selection.id)))
        )
      );
      return;
    }
    setBasisItems((prev) => {
      const next = [...prev];
      for (const source of selectableBasisSources) {
        const selection: WorkspaceFileSelection = {
          origin: 'source',
          id: source.id,
          title: source.title,
        };
        const exists = next.some((b) => isSameWorkspaceSelection(b.selection, selection));
        if (exists) continue;
        next.push({
          key: workspaceTargetKey(selection),
          selection,
          fileType: source.type,
          status: source.status || 'ready',
        });
      }
      return next;
    });
  };

  const handleStartReview = () => {
    if (!canStart) return;
    const scope = snapshotScope(DEFAULT_REVIEW_SCOPE);
    const payload: RegulatoryReviewStartPayload = {
      scope,
      targets: pendingTargets.map((t) => ({
        key: t.key,
        title: targetTitle(t),
        sourceLabel:
          t.kind === 'local' ? `本地文件 · ${formatFileSize(t.size)}` : targetSourceLabel(t),
        format: targetFormat(t),
      })),
      basis: visibleBasis.map((b) => ({
        key: b.key,
        title: b.selection.title,
        sourceLabel: '工作空间 · 来源文件',
        format: (b.fileType || 'FILE').toUpperCase(),
      })),
    };
    onStartReview(payload);
  };

  return (
    <div
      className="fixed inset-0 z-[600] flex items-center justify-center bg-slate-900/40 backdrop-blur-sm animate-in fade-in"
      onClick={onClose}
    >
      <div
        className="flex h-[800px] max-h-[85vh] w-[960px] flex-col overflow-hidden rounded-[32px] bg-white shadow-2xl animate-in zoom-in-95 font-bold"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="z-10 flex shrink-0 items-center justify-between border-b border-gray-100 bg-white p-6">
          <div className="flex items-center gap-3">
            <div className="rounded-xl bg-sky-50 p-2 text-sky-600">
              <Scale size={24} strokeWidth={2.5} />
            </div>
            <div>
              <h3 className="text-xl font-extrabold text-slate-800">制度合规审查</h3>
              <p className="mt-0.5 text-[12px] font-bold text-slate-400">
                选择审查对象与审查手册，可选补充审查依据
              </p>
            </div>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="rounded-full bg-slate-50 p-2 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
          >
            <X size={20} />
          </button>
        </div>

        <>
        <div className="custom-scrollbar flex min-h-0 flex-1 flex-col gap-5 overflow-y-auto px-6 py-5">
          {/* 1. 选择审查对象：空态 flex-1 + 最小高度；有文件后沿用空态测高（与合同/脱敏一致） */}
          <section
            ref={uploadSectionRef}
            className={`flex flex-col ${isEmptyState ? 'min-h-0 flex-1' : 'shrink-0'}`}
            style={
              !isEmptyState
                ? { height: uploadSectionHeight || UPLOAD_SECTION_HEIGHT_FALLBACK }
                : { minHeight: UPLOAD_SECTION_MIN_HEIGHT }
            }
          >
            <div className="mb-3 flex shrink-0 items-center justify-between gap-3">
              <h4 className="text-[14px] font-extrabold text-slate-800">选择审查对象</h4>
              <div
                ref={uploadTabListRef}
                className="relative flex items-center rounded-xl border border-slate-200 bg-slate-50/80 p-1"
              >
                <span
                  aria-hidden
                  className="pointer-events-none absolute bottom-1 top-1 rounded-lg bg-white shadow-sm transition-[left,width] duration-300 ease-out"
                  style={{ left: tabPillStyle.left, width: tabPillStyle.width }}
                />
                <button
                  ref={localTabRef}
                  type="button"
                  onClick={() => switchTab('local')}
                  className={`relative z-10 inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[12px] font-bold transition-colors ${
                    activeTab === 'local' ? 'text-sky-700' : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <FolderUp size={14} strokeWidth={2.5} />
                  本地上传
                </button>
                <button
                  ref={workspaceTabRef}
                  type="button"
                  onClick={() => switchTab('workspace')}
                  className={`relative z-10 inline-flex items-center gap-1.5 rounded-lg px-3.5 py-2 text-[12px] font-bold transition-colors ${
                    activeTab === 'workspace'
                      ? 'text-sky-700'
                      : 'text-slate-500 hover:text-slate-700'
                  }`}
                >
                  <FolderOpen size={14} strokeWidth={2.5} />
                  工作空间文件
                </button>
              </div>
            </div>

            <div className="flex min-h-0 flex-1 flex-col">
              {activeTab === 'local' ? (
                <div className="flex min-h-0 flex-1 flex-col animate-in fade-in duration-200">
                  <div
                    role="button"
                    tabIndex={0}
                    onClick={handleDropZoneClick}
                    onKeyDown={(e) => {
                      if (e.key === 'Enter' || e.key === ' ') {
                        e.preventDefault();
                        handleDropZoneClick();
                      }
                    }}
                    onDragOver={(e) => {
                      e.preventDefault();
                      setIsDragging(true);
                    }}
                    onDragLeave={(e) => {
                      e.preventDefault();
                      setIsDragging(false);
                    }}
                    onDrop={(e) => {
                      e.preventDefault();
                      setIsDragging(false);
                      if (e.dataTransfer.files?.length) addLocalFiles(e.dataTransfer.files);
                    }}
                    className={`relative flex min-h-[180px] flex-1 cursor-pointer flex-col items-center justify-center rounded-2xl border border-dashed px-6 py-6 text-center transition-all ${
                      isDragging
                        ? 'border-sky-400 bg-sky-50/80 shadow-sm'
                        : 'border-slate-200 bg-gradient-to-b from-slate-50/80 to-white hover:border-sky-300 hover:bg-sky-50/40'
                    }`}
                  >
                    <div className="relative mb-3 flex h-14 w-14 shrink-0 items-center justify-center rounded-2xl bg-gradient-to-br from-sky-500 to-sky-600 text-white shadow-md shadow-sky-200">
                      <FolderUp size={26} strokeWidth={2.25} />
                      <span className="absolute -bottom-1 -right-1 flex h-6 w-6 items-center justify-center rounded-full bg-white shadow-sm ring-2 ring-sky-100">
                        <Scale size={12} className="text-sky-600" strokeWidth={2.5} />
                      </span>
                    </div>
                    <p className="shrink-0 text-[15px] font-extrabold text-slate-800">
                      拖拽或{' '}
                      <button
                        type="button"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDropZoneClick();
                        }}
                        className="text-sky-600 underline-offset-2 hover:underline"
                      >
                        选择文件
                      </button>{' '}
                      至此处
                    </p>
                    <p className="mt-2 max-w-[520px] shrink-0 text-[12px] font-medium leading-relaxed text-slate-400">
                      支持 txt、doc、docx、纯文本 pdf，单文件不超过 100MB
                      <br />
                      本地与工作空间合计最多 {MAX_TARGETS} 个
                      {atCapacity ? '（已达上限）' : `（还可添加 ${remainingSlots} 个）`}
                    </p>
                    <input
                      ref={fileInputRef}
                      type="file"
                      className="hidden"
                      accept={ACCEPT_ATTR}
                      multiple
                      onChange={handleLocalFileChange}
                    />
                  </div>
                  {uploadError ? (
                    <p className="mt-2 shrink-0 text-[12px] font-bold text-red-500">{uploadError}</p>
                  ) : null}
                </div>
              ) : (
                <div className="flex min-h-0 flex-1 flex-col animate-in fade-in duration-200">
                  <p className="mb-2.5 shrink-0 text-[12px] font-medium text-slate-400">
                    本地与工作空间合计最多 {MAX_TARGETS} 个文件
                    {atCapacity ? '（已达上限）' : `（还可添加 ${remainingSlots} 个）`}
                  </p>
                  <div className="min-h-0 flex-1">
                    <WorkspaceFilePicker
                      sources={sources}
                      conclusions={conclusions}
                      selected={workspaceSelections}
                      onToggle={handleWorkspaceToggle}
                      disableAdd={atCapacity}
                      accent="sky"
                      selectableCountLabel="可选文件"
                      emptySourcesText="暂无可选的来源文件（仅支持已就绪的文档类文件）"
                      emptyConclusionsText="暂无可选的生成结果（仅支持已完成的结果）"
                    />
                  </div>
                  {uploadError ? (
                    <p className="mt-2 shrink-0 text-[12px] font-bold text-red-500">{uploadError}</p>
                  ) : null}
                </div>
              )}
            </div>
          </section>

          {/* 2. 待审查对象：有文件后随内容增高，不局部滚动 */}
          <section className="shrink-0">
            <div className="mb-2.5 flex items-center justify-between gap-3">
              <h4 className="text-[14px] font-extrabold text-slate-800">待审查对象</h4>
              <span className="text-[12px] font-bold text-slate-400">
                {pendingTargets.length}/{MAX_TARGETS}
              </span>
            </div>
            {isEmptyState ? (
              <div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50/50 px-4 py-5 text-center text-[12px] font-medium text-slate-400">
                从上方本地上传或工作空间选择文件后，将在此汇总展示
              </div>
            ) : (
              <div className="grid grid-cols-1 gap-2.5 sm:grid-cols-2">
                {pendingTargets.map((target) => {
                  const title = targetTitle(target);
                  const subtitle =
                    target.kind === 'local'
                      ? `本地文件 · ${formatFileSize(target.size)}`
                      : target.selection.origin === 'source'
                        ? '工作空间文件 · 来源文件'
                        : '工作空间文件 · 生成结果';
                  return (
                    <div
                      key={target.key}
                      className="flex items-center gap-3 rounded-2xl border border-slate-200 bg-white px-3.5 py-2.5 shadow-sm"
                    >
                      <span className="flex h-9 w-9 shrink-0 items-center justify-center rounded-xl bg-sky-50 text-sky-600">
                        <FileText size={16} strokeWidth={2.5} />
                      </span>
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-[13px] font-bold text-slate-800">{title}</div>
                        <div className="truncate text-[11px] font-medium text-slate-400">
                          {subtitle}
                        </div>
                      </div>
                      <button
                        type="button"
                        onClick={() => removePendingTarget(target.key)}
                        className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
                        aria-label={`移除 ${title}`}
                      >
                        <X size={15} />
                      </button>
                    </div>
                  );
                })}
              </div>
            )}
          </section>

          {/* 3. 审查手册（与脱敏「脱敏规则」同层；默认项锁定不可取消） */}
          <section className="shrink-0">
            <div className="mb-2.5 flex items-center gap-2">
              <ShieldCheck size={16} className="text-sky-600" strokeWidth={2.5} />
              <h4 className="text-[14px] font-extrabold text-slate-800">审查手册</h4>
            </div>
            <div className="grid grid-cols-1 gap-2.5">
              <div className="flex w-full items-center gap-3 rounded-2xl border border-sky-300 bg-sky-50/70 px-4 py-3.5 shadow-sm">
                <button
                  type="button"
                  aria-disabled
                  className="flex h-5 w-5 shrink-0 cursor-default items-center justify-center rounded-md border-2 border-sky-600 bg-sky-600"
                  aria-label="默认审查手册（不可取消）"
                >
                  <Check size={12} className="text-white" strokeWidth={3} />
                </button>
                <div className="min-w-0 flex-1 cursor-default text-left">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="text-[14px] font-extrabold text-slate-800">
                      {DEFAULT_REVIEW_SCOPE.name}
                    </span>
                    <span className="rounded-md bg-white px-1.5 py-0.5 text-[10px] font-extrabold text-sky-600 ring-1 ring-sky-200">
                      默认
                    </span>
                  </div>
                  <p className="mt-1.5 line-clamp-2 text-[12px] font-medium leading-relaxed text-slate-500">
                    {DEFAULT_REVIEW_SCOPE.desc}
                  </p>
                </div>
              </div>
            </div>
          </section>
        </div>

        <div className="flex shrink-0 items-center justify-end gap-3 border-t border-slate-100 bg-white px-6 py-4">
          {!canStart ? (
            <p className="mr-auto text-[12px] font-bold text-slate-400">
              请至少选择 1 个待审查对象
            </p>
          ) : (
            <p className="mr-auto text-[12px] font-medium text-slate-400">
              {visibleBasis.length > 0
                ? `已选 ${visibleBasis.length} 个审查依据（来源文件）`
                : '未选审查依据时，将仅基于制度正文与审查手册'}
            </p>
          )}
          <div ref={basisPanelRef} className="relative">
            <button
              type="button"
              onClick={() => {
                setBasisError(null);
                setBasisPanelOpen((v) => !v);
              }}
              className={`inline-flex items-center gap-1.5 rounded-2xl border px-4 py-2.5 text-[13px] font-bold transition-all ${
                basisPanelOpen
                  ? 'border-sky-200 bg-sky-50 text-sky-700'
                  : 'border-slate-200 bg-white text-slate-600 hover:border-sky-200 hover:bg-sky-50/60 hover:text-sky-700'
              }`}
            >
              <Library size={15} strokeWidth={2.5} />
              审查依据
              {visibleBasis.length > 0 ? (
                <span className="rounded-md bg-sky-100 px-1.5 py-0.5 text-[11px] font-extrabold text-sky-700">
                  {visibleBasis.length}
                </span>
              ) : null}
              <ChevronDown
                size={14}
                strokeWidth={2.5}
                className={`transition-transform ${basisPanelOpen ? 'rotate-180' : ''}`}
              />
            </button>
            {basisPanelOpen ? (
              <div
                className="absolute bottom-full right-0 z-[80] mb-2 w-[260px] overflow-hidden rounded-2xl border border-slate-200/80 bg-white shadow-xl animate-in fade-in zoom-in-95 origin-bottom-right"
                onClick={(e) => e.stopPropagation()}
              >
                <div className="flex items-center justify-between gap-2 border-b border-sky-50 bg-sky-50/70 px-3 py-2">
                  <span className="text-[12px] font-bold text-sky-700/80">来源</span>
                  <button
                    type="button"
                    disabled={selectableBasisSources.length === 0}
                    onClick={handleBasisSelectAll}
                    className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border transition-colors ${
                      selectableBasisSources.length === 0
                        ? 'cursor-not-allowed border-slate-200 bg-slate-50'
                        : basisAllSelected
                          ? 'border-sky-600 bg-sky-600 text-white'
                          : basisSomeSelected
                            ? 'border-sky-600 bg-sky-100 text-sky-600'
                            : 'border-slate-300 bg-white hover:border-sky-400'
                    }`}
                    aria-label={basisAllSelected ? '取消全选' : '全选来源'}
                    title={basisAllSelected ? '取消全选' : '全选'}
                  >
                    {basisAllSelected ? (
                      <Check size={10} strokeWidth={3} />
                    ) : basisSomeSelected ? (
                      <span className="h-0.5 w-2 rounded-full bg-sky-600" />
                    ) : null}
                  </button>
                </div>
                <div className="custom-scrollbar max-h-[320px] overflow-y-auto px-1.5 pb-1.5">
                  {basisSourceOptions.length === 0 ? (
                    <div className="px-2 py-5 text-center text-[11px] font-medium text-slate-400">
                      暂无来源文件
                    </div>
                  ) : (
                    <div className="space-y-0.5">
                      {basisSourceOptions.map((source) => {
                        const selection: WorkspaceFileSelection = {
                          origin: 'source',
                          id: source.id,
                          title: source.title,
                        };
                        const inTargets = pendingTargets.some(
                          (t) =>
                            t.kind === 'workspace' &&
                            isSameWorkspaceSelection(t.selection, selection)
                        );
                        const selected =
                          !inTargets &&
                          basisItems.some((b) => isSameWorkspaceSelection(b.selection, selection));
                        return (
                          <button
                            key={String(source.id)}
                            type="button"
                            disabled={inTargets}
                            title={inTargets ? '已在待审查对象中' : source.title}
                            onClick={() => handleBasisToggle(selection)}
                            className={`flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left text-slate-600 transition-colors ${
                              inTargets ? 'cursor-not-allowed opacity-40' : 'hover:bg-slate-50'
                            }`}
                          >
                            {basisSourceIcon(source.type)}
                            <span className="min-w-0 flex-1 truncate text-[12px] font-medium">
                              {source.title}
                            </span>
                            <span
                              className={`flex h-4 w-4 shrink-0 items-center justify-center rounded border ${
                                selected
                                  ? 'border-sky-600 bg-sky-600 text-white'
                                  : 'border-slate-300 bg-white'
                              }`}
                              aria-hidden
                            >
                              {selected ? <Check size={10} strokeWidth={3} /> : null}
                            </span>
                          </button>
                        );
                      })}
                    </div>
                  )}
                </div>
                {basisError ? (
                  <p className="border-t border-slate-100 px-3 py-1.5 text-[11px] font-bold text-red-500">
                    {basisError}
                  </p>
                ) : null}
              </div>
            ) : null}
          </div>
          <button
            type="button"
            disabled={!canStart}
            onClick={handleStartReview}
            className={`rounded-2xl px-6 py-2.5 text-[13px] font-bold transition-all ${
              canStart
                ? 'bg-sky-600 text-white shadow-lg shadow-sky-200 hover:bg-sky-700 active:scale-95'
                : 'cursor-not-allowed bg-slate-100 text-slate-300'
            }`}
          >
            开始审查
          </button>
        </div>
        </>
      </div>
    </div>
  );
}
