/**
 * 制度合规审查 · 审查手册
 * 当前仅保留默认合规审查（不可取消）
 */

export type RegulatoryReviewScope = {
  id: string;
  name: string;
  desc: string;
  /** 审查层标签，用于进度与结果展示 */
  layers: string[];
  isDefault?: boolean;
};

export const DEFAULT_SCOPE_ID = 'scope-default';

export const DEFAULT_REVIEW_SCOPE: RegulatoryReviewScope = {
  id: DEFAULT_SCOPE_ID,
  name: '默认合规审查',
  desc: '覆盖制度完整性与体系衔接、制定依据、权限边界、内部一致性与语言文字规范。',
  layers: ['制度完整性', '制定依据', '权限边界', '内部一致性', '语言文字'],
  isDefault: true,
};

/** 可选审查手册列表（目前仅默认项） */
export const PRESET_REVIEW_SCOPES: RegulatoryReviewScope[] = [DEFAULT_REVIEW_SCOPE];

export function snapshotScope(scope: RegulatoryReviewScope = DEFAULT_REVIEW_SCOPE): RegulatoryReviewScope {
  return {
    id: scope.id,
    name: scope.name,
    desc: scope.desc,
    layers: [...scope.layers],
    isDefault: scope.isDefault,
  };
}
