import React from 'react';
import type {
  CivilCaseReport,
  EvidenceCheck,
  EvidenceRow,
  ElementRow,
  RiskItem,
  StrategyRow,
  TimelineRow,
} from './civilCaseTypes';

type Props = {
  report: CivilCaseReport;
};

const STRENGTH_STYLE: Record<ElementRow['strength'], string> = {
  强: 'bg-green-50 text-green-700 ring-green-200',
  中等: 'bg-amber-50 text-amber-700 ring-amber-200',
  弱: 'bg-slate-50 text-slate-600 ring-slate-200',
  无: 'bg-slate-50 text-slate-400 ring-slate-200',
};

const SEVERITY_STYLE: Record<RiskItem['severity'], string> = {
  高: 'bg-red-50 text-red-700 ring-red-200',
  中: 'bg-amber-50 text-amber-700 ring-amber-200',
  低: 'bg-slate-50 text-slate-600 ring-slate-200',
};

const IMPORTANCE_STYLE: Record<TimelineRow['importance'], string> = {
  关键: 'bg-red-50 text-red-700 ring-red-200',
  相关: 'bg-amber-50 text-amber-700 ring-amber-200',
  背景: 'bg-slate-50 text-slate-500 ring-slate-200',
};

const VERDICT_STYLE: Record<EvidenceCheck['authenticity'], string> = {
  '✅ 可初步支持': 'bg-green-50 text-green-700 ring-green-200',
  '✅ + ⚠️ 保留并提请律师判断': 'bg-amber-50 text-amber-700 ring-amber-200',
  '❌ 建议排除（待律师确认）': 'bg-red-50 text-red-700 ring-red-200',
};

const CITE_KIND_STYLE: Record<string, string> = {
  law: 'bg-blue-50 text-blue-700 ring-blue-200',
  case: 'bg-violet-50 text-violet-700 ring-violet-200',
  material: 'bg-slate-50 text-slate-600 ring-slate-200',
};

function SectionHeading({ children }: { children: React.ReactNode }) {
  return (
    <h2 className="mb-3 mt-9 border-b border-slate-200 pb-2 text-[16px] font-extrabold tracking-wide text-slate-900 first:mt-0">
      {children}
    </h2>
  );
}

function MetaRow({ label, value }: { label: string; value: string }) {
  return (
    <tr>
      <td className="w-[128px] border border-slate-200 bg-slate-50 px-3 py-2.5 text-[12.5px] font-extrabold text-slate-600">
        {label}
      </td>
      <td className="border border-slate-200 px-3 py-2.5 text-[13px] font-medium leading-relaxed text-slate-800">
        {value}
      </td>
    </tr>
  );
}

function Table({ head, children }: { head: string[]; children: React.ReactNode }) {
  return (
    <div className="overflow-x-auto rounded-lg border border-slate-200">
      <table className="w-full min-w-[720px] border-collapse text-left">
        <thead>
          <tr className="bg-slate-50">
            {head.map((h) => (
              <th
                key={h}
                className="border-b border-slate-200 px-2.5 py-2.5 text-[11px] font-extrabold tracking-wide text-slate-500"
              >
                {h}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>{children}</tbody>
      </table>
    </div>
  );
}

function Badge({ text, style }: { text: string; style: string }) {
  return (
    <span className={`inline-flex rounded-md px-1.5 py-0.5 text-[11px] font-extrabold ring-1 ${style}`}>
      {text}
    </span>
  );
}

function TimelineSection({ rows }: { rows: TimelineRow[] }) {
  return (
    <Table head={['日期', '事件', '重要性', '来源定位']}>
      {rows.map((r, i) => (
        <tr key={i} className="align-top hover:bg-slate-50/70">
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold text-slate-700">{r.date}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.event}</td>
          <td className="border-b border-slate-100 px-2.5 py-3">
            <Badge text={r.importance} style={IMPORTANCE_STYLE[r.importance]} />
          </td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{r.source}</td>
        </tr>
      ))}
    </Table>
  );
}

function ElementTable({ rows }: { rows: ElementRow[] }) {
  return (
    <Table head={['请求权/抗辩', '要件', '控制性依据', '支持证据', '相反证据', '强度', '状态', '缺口']}>
      {rows.map((r, i) => (
        <tr key={i} className="align-top hover:bg-slate-50/70">
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold text-slate-800">{r.claim}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.element}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{r.basis}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.supportEvidences}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.contraryEvidences}</td>
          <td className="border-b border-slate-100 px-2.5 py-3">
            <Badge text={r.strength} style={STRENGTH_STYLE[r.strength]} />
          </td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.status}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-500">{r.gap}</td>
        </tr>
      ))}
    </Table>
  );
}

function EvidenceTable({ rows }: { rows: EvidenceRow[] }) {
  return (
    <Table head={['编号', '名称', '类型/载体', '来源与定位', '形成时间', '原件状态', '证明内容', '拟证明目的/要件']}>
      {rows.map((r) => (
        <tr key={r.id} className="align-top hover:bg-slate-50/70">
          <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-bold text-slate-500">{r.id}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold text-slate-800">{r.name}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.type}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{r.source}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{r.date}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{r.original}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.content}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.purpose}</td>
        </tr>
      ))}
    </Table>
  );
}

function StrategyTable({ rows }: { rows: StrategyRow[] }) {
  return (
    <Table head={['请求权/抗辩', '要件', '我方路径', '对方路径/突破点', '证据缺口', '下一步']}>
      {rows.map((r, i) => (
        <tr key={i} className="align-top hover:bg-slate-50/70">
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold text-slate-800">{r.claim}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.element}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.ourPath}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.theirPath}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-500">{r.evidenceGap}</td>
          <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{r.next}</td>
        </tr>
      ))}
    </Table>
  );
}

function StringList({ items }: { items: string[] }) {
  return (
    <ol className="list-decimal space-y-2 pl-5 text-[13px] font-medium leading-[1.85] text-slate-700">
      {items.map((item, index) => (
        <li key={index} className="pl-1">
          {item}
        </li>
      ))}
    </ol>
  );
}

export default function CivilCaseAnalysisReportPreview({ report }: Props) {
  const r = report;
  return (
    <div className="w-full max-w-[900px] shrink-0">
      <article className="min-h-[1100px] rounded-sm border border-gray-200 bg-white px-10 py-12 shadow-md sm:px-14 sm:py-14 lg:px-16 lg:py-16">
        <header className="mb-8 text-center">
          <h1 className="text-[20px] font-extrabold leading-snug tracking-wide text-slate-900 sm:text-[22px]">
            {r.documentTitle}
          </h1>
          <p className="mt-2 text-[18px] font-extrabold tracking-[0.12em] text-orange-600">{r.subtitle}</p>
        </header>

        <table className="mb-2 w-full border-collapse">
          <tbody>
            <MetaRow label="案件名称" value={r.caseName} />
            <MetaRow label="我方立场" value={r.ourSide} />
            <MetaRow label="案由/管辖" value={`${r.claimType}；${r.venue}`} />
            <MetaRow label="程序阶段" value={r.stage} />
            <MetaRow label="分析范围" value={r.directionLabel} />
            <MetaRow label="检索范围" value={r.searchLabel} />
            <MetaRow label="报告日期" value={r.reviewDate} />
          </tbody>
        </table>

        <h3 className="mb-2 mt-6 text-[14px] font-extrabold text-slate-800">案情信息</h3>
        <div className="mb-1 rounded-xl border border-slate-200 bg-slate-50/50 px-4 py-3">
          <p className="whitespace-pre-wrap text-[13px] font-medium leading-[1.9] text-slate-700">
            {r.caseInfoText || '（未提供文字案情信息，请以所选案件材料为准）'}
          </p>
        </div>

        <SectionHeading>二、法规、司法解释与类案检索核验</SectionHeading>
        <div className="space-y-2">
          {r.cites.map((c, i) => (
            <div key={i} className="flex items-start gap-2 rounded-xl border border-slate-200 px-3.5 py-2.5">
              <Badge text={c.kind === 'law' ? '法规' : c.kind === 'case' ? '案例' : '材料'} style={CITE_KIND_STYLE[c.kind]} />
              <div className="min-w-0">
                <div className="text-[13px] font-bold leading-relaxed text-slate-800">{c.title}</div>
                <div className="text-[11.5px] font-medium text-slate-400">{c.note}</div>
              </div>
            </div>
          ))}
        </div>

        {r.research ? (
          <>
            <SectionHeading>三、案件基础分析</SectionHeading>
            <div className="mb-4">
              <TimelineSection rows={r.research.timeline} />
            </div>
            <div className="mb-4">
              <ElementTable rows={r.research.elements} />
            </div>
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">3.4 当前态势与研究简报</h3>
            <p className="text-[13px] font-medium leading-[1.9] text-slate-700">{r.research.situation}</p>
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">3.5 待核验与下一研究动作</h3>
            <StringList items={r.research.openQuestions} />
          </>
        ) : null}

        {r.evidence ? (
          <>
            <SectionHeading>四、证据梳理</SectionHeading>
            <div className="mb-4">
              <EvidenceTable rows={r.evidence.catalog} />
            </div>
            <div className="mb-4">
              <ElementTable rows={r.evidence.elementMap} />
            </div>
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">4.5 证据三性初检</h3>
            <Table head={['编号', '名称', '三性初检', '说明']}>
              {r.evidence.checks.map((ch) => (
                <tr key={ch.id} className="align-top hover:bg-slate-50/70">
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-bold text-slate-500">{ch.id}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold text-slate-800">{ch.name}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3">
                    <Badge text={ch.authenticity} style={VERDICT_STYLE[ch.authenticity]} />
                  </td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">
                    {ch.legality}；{ch.relevance}
                  </td>
                </tr>
              ))}
            </Table>
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">4.6 模式观察与补证计划</h3>
            <StringList items={r.evidence.supplement} />
          </>
        ) : null}

        {r.strategy ? (
          <>
            <SectionHeading>五、策略制定</SectionHeading>
            <div className="mb-4">
              <StrategyTable rows={r.strategy.matrix} />
            </div>
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">5.3 论点与反驳计划</h3>
            <StringList items={r.strategy.arguments} />
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">5.7 风险重评估</h3>
            <Table head={['风险', '可能敞口', '发生条件', '等级', '紧迫度']}>
              {r.strategy.risks.map((risk, i) => (
                <tr key={i} className="align-top hover:bg-slate-50/70">
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-bold text-slate-800">{risk.risk}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{risk.exposure}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{risk.condition}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3">
                    <Badge text={risk.severity} style={SEVERITY_STYLE[risk.severity]} />
                  </td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{risk.urgency}</td>
                </tr>
              ))}
            </Table>
            <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">5.8 未来 7/30 天行动清单</h3>
            <Table head={['时间窗口', '动作', '责任对象', '依赖']}>
              {r.strategy.actions.map((a, i) => (
                <tr key={i} className="align-top hover:bg-slate-50/70">
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-bold text-slate-500">{a.window}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-700">{a.action}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[12px] font-medium text-slate-600">{a.owner}</td>
                  <td className="border-b border-slate-100 px-2.5 py-3 text-[11.5px] font-medium text-slate-500">{a.depends}</td>
                </tr>
              ))}
            </Table>
          </>
        ) : null}

        <SectionHeading>六、综合结论、风险提示与下一步</SectionHeading>
        <p className="rounded-lg border border-orange-100 bg-orange-50/60 px-4 py-3 text-[13.5px] font-bold leading-[1.9] text-slate-800">
          {r.conclusion}
        </p>
        <p className="mt-3 text-[13px] font-medium leading-[1.9] text-slate-700">
          <span className="font-extrabold text-slate-800">未覆盖模块/研究边界：</span>
          {r.unCovered}
        </p>
        <h3 className="mb-2 mt-5 text-[14px] font-extrabold text-slate-800">待律师判断、待核验事项及建议行动</h3>
        <StringList items={r.nextSteps} />
        <p className="mt-3 text-[12px] font-medium leading-[1.9] text-slate-500">本次主要依据：{r.mainReferences}</p>

        <blockquote className="mt-8 border-l-4 border-slate-300 bg-slate-50 px-4 py-3 text-[12.5px] font-medium leading-[1.9] text-slate-600">
          本报告由律爱多（北大法宝旗下 AI 法律产品）生成，仅供法律分析与业务决策参考；最终结论请以已核验来源及专业人员意见为准。更多法律能力，请前往律爱多：https://ai.pkulaw.com/apps/lawyerAssist/
        </blockquote>
      </article>
    </div>
  );
}
