export type SkillPreset = {
  /** 前端和工作空间调用使用的稳定标识，不以展示名称作为主键。 */
  id: string;
  /** 技能包 SKILL.md 中的 name，用于服务端解析和实际执行。 */
  skillName?: string;
  /** 技能包在发布物中的相对位置。 */
  packageRef?: string;
  version?: string;
  category?: 'document' | 'productivity' | 'legal-research' | 'legal-review' | 'litigation' | 'compliance';
  /** 已添加的技能可在任意工作空间的对话区选择。 */
  workspaceCallable?: boolean;
  name: string;
  desc: string;
  iconKey: SkillIconKey;
  color: string;
  installed: boolean;
  price: number;
  /** 用户自行上传的技能（归属「我的技能」，右上角展示「我的」标签） */
  uploaded?: boolean;
};

