import raw from './mockAnnotatedWordData.json';

export type ReviewCommentSeverity = '严重' | '高' | '中' | '低';

export type AnnotatedWordSegment = {
  type: 'text' | 'del' | 'ins';
  text: string;
  commentIds: string[];
  /** 对应修订条目 id（红线删除/新增） */
  revisionId?: string;
};

export type AnnotatedWordBlock =
  | {
      style: 'title' | 'article' | 'party' | 'body';
      segments: AnnotatedWordSegment[];
    }
  | {
      style: 'sign-table';
      rows: string[][];
    };

export type AnnotatedWordComment = {
  id: string;
  severity: ReviewCommentSeverity;
  body: string;
  author: string;
  /** 批注覆盖的条款摘录（打开时派生） */
  quote?: string;
};

export type AnnotatedWordRevisionKind = 'replace' | 'insert' | 'delete';

/** Word 修订模式下的删除 / 新增（可与批注关联） */
export type AnnotatedWordRevision = {
  id: string;
  kind: AnnotatedWordRevisionKind;
  deletedText: string;
  insertedText: string;
  author: string;
  commentIds: string[];
};

export type AnnotatedWordDocument = {
  title: string;
  subtitle: string;
  comments: AnnotatedWordComment[];
  revisions: AnnotatedWordRevision[];
  blocks: AnnotatedWordBlock[];
};

/** 浮层统一条目：批注或修订 */
export type ReviewResultItem =
  | {
      kind: 'comment';
      id: string;
      severity: ReviewCommentSeverity;
      body: string;
      author: string;
      quote?: string;
    }
  | {
      kind: 'revision';
      id: string;
      revisionKind: AnnotatedWordRevisionKind;
      deletedText: string;
      insertedText: string;
      author: string;
      relatedCommentId?: string;
    };

function isSegmentBlock(
  block: AnnotatedWordBlock
): block is Extract<AnnotatedWordBlock, { segments: AnnotatedWordSegment[] }> {
  return block.style !== 'sign-table';
}

/** 为每条批注补一段原文摘录，便于浮层展示 */
function withCommentQuotes(doc: AnnotatedWordDocument): AnnotatedWordDocument {
  const quotes = new Map<string, string>();
  doc.blocks.forEach((block) => {
    if (!isSegmentBlock(block)) return;
    block.segments.forEach((seg) => {
      seg.commentIds.forEach((cid) => {
        if (!quotes.has(cid) && seg.text.trim()) {
          quotes.set(cid, seg.text.trim().slice(0, 72));
        }
      });
    });
  });
  return {
    ...doc,
    comments: doc.comments.map((c) => ({
      ...c,
      quote: quotes.get(c.id) || c.quote,
    })),
    revisions: doc.revisions || [],
  };
}

/**
 * 模拟合同审查交付物：带批注/红线的 Word 文档（基于示例
 * 《软件开发与技术服务合同_采购方审查红线版.docx》）
 */
export function buildMockAnnotatedWordDocument(options?: {
  fileTitle?: string;
}): AnnotatedWordDocument {
  const base = raw as AnnotatedWordDocument;
  const titled = options?.fileTitle
    ? {
        ...base,
        title: options.fileTitle.endsWith('.docx')
          ? options.fileTitle
          : `${options.fileTitle.replace(/\.[^.]+$/, '')}_采购方审查红线版.docx`,
      }
    : base;
  return withCommentQuotes({
    ...titled,
    revisions: titled.revisions || [],
  });
}

export function countCommentsBySeverity(comments: AnnotatedWordComment[]) {
  const counts: Record<ReviewCommentSeverity, number> = {
    严重: 0,
    高: 0,
    中: 0,
    低: 0,
  };
  comments.forEach((c) => {
    if (counts[c.severity] != null) counts[c.severity] += 1;
    else counts['高'] += 1;
  });
  return counts;
}

/** 合并批注 + 修订，供审查结果浮层展示 */
export function buildReviewResultItems(doc: AnnotatedWordDocument): ReviewResultItem[] {
  const comments: ReviewResultItem[] = doc.comments.map((c) => ({
    kind: 'comment',
    id: c.id,
    severity: c.severity,
    body: c.body,
    author: c.author,
    quote: c.quote,
  }));
  const revisions: ReviewResultItem[] = (doc.revisions || []).map((r) => ({
    kind: 'revision',
    id: r.id,
    revisionKind: r.kind,
    deletedText: r.deletedText,
    insertedText: r.insertedText,
    author: r.author,
    relatedCommentId: r.commentIds[0],
  }));
  return [...comments, ...revisions];
}
