/** 回答区与参考来源区可拖拽分割：单侧最小宽度与左侧主内容区一致（px）；手柄宽度 */
const SPLIT_MIN_LEFT_PX = 400;
const SPLIT_MIN_RIGHT_PX = SPLIT_MIN_LEFT_PX;
const SPLIT_HANDLE_PX = 6;
const SPLIT_DRAG_THRESHOLD_PX = 4;
const SPLIT_TRANSITION_MS = 300;
/** 左右宽度差低于此值视为接近均衡（px） */
const SPLIT_BALANCE_THRESHOLD_PX = 40;
/** 右侧来源栏宽度低于此值时，将「收录到知识库 / 添加到工作空间」收成「继续」菜单 */
const SOURCE_ASIDE_ACTIONS_COMPACT_MAX_PX = 380;

type SplitLayoutPreset = 'answer_wide' | 'source_wide' | 'custom';

type SourcePanelTab = 'reference' | 'match';

function getSplitBounds(containerWidth: number) {
  const available = containerWidth - SPLIT_HANDLE_PX;
  const maxRight = Math.max(SPLIT_MIN_RIGHT_PX, available - SPLIT_MIN_LEFT_PX);
  return { available, maxRight };
}

function rightWidthForPreset(preset: Exclude<SplitLayoutPreset, 'custom'>, containerWidth: number) {
  const { maxRight } = getSplitBounds(containerWidth);
  // 与拖动极限对齐：左宽右窄 = 右栏最窄；左窄右宽 = 右栏最宽
  if (preset === 'answer_wide') return SPLIT_MIN_RIGHT_PX;
  return maxRight;
}

function resolveSplitPresetOnClick(
  mode: SplitLayoutPreset,
  containerWidth: number,
  rightWidth: number
): Exclude<SplitLayoutPreset, 'custom'> {
  if (mode === 'answer_wide') return 'source_wide';
  if (mode === 'source_wide') return 'answer_wide';

  const answerWideRight = rightWidthForPreset('answer_wide', containerWidth);
  const sourceWideRight = rightWidthForPreset('source_wide', containerWidth);
  const leftWidth = containerWidth - SPLIT_HANDLE_PX - rightWidth;
  const diff = leftWidth - rightWidth;

  if (Math.abs(diff) <= SPLIT_BALANCE_THRESHOLD_PX) return 'answer_wide';

  // 自定义比例：按当前位置切换至对侧预设，避免拖到极限后点击反而往同侧预设回缩
  const midpoint = (answerWideRight + sourceWideRight) / 2;
  return rightWidth >= midpoint ? 'answer_wide' : 'source_wide';
}

function clampRightWidth(width: number, containerWidth: number) {
  const { maxRight } = getSplitBounds(containerWidth);
  return Math.min(Math.max(width, SPLIT_MIN_RIGHT_PX), maxRight);
}

const REF_PAGE_SIZE = 10;

function buildPagination(totalPages: number, current: number): (number | 'ellipsis')[] {
  if (totalPages <= 0) return [];
  if (totalPages <= 7) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }
  if (current <= 4) {
    return [1, 2, 3, 4, 'ellipsis', totalPages];
  }
  /* 靠近末页时展示尾部连续页码（避免第 5 页误用此分支） */
  if (current >= totalPages - 2) {
    return [1, 'ellipsis', totalPages - 3, totalPages - 2, totalPages - 1, totalPages];
  }
  return [1, 'ellipsis', current - 1, current, current + 1, 'ellipsis', totalPages];
}

type SearchResultsViewProps = {
  submittedQuery: string;
  modelId: string;
  thinkingEnabled: boolean;
  searchMode: SearchMode;
  setSearchMode: (m: SearchMode) => void;
  sources: SearchSources;
  toggleSource: (k: SearchSourceKey) => void;
  followUp: string;
  setFollowUp: (v: string) => void;
  onFollowUpSubmit: () => void;
  onNewSearch: () => void;
};

const SearchResultsView: React.FC<SearchResultsViewProps> = ({
  submittedQuery,
  modelId,
  thinkingEnabled,
  searchMode,
  setSearchMode,
  sources,
  toggleSource,
  followUp,
  setFollowUp,
  onFollowUpSubmit,
  onNewSearch,
}) => {
  const data = useMemo(() => buildMockSearchResult(submittedQuery), [submittedQuery]);
  const [page, setPage] = useState(1);
  const [matchPage, setMatchPage] = useState(1);
  const [sourcePanelTab, setSourcePanelTab] = useState<SourcePanelTab>('reference');
  const [activeMatchConditionGroupId, setActiveMatchConditionGroupId] = useState<string>(
    () => data.matchConditionGroups[0]?.id ?? ''
  );
  const [turns, setTurns] = useState<ConversationTurn[]>(() => [
    createInitialTurn(data.answerMarkdown, data.referenceSources),
  ]);
  const [activeSourceTurnId, setActiveSourceTurnId] = useState(INITIAL_TURN_ID);
  const [filterOpen, setFilterOpen] = useState(false);
  const [referenceAppliedFilters, setReferenceAppliedFilters] = useState<SourceListFilters>(
    () => defaultSourceListFilters()
  );
  const [referenceDraftFilters, setReferenceDraftFilters] = useState<SourceListFilters>(
    () => defaultSourceListFilters()
  );
  const [matchAppliedFilters, setMatchAppliedFilters] = useState<SourceListFilters>(
    () => defaultSourceListFilters()
  );
  const [matchDraftFilters, setMatchDraftFilters] = useState<SourceListFilters>(
    () => defaultSourceListFilters()
  );
  const [pinById, setPinById] = useState<Record<string, boolean>>({});
  const [continueMenuOpen, setContinueMenuOpen] = useState(false);
  const [answerMoreMenuTurnId, setAnswerMoreMenuTurnId] = useState<string | null>(null);
  const [answerFeedbackByTurnId, setAnswerFeedbackByTurnId] = useState<
    Record<string, 'like' | 'dislike'>
  >({});
  const [dislikeFeedbackOpenTurnId, setDislikeFeedbackOpenTurnId] = useState<string | null>(null);
  const [dislikeFeedbackDraftByTurnId, setDislikeFeedbackDraftByTurnId] = useState<
    Record<string, AnswerFeedbackDraft>
  >({});
  const [copyTipTurnId, setCopyTipTurnId] = useState<string | null>(null);
  const [reportModalTurnId, setReportModalTurnId] = useState<string | null>(null);
  const [reportJobsByTurnId, setReportJobsByTurnId] = useState<Record<string, SearchReportTurnJobs>>({});
  const [previewReportDocument, setPreviewReportDocument] =
    useState<SearchReportGeneratedDocument | null>(null);
  const [generationByTurnId, setGenerationByTurnId] = useState<
    Record<string, TurnAnswerGenerationSnapshot>
  >({});
  const cancelGenerationRef = useRef<Record<string, () => void>>({});
  const continueMenuRef = useRef<HTMLDivElement>(null);
  const answerMoreMenuRef = useRef<HTMLDivElement>(null);
  const [saveToastMsg, setSaveToastMsg] = useState('');
  const saveToastTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const copyTipTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const answerScrollRef = useRef<HTMLDivElement>(null);
  const scrollToConversationEndRef = useRef(false);

  const splitContainerRef = useRef<HTMLDivElement>(null);
  const [rightPanelWidth, setRightPanelWidth] = useState(SPLIT_MIN_RIGHT_PX);
  const [splitLayoutMode, setSplitLayoutMode] = useState<SplitLayoutPreset>('answer_wide');
  const [splitAnimating, setSplitAnimating] = useState(false);
  const splitPointerRef = useRef<{
    startX: number;
    startRightWidth: number;
    didDrag: boolean;
  } | null>(null);
  const splitAnimTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const cancelTurnGeneration = useCallback((turnId: string) => {
    cancelGenerationRef.current[turnId]?.();
    delete cancelGenerationRef.current[turnId];
    setGenerationByTurnId((prev) => {
      if (!(turnId in prev)) return prev;
      const next = { ...prev };
      delete next[turnId];
      return next;
    });
  }, []);

  const startTurnGeneration = useCallback(
    (turnId: string, targetMarkdown: string) => {
      cancelTurnGeneration(turnId);
      setGenerationByTurnId((prev) => ({ ...prev, [turnId]: { stepIndex: 0 } }));
      cancelGenerationRef.current[turnId] = startSearchAnswerGeneration({
        targetMarkdown,
        onStepChange: (stepIndex) => {
          setGenerationByTurnId((prev) => ({ ...prev, [turnId]: { stepIndex } }));
        },
        onStreamUpdate: (partial) => {
          setTurns((prev) =>
            prev.map((t) => (t.id === turnId ? { ...t, answerMarkdown: partial } : t))
          );
        },
        onComplete: () => {
          cancelTurnGeneration(turnId);
        },
      });
    },
    [cancelTurnGeneration]
  );

  const resolveTurnTargetMarkdown = useCallback(
    (turn: ConversationTurn): string => {
      if (turn.kind === 'initial') return data.answerMarkdown;
      if (turn.userPrompt === FILTER_BASED_TURN_PROMPT) {
        const sources = data.referenceSources.filter((s) => turn.sourceIds.includes(s.id));
        return buildAnswerMarkdownFromFilteredSources(submittedQuery, sources);
      }
      return buildFollowUpAnswerMarkdown(turn.userPrompt ?? '');
    },
    [data.answerMarkdown, data.referenceSources, submittedQuery]
  );

  useEffect(() => {
    setPinById({});
    setPage(1);
    setMatchPage(1);
    setSourcePanelTab('reference');
    setActiveMatchConditionGroupId(data.matchConditionGroups[0]?.id ?? '');
    const defaultFilters = defaultSourceListFilters();
    setReferenceAppliedFilters(defaultFilters);
    setReferenceDraftFilters(defaultFilters);
    setMatchAppliedFilters(defaultFilters);
    setMatchDraftFilters(defaultFilters);
    Object.values(cancelGenerationRef.current).forEach((cancel) => cancel());
    cancelGenerationRef.current = {};
    setGenerationByTurnId({});
    setAnswerMoreMenuTurnId(null);
    setAnswerFeedbackByTurnId({});
    setDislikeFeedbackOpenTurnId(null);
    setDislikeFeedbackDraftByTurnId({});

    const initial = createInitialTurn('', data.referenceSources);
    setTurns([initial]);
    setActiveSourceTurnId(INITIAL_TURN_ID);
    startTurnGeneration(INITIAL_TURN_ID, data.answerMarkdown);
  }, [submittedQuery, data.answerMarkdown, data.referenceSources, startTurnGeneration]);

  useEffect(
    () => () => {
      Object.values(cancelGenerationRef.current).forEach((cancel) => cancel());
    },
    []
  );

  useEffect(() => {
    if (!continueMenuOpen) return;
    const onPointerDown = (e: MouseEvent) => {
      if (continueMenuRef.current && !continueMenuRef.current.contains(e.target as Node)) {
        setContinueMenuOpen(false);
      }
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setContinueMenuOpen(false);
    };
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [continueMenuOpen]);

  useEffect(() => {
    if (!answerMoreMenuTurnId) return;
    const onPointerDown = (e: MouseEvent) => {
      const target = e.target as Node;
      if (answerMoreMenuRef.current?.contains(target)) return;
      if (isInsideSaveTargetFlyout(target)) return;
      setAnswerMoreMenuTurnId(null);
    };
    const onKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') setAnswerMoreMenuTurnId(null);
    };
    document.addEventListener('mousedown', onPointerDown);
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.removeEventListener('mousedown', onPointerDown);
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [answerMoreMenuTurnId]);

  useEffect(() => {
    if (rightPanelWidth >= SOURCE_ASIDE_ACTIONS_COMPACT_MAX_PX) {
      setContinueMenuOpen(false);
    }
  }, [rightPanelWidth]);

  const mergedSources = useMemo<ReferenceSourceItem[]>(
    () =>
      data.referenceSources.map((s) => ({
        ...s,
        userPinned: pinById[s.id] ?? false,
      })),
    [data.referenceSources, pinById]
  );

  const activeTurn = useMemo(
    () => turns.find((t) => t.id === activeSourceTurnId) ?? turns[0],
    [turns, activeSourceTurnId]
  );

  const activeTurnIndex = useMemo(
    () => Math.max(0, turns.findIndex((t) => t.id === activeSourceTurnId)),
    [turns, activeSourceTurnId]
  );

  const activeTurnSourceIdSet = useMemo(
    () => new Set(activeTurn?.sourceIds ?? []),
    [activeTurn]
  );

  const turnMergedSources = useMemo(
    () => mergedSources.filter((s) => activeTurnSourceIdSet.has(s.id)),
    [mergedSources, activeTurnSourceIdSet]
  );

  const mergedMatchResults = useMemo<ReferenceSourceItem[]>(
    () =>
      data.matchResults.map((s) => ({
        ...s,
        userPinned: pinById[s.id] ?? false,
      })),
    [data.matchResults, pinById]
  );

  const turnMatchResults = mergedMatchResults;

  const activeGroupMatchResults = useMemo(() => {
    if (!activeMatchConditionGroupId) return turnMatchResults;
    return turnMatchResults.filter(
      (s) => s.conditionGroupId === activeMatchConditionGroupId
    );
  }, [turnMatchResults, activeMatchConditionGroupId]);

  useEffect(() => {
    if (
      activeMatchConditionGroupId &&
      data.matchConditionGroups.some((g) => g.id === activeMatchConditionGroupId)
    ) {
      return;
    }
    setActiveMatchConditionGroupId(data.matchConditionGroups[0]?.id ?? '');
  }, [data.matchConditionGroups, activeMatchConditionGroupId]);

  const selectedSourceCount = useMemo(
    () => turnMergedSources.filter((s) => s.userPinned).length,
    [turnMergedSources]
  );

  const filteredSorted = useMemo(() => {
    const filtered = filterReferenceSources(turnMergedSources, referenceAppliedFilters);
    return sortReferenceSources(filtered);
  }, [turnMergedSources, referenceAppliedFilters]);

  const filteredSortedMatch = useMemo(() => {
    const filtered = filterReferenceSources(activeGroupMatchResults, matchAppliedFilters, {
      mode: 'match',
      referenceSourceIds: activeTurnSourceIdSet,
    });
    return sortReferenceSources(filtered);
  }, [activeGroupMatchResults, matchAppliedFilters, activeTurnSourceIdSet]);

  const suggestedFollowUps = useMemo(
    () => buildSuggestedFollowUps(submittedQuery),
    [submittedQuery]
  );

  const reportTurn = useMemo(
    () => (reportModalTurnId ? turns.find((t) => t.id === reportModalTurnId) ?? null : null),
    [turns, reportModalTurnId]
  );

  const reportTurnIndex = useMemo(
    () => (reportTurn ? Math.max(0, turns.findIndex((t) => t.id === reportTurn.id)) : 0),
    [turns, reportTurn]
  );

  const isAnswerPanelWide = useMemo(() => {
    if (splitLayoutMode === 'answer_wide') return true;
    if (splitLayoutMode === 'source_wide') return false;
    const el = splitContainerRef.current;
    if (!el) return true;
    const cw = el.getBoundingClientRect().width;
    const leftWidth = cw - SPLIT_HANDLE_PX - rightPanelWidth;
    return leftWidth >= rightPanelWidth;
  }, [splitLayoutMode, rightPanelWidth]);

  const reportResultCardVariant: SearchReportResultCardVariant = isAnswerPanelWide
    ? 'large'
    : 'compact';

  const reportTurnSources = useMemo(
    () => (reportTurn ? getTurnReferenceSources(reportTurn, mergedSources) : []),
    [reportTurn, mergedSources]
  );

  const reportCitedSources = useMemo(
    () => getTurnCitedSources(reportTurnSources),
    [reportTurnSources]
  );

  const totalPages = Math.max(1, Math.ceil(filteredSorted.length / REF_PAGE_SIZE));
  const safePage = Math.min(page, totalPages);
  const pageSlice = useMemo(() => {
    const p = safePage;
    const start = (p - 1) * REF_PAGE_SIZE;
    return filteredSorted.slice(start, start + REF_PAGE_SIZE);
  }, [filteredSorted, safePage]);

  const matchTotalPages = Math.max(1, Math.ceil(filteredSortedMatch.length / REF_PAGE_SIZE));
  const matchSafePage = Math.min(matchPage, matchTotalPages);
  const matchPageSlice = useMemo(() => {
    const p = matchSafePage;
    const start = (p - 1) * REF_PAGE_SIZE;
    return filteredSortedMatch.slice(start, start + REF_PAGE_SIZE);
  }, [filteredSortedMatch, matchSafePage]);

  const activeFilteredList =
    sourcePanelTab === 'reference' ? filteredSorted : filteredSortedMatch;
  const activeTotalPages =
    sourcePanelTab === 'reference' ? totalPages : matchTotalPages;
  const activeSafePage =
    sourcePanelTab === 'reference' ? safePage : matchSafePage;
  const activePageSlice =
    sourcePanelTab === 'reference' ? pageSlice : matchPageSlice;

  useEffect(() => {
    if (page > totalPages) setPage(totalPages);
  }, [page, totalPages]);

  useEffect(() => {
    if (matchPage > matchTotalPages) setMatchPage(matchTotalPages);
  }, [matchPage, matchTotalPages]);

  useEffect(() => {
    const el = splitContainerRef.current;
    if (!el) return;
    const sync = () => {
      const cw = el.getBoundingClientRect().width;
      setRightPanelWidth((w) => {
        if (splitLayoutMode === 'answer_wide') {
          return rightWidthForPreset('answer_wide', cw);
        }
        if (splitLayoutMode === 'source_wide') {
          return rightWidthForPreset('source_wide', cw);
        }
        return clampRightWidth(w, cw);
      });
    };
    sync();
    const ro = new ResizeObserver(sync);
    ro.observe(el);
    return () => ro.disconnect();
  }, [splitLayoutMode]);

  useEffect(
    () => () => {
      if (splitAnimTimerRef.current) clearTimeout(splitAnimTimerRef.current);
    },
    []
  );

  const applySplitPreset = (preset: Exclude<SplitLayoutPreset, 'custom'>, animate = true) => {
    const container = splitContainerRef.current;
    if (!container) return;
    const cw = container.getBoundingClientRect().width;
    if (animate) {
      setSplitAnimating(true);
      if (splitAnimTimerRef.current) clearTimeout(splitAnimTimerRef.current);
      splitAnimTimerRef.current = setTimeout(() => setSplitAnimating(false), SPLIT_TRANSITION_MS);
    } else {
      setSplitAnimating(false);
    }
    setSplitLayoutMode(preset);
    setRightPanelWidth(rightWidthForPreset(preset, cw));
  };

  const toggleSplitLayout = () => {
    const container = splitContainerRef.current;
    if (!container) return;
    const cw = container.getBoundingClientRect().width;
    const target = resolveSplitPresetOnClick(splitLayoutMode, cw, rightPanelWidth);
    applySplitPreset(target, true);
  };

  const onSplitPointerDown = (e: React.PointerEvent<HTMLDivElement>) => {
    if (e.button !== 0) return;
    e.preventDefault();
    splitPointerRef.current = {
      startX: e.clientX,
      startRightWidth: rightPanelWidth,
      didDrag: false,
    };
    e.currentTarget.setPointerCapture(e.pointerId);
  };

  const onSplitPointerMove = (e: React.PointerEvent<HTMLDivElement>) => {
    const drag = splitPointerRef.current;
    const container = splitContainerRef.current;
    if (!drag || !container) return;
    const dx = e.clientX - drag.startX;
    if (!drag.didDrag && Math.abs(dx) >= SPLIT_DRAG_THRESHOLD_PX) {
      drag.didDrag = true;
      setSplitAnimating(false);
      setSplitLayoutMode('custom');
    }
    if (!drag.didDrag) return;
    const rect = container.getBoundingClientRect();
    const next = clampRightWidth(drag.startRightWidth - dx, rect.width);
    setRightPanelWidth(next);
  };

  const onSplitPointerUp = (e: React.PointerEvent<HTMLDivElement>) => {
    const drag = splitPointerRef.current;
    if (drag) {
      if (!drag.didDrag) toggleSplitLayout();
      splitPointerRef.current = null;
    }
    try {
      e.currentTarget.releasePointerCapture(e.pointerId);
    } catch {
      /* ignore */
    }
  };

  const openFilterPanel = () => {
    if (sourcePanelTab === 'reference') {
      setReferenceDraftFilters(
        syncAdvancedFiltersWithRegularFilters(referenceAppliedFilters)
      );
    } else {
      setMatchDraftFilters(syncAdvancedFiltersWithRegularFilters(matchAppliedFilters));
    }
    setFilterOpen(true);
  };

  const confirmFilters = () => {
    if (sourcePanelTab === 'reference') {
      setReferenceAppliedFilters(
        syncAdvancedFiltersWithRegularFilters(referenceDraftFilters)
      );
      setPage(1);
    } else {
      setMatchAppliedFilters(syncAdvancedFiltersWithRegularFilters(matchDraftFilters));
      setMatchPage(1);
    }
    setFilterOpen(false);
  };

  const resetReferenceFilters = () => {
    const defaults = defaultSourceListFilters();
    setReferenceAppliedFilters(defaults);
    setReferenceDraftFilters(defaults);
    setPage(1);
  };

  const toggleUserPin = (id: string) => {
    setPinById((prev) => ({ ...prev, [id]: !(prev[id] ?? false) }));
  };

  const clearAllSourceSelection = () => {
    setPinById(Object.fromEntries(data.referenceSources.map((s) => [s.id, false])));
    setContinueMenuOpen(false);
  };

  const referenceFilterActive = !isDefaultSourceListFilters(referenceAppliedFilters);
  const matchFilterActive = !isDefaultSourceListFilters(matchAppliedFilters);
  const filterActive =
    sourcePanelTab === 'reference' ? referenceFilterActive : matchFilterActive;
  const reportShowFilteredScope = !!(
    reportTurn &&
    reportTurn.id === activeSourceTurnId &&
    referenceFilterActive &&
    filteredSorted.length > 0
  );
  const filterSnapshot =
    sourcePanelTab === 'reference' ? turnMergedSources : activeGroupMatchResults;
  const activeFilterChips = useMemo(() => {
    const filters =
      sourcePanelTab === 'reference' ? referenceAppliedFilters : matchAppliedFilters;
    return getActiveFilterChips(filters, filterSnapshot);
  }, [
    sourcePanelTab,
    referenceAppliedFilters,
    matchAppliedFilters,
    filterSnapshot,
  ]);
  const activeFilterCount = activeFilterChips.length;

  const actionsCompact = rightPanelWidth < SOURCE_ASIDE_ACTIONS_COMPACT_MAX_PX;

  const showSelectedSourceActions = selectedSourceCount > 0;
  const showFilterBasedAnswerAction =
    !showSelectedSourceActions && referenceFilterActive && filteredSorted.length > 0;
  const showAsideBatchActions =
    sourcePanelTab === 'reference' && (showSelectedSourceActions || showFilterBasedAnswerAction);

  const showSaveToast = (msg: string) => {
    setSaveToastMsg(msg);
    if (saveToastTimerRef.current) clearTimeout(saveToastTimerRef.current);
    saveToastTimerRef.current = setTimeout(() => setSaveToastMsg(''), 3000);
  };

  const handleAnswerFromFilteredResults = () => {
    if (filteredSorted.length === 0) return;
    const newTurn = createFilterBasedAnswerTurn(submittedQuery, filteredSorted);
    const targetMarkdown = newTurn.answerMarkdown;
    const turnWithEmpty = { ...newTurn, answerMarkdown: '' };
    scrollToConversationEndRef.current = true;
    setTurns((prev) => [...prev, turnWithEmpty]);
    setActiveSourceTurnId(turnWithEmpty.id);
    resetReferenceFilters();
    setContinueMenuOpen(false);
    startTurnGeneration(turnWithEmpty.id, targetMarkdown);
  };

  const handleViewTurnSources = (turnId: string) => {
    setActiveSourceTurnId(turnId);
    setSourcePanelTab('reference');
    setFilterOpen(false);
    setPage(1);
  };

  const setActiveListPage = (p: number) => {
    if (sourcePanelTab === 'reference') setPage(p);
    else setMatchPage(p);
  };

  const getMatchResultStatusLabel = (item: ReferenceSourceItem): string | null => {
    if (item.citedMark) return '已引用';
    if (activeTurnSourceIdSet.has(item.id)) return '已参考';
    return null;
  };

  const getSourceListTitle = (
    item: ReferenceSourceItem,
    matchStatusLabel: string | null
  ): string => {
    if (matchStatusLabel) return item.title;
    return item.title.replace(/^候选召回\s*\d+：\s*/, '');
  };

  const handleOpenReportModal = (turnId: string) => {
    if (isTurnReportGenerating(reportJobsByTurnId[turnId])) return;
    setReportModalTurnId(turnId);
  };

  const handleGenerateReport = (scope: ReportSourceScope, sourceCount: number) => {
    if (!reportModalTurnId || !reportTurn) return;
    const userQuestion = resolveTurnUserQuestion(reportTurn, submittedQuery);
    const job = createSearchReportJob({
      turnId: reportModalTurnId,
      userQuestion,
      sourceScope: scope,
      sourceCount,
    });
    setReportJobsByTurnId((prev) => ({
      ...prev,
      [reportModalTurnId]: appendSearchReportJob(prev[reportModalTurnId], job),
    }));
  };

  const shiftReportTask = (turnId: string, delta: number) => {
    setReportJobsByTurnId((prev) => {
      const turnJobs = prev[turnId];
      if (!turnJobs) return prev;
      return { ...prev, [turnId]: shiftSearchReportJobIndex(turnJobs, delta) };
    });
  };

  const handleOpenReportDocument = (doc: SearchReportGeneratedDocument) => {
    setPreviewReportDocument(doc);
    applySplitPreset('source_wide', true);
  };

  const handleCloseReportDocument = () => {
    setPreviewReportDocument(null);
  };

  const handleFollowUpSubmit = () => {
    const q = followUp.trim();
    if (!q) return;
    const pinnedInActiveTurn = turnMergedSources.filter((s) => s.userPinned);
    const scopeSources = pinnedInActiveTurn.length > 0 ? pinnedInActiveTurn : turnMergedSources;
    const newTurn = createFollowUpTurn(q, scopeSources);
    const targetMarkdown = newTurn.answerMarkdown;
    const turnWithEmpty = { ...newTurn, answerMarkdown: '' };
    scrollToConversationEndRef.current = true;
    setTurns((prev) => [...prev, turnWithEmpty]);
    setActiveSourceTurnId(turnWithEmpty.id);
    setFollowUp('');
    resetReferenceFilters();
    onFollowUpSubmit();
    startTurnGeneration(turnWithEmpty.id, targetMarkdown);
  };

  const updateTurn = (turnId: string, patch: Partial<ConversationTurn>) => {
    setTurns((prev) => prev.map((t) => (t.id === turnId ? { ...t, ...patch } : t)));
  };

  useEffect(
    () => () => {
      if (copyTipTimerRef.current) clearTimeout(copyTipTimerRef.current);
    },
    []
  );

  useEffect(() => {
    const timer = setInterval(() => {
      setReportJobsByTurnId((prev) => {
        let changed = false;
        const next: Record<string, SearchReportTurnJobs> = { ...prev };
        for (const [turnId, turnJobs] of Object.entries(prev)) {
          let turnChanged = false;
          const jobs = turnJobs.jobs.map((job) => {
            if (job.status !== 'generating') return job;
            turnChanged = true;
            changed = true;
            return advanceSearchReportJob(job);
          });
          if (turnChanged) {
            next[turnId] = { ...turnJobs, jobs };
          }
        }
        return changed ? next : prev;
      });
    }, 1200);
    return () => clearInterval(timer);
  }, []);

  useEffect(() => {
    if (!scrollToConversationEndRef.current) return;
    scrollToConversationEndRef.current = false;

    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const behavior: ScrollBehavior = reducedMotion ? 'auto' : 'smooth';

    const scrollToEnd = () => {
      const scroller = answerScrollRef.current;
      if (!scroller) return;
      scroller.scrollTo({
        top: scroller.scrollHeight,
        behavior,
      });
    };

    requestAnimationFrame(() => {
      requestAnimationFrame(scrollToEnd);
    });
  }, [turns]);

  const handleRegenerateAnswer = (turn: ConversationTurn) => {
    const targetMarkdown = resolveTurnTargetMarkdown(turn);
    updateTurn(turn.id, { answerMarkdown: '' });
    startTurnGeneration(turn.id, targetMarkdown);
  };

  const handleCopyAnswer = async (turn: ConversationTurn) => {
    if (!turn.answerMarkdown.trim()) return;
    try {
      await navigator.clipboard.writeText(turn.answerMarkdown);
      setCopyTipTurnId(turn.id);
      if (copyTipTimerRef.current) clearTimeout(copyTipTimerRef.current);
      copyTipTimerRef.current = setTimeout(() => setCopyTipTurnId(null), 2000);
    } catch {
      /* 演示环境可能无剪贴板权限 */
    }
  };

  const handleEditAnswer = () => {
    /* 演示：后续接入富文本编辑 */
  };

  const handleExportAnswerPdf = (turn: ConversationTurn) => {
    if (!turn.answerMarkdown.trim()) return;
    showSaveToast('PDF 已生成并开始下载');
  };

  const handleExportAnswerWord = (turn: ConversationTurn) => {
    if (!turn.answerMarkdown.trim()) return;
    showSaveToast('Word 已生成并开始下载');
  };

  const clearDislikeFeedbackDraft = (turnId: string) => {
    setDislikeFeedbackDraftByTurnId((prev) => {
      if (!(turnId in prev)) return prev;
      const next = { ...prev };
      delete next[turnId];
      return next;
    });
  };

  const handleAnswerFeedback = (turnId: string, type: 'like' | 'dislike') => {
    const current = answerFeedbackByTurnId[turnId];
    if (current === type) {
      setAnswerFeedbackByTurnId((prev) => {
        const next = { ...prev };
        delete next[turnId];
        return next;
      });
      if (type === 'dislike') {
        setDislikeFeedbackOpenTurnId(null);
        clearDislikeFeedbackDraft(turnId);
      }
      return;
    }

    setAnswerFeedbackByTurnId((prev) => ({ ...prev, [turnId]: type }));
    if (type === 'dislike') {
      setDislikeFeedbackOpenTurnId(turnId);
      setDislikeFeedbackDraftByTurnId((prev) => ({
        ...prev,
        [turnId]: prev[turnId] ?? { selectedReasonIds: [], otherText: '' },
      }));
    } else {
      setDislikeFeedbackOpenTurnId(null);
      clearDislikeFeedbackDraft(turnId);
      showSaveToast('感谢您的反馈！');
    }
  };

  const toggleDislikeFeedbackReason = (turnId: string, reasonId: string) => {
    setDislikeFeedbackDraftByTurnId((prev) => {
      const draft = prev[turnId] ?? { selectedReasonIds: [], otherText: '' };
      const selected = draft.selectedReasonIds.includes(reasonId);
      const selectedReasonIds = selected
        ? draft.selectedReasonIds.filter((id) => id !== reasonId)
        : [...draft.selectedReasonIds, reasonId];
      return {
        ...prev,
        [turnId]: {
          ...draft,
          selectedReasonIds,
          otherText: reasonId === 'other' && selected ? '' : draft.otherText,
        },
      };
    });
  };

  const setDislikeFeedbackOtherText = (turnId: string, text: string) => {
    setDislikeFeedbackDraftByTurnId((prev) => {
      const draft = prev[turnId] ?? { selectedReasonIds: [], otherText: '' };
      return { ...prev, [turnId]: { ...draft, otherText: text } };
    });
  };

  const closeDislikeFeedbackPanel = (turnId: string) => {
    setDislikeFeedbackOpenTurnId((id) => (id === turnId ? null : id));
    clearDislikeFeedbackDraft(turnId);
  };

  const submitDislikeFeedback = (turnId: string) => {
    const draft = dislikeFeedbackDraftByTurnId[turnId];
    if (!draft) return;
    const canSubmit =
      draft.selectedReasonIds.length > 0 || draft.otherText.trim().length > 0;
    if (!canSubmit) return;
    setDislikeFeedbackOpenTurnId(null);
    clearDislikeFeedbackDraft(turnId);
    showSaveToast('感谢您的反馈！');
  };

  const handleDeleteAnswer = (turnId: string) => {
    cancelTurnGeneration(turnId);
    updateTurn(turnId, { answerMarkdown: '' });
  };

  const answerActionBtnClass =
    'flex h-7 w-7 items-center justify-center rounded-md text-slate-500 transition hover:bg-slate-100 hover:text-slate-800 disabled:cursor-not-allowed disabled:opacity-40';

  const answerMoreMenuItemClass = MORE_MENU_ITEM_CLASS;

  const onRemoveFilterChip = (chipId: string) => {
    if (sourcePanelTab === 'reference') {
      setReferenceAppliedFilters((prev) => removeFilterChip(prev, chipId));
      setPage(1);
    } else {
      setMatchAppliedFilters((prev) => removeFilterChip(prev, chipId));
      setMatchPage(1);
    }
  };

  const handleSourcePanelTabChange = (tab: SourcePanelTab) => {
    setSourcePanelTab(tab);
    setFilterOpen(false);
  };

  const handleSelectMatchConditionGroup = (groupId: string) => {
    setActiveMatchConditionGroupId(groupId);
    setMatchPage(1);
  };

  return (
    <>
    <div ref={splitContainerRef} className="flex min-h-0 flex-1 flex-row bg-[#f8fafc]">
      {/* 左侧主答案区 */}
      <section
        className="flex min-w-0 flex-1 flex-col bg-white"
        style={{ minWidth: SPLIT_MIN_LEFT_PX }}
      >
        <div ref={answerScrollRef} className="custom-scrollbar flex-1 overflow-y-auto scroll-smooth px-6 py-5 md:px-8">
          <button
            type="button"
            onClick={onNewSearch}
            className="mb-4 inline-flex items-center gap-1.5 rounded-xl border border-slate-200 bg-slate-50 px-3 py-2 text-[12px] font-extrabold text-slate-600 transition hover:border-blue-200 hover:bg-blue-50 hover:text-blue-700"
          >
            <ArrowLeft size={14} strokeWidth={2.5} />
            新检索
          </button>

          <h1 className="text-[17px] font-extrabold leading-snug text-slate-900 md:text-lg">{data.title}</h1>

          <div className="mt-3 flex flex-wrap items-center gap-2">
            <span className="rounded-lg border border-slate-200 bg-white px-2.5 py-1 text-[11px] font-bold text-slate-500">
              {getModelLabel(modelId)}
            </span>
            {supportsThinkingMode(modelId) ? (
              <span className="rounded-lg bg-slate-100 px-2.5 py-1 text-[11px] font-extrabold text-slate-600">
                {thinkingEnabled ? '思考' : '普通'}
              </span>
            ) : null}
          </div>

          {turns.map((turn, turnIdx) => {
            const sourcesActive = activeSourceTurnId === turn.id;
            const viewSourceBtnClass = sourcesActive
              ? 'bg-blue-600 text-white shadow-sm ring-1 ring-blue-500/30'
              : 'border border-slate-200 bg-white text-slate-600 hover:border-blue-200 hover:bg-blue-50 hover:text-blue-700';
            const turnReportJobs = reportJobsByTurnId[turn.id];
            const activeReportJob = getActiveSearchReportJob(turnReportJobs);
            const isReportGenerating = isTurnReportGenerating(turnReportJobs);
            const turnGeneration = generationByTurnId[turn.id];
            const showExecutionStatus = !!turnGeneration && !turn.answerMarkdown.trim();
            const showTurnFooter = !turnGeneration;
            const answerFeedback = answerFeedbackByTurnId[turn.id];
            const dislikeFeedbackOpen =
              dislikeFeedbackOpenTurnId === turn.id && answerFeedback === 'dislike';
            const dislikeFeedbackDraft =
              dislikeFeedbackDraftByTurnId[turn.id] ?? {
                selectedReasonIds: [],
                otherText: '',
              };
            const answerMoreMenuOpen = answerMoreMenuTurnId === turn.id;
            const answerActionsDisabled = !turn.answerMarkdown.trim();

            return (
              <div
                key={turn.id}
                className={turnIdx > 0 ? 'mt-8 border-t border-slate-100 pt-8' : 'mt-6'}
              >
                {turn.kind === 'follow_up' && turn.userPrompt ? (
                  <div className="mb-4 flex justify-end">
                    <p className="max-w-[92%] rounded-2xl rounded-tr-sm border border-slate-200 bg-slate-50 px-4 py-2.5 text-[13px] font-bold leading-relaxed text-slate-800">
                      {turn.userPrompt}
                    </p>
                  </div>
                ) : null}

                {showExecutionStatus ? (
                  <SearchAnswerExecutionStatus
                    message={getExecutionStepMessage(turnGeneration.stepIndex)}
                  />
                ) : null}

                {turn.answerMarkdown.trim() ? (
                  <SearchAnswerMarkdown content={turn.answerMarkdown} />
                ) : !turnGeneration ? (
                  <p className="py-6 text-center text-[13px] font-medium text-slate-400">
                    回答已删除，可点击「重新生成」恢复演示内容。
                  </p>
                ) : null}

                {showTurnFooter ? (
                <div className="mt-6 border-t border-slate-100 pt-4">
                  <div className="flex items-start justify-between gap-2">
                    <div className="flex min-w-0 flex-1 flex-wrap items-start gap-x-2 gap-y-1.5">
                      <button
                        type="button"
                        onClick={() => handleOpenReportModal(turn.id)}
                        disabled={!turn.answerMarkdown.trim() || isReportGenerating}
                        className="inline-flex h-8 shrink-0 items-center gap-1.5 rounded-lg border border-slate-200 bg-white px-3 text-[12px] font-extrabold text-slate-700 transition hover:border-blue-200 hover:bg-blue-50 hover:text-blue-800 disabled:cursor-not-allowed disabled:opacity-40"
                      >
                        {isReportGenerating ? '正在生成检索报告' : '生成检索报告'}
                      </button>
                      <div className="flex h-8 items-center gap-0.5">
                        <button
                          type="button"
                          title="重新生成"
                          onClick={() => handleRegenerateAnswer(turn)}
                          className={answerActionBtnClass}
                          aria-label="重新生成"
                        >
                          <RefreshCw size={15} strokeWidth={2} />
                        </button>
                        <button
                          type="button"
                          title={copyTipTurnId === turn.id ? '已复制' : '复制内容'}
                          disabled={answerActionsDisabled}
                          onClick={() => handleCopyAnswer(turn)}
                          className={answerActionBtnClass}
                          aria-label="复制内容"
                        >
                          <Copy size={15} strokeWidth={2} />
                        </button>
                        <button
                          type="button"
                          title="点赞"
                          disabled={answerActionsDisabled}
                          onClick={() => handleAnswerFeedback(turn.id, 'like')}
                          className={`${answerActionBtnClass} ${
                            answerFeedback === 'like'
                              ? 'bg-blue-50 text-blue-600 hover:bg-blue-100 hover:text-blue-700'
                              : ''
                          }`}
                          aria-label="点赞"
                          aria-pressed={answerFeedback === 'like'}
                        >
                          <ThumbsUp
                            size={15}
                            strokeWidth={2}
                            fill={answerFeedback === 'like' ? 'currentColor' : 'none'}
                          />
                        </button>
                        <button
                          type="button"
                          title="点踩"
                          disabled={answerActionsDisabled}
                          onClick={() => handleAnswerFeedback(turn.id, 'dislike')}
                          className={`${answerActionBtnClass} ${
                            answerFeedback === 'dislike'
                              ? 'bg-rose-50 text-rose-600 hover:bg-rose-100 hover:text-rose-700'
                              : ''
                          }`}
                          aria-label="点踩"
                          aria-pressed={answerFeedback === 'dislike'}
                        >
                          <ThumbsDown
                            size={15}
                            strokeWidth={2}
                            fill={answerFeedback === 'dislike' ? 'currentColor' : 'none'}
                          />
                        </button>
                        <div
                          ref={answerMoreMenuOpen ? answerMoreMenuRef : undefined}
                          className="relative"
                        >
                          <button
                            type="button"
                            title="更多操作"
                            onClick={() =>
                              setAnswerMoreMenuTurnId((id) =>
                                id === turn.id ? null : turn.id
                              )
                            }
                            aria-expanded={answerMoreMenuOpen}
                            aria-haspopup="menu"
                            className={answerActionBtnClass}
                            aria-label="更多操作"
                          >
                            <MoreHorizontal size={15} strokeWidth={2} />
                          </button>
                          {answerMoreMenuOpen ? (
                            <div
                              role="menu"
                              className="absolute left-0 top-[calc(100%+6px)] z-50 flex min-w-[168px] flex-col gap-0.5 rounded-xl border border-slate-200/90 bg-white p-1.5 shadow-lg shadow-slate-200/80"
                            >
                              <button
                                type="button"
                                role="menuitem"
                                disabled={answerActionsDisabled}
                                className={answerMoreMenuItemClass}
                                onClick={() => {
                                  handleEditAnswer();
                                  setAnswerMoreMenuTurnId(null);
                                }}
                              >
                                <Pencil size={15} strokeWidth={2} className="shrink-0 text-slate-500" />
                                在线编辑
                              </button>
                              <SaveTargetHoverSubmenu
                                label="收录到知识库"
                                icon={
                                  <Layers
                                    size={15}
                                    strokeWidth={2}
                                    className="shrink-0 text-slate-500"
                                  />
                                }
                                items={MOCK_SAVE_KNOWLEDGE_BASES}
                                confirmLabel="收录到知识库"
                                disabled={answerActionsDisabled}
                                menuItemClassName={answerMoreMenuItemClass}
                                onConfirm={() => {
                                  showSaveToast('收录成功');
                                  setAnswerMoreMenuTurnId(null);
                                }}
                              />
                              <ActionHoverSubmenu
                                label="导出文件"
                                icon={
                                  <Upload
                                    size={15}
                                    strokeWidth={2}
                                    className="shrink-0 text-slate-500"
                                  />
                                }
                                items={[
                                  {
                                    id: 'pdf',
                                    label: '生成 PDF 并下载',
                                    icon: (
                                      <FileText
                                        size={15}
                                        strokeWidth={2}
                                        className="shrink-0 text-slate-500"
                                      />
                                    ),
                                  },
                                  {
                                    id: 'word',
                                    label: '生成 Word 并下载',
                                    icon: (
                                      <FileType
                                        size={15}
                                        strokeWidth={2}
                                        className="shrink-0 text-slate-500"
                                      />
                                    ),
                                  },
                                ]}
                                disabled={answerActionsDisabled}
                                menuItemClassName={answerMoreMenuItemClass}
                                onSelect={(id) => {
                                  if (id === 'pdf') handleExportAnswerPdf(turn);
                                  else if (id === 'word') handleExportAnswerWord(turn);
                                  setAnswerMoreMenuTurnId(null);
                                }}
                              />
                              <button
                                type="button"
                                role="menuitem"
                                disabled={answerActionsDisabled}
                                className={`${answerMoreMenuItemClass} text-rose-600 hover:bg-rose-50 hover:text-rose-700`}
                                onClick={() => {
                                  handleDeleteAnswer(turn.id);
                                  setAnswerMoreMenuTurnId(null);
                                }}
                              >
                                <Trash2 size={15} strokeWidth={2} className="shrink-0" />
                                删除
                              </button>
                            </div>
                          ) : null}
                        </div>
                      </div>
                    </div>
                    <button
                      type="button"
                      onClick={() => handleViewTurnSources(turn.id)}
                      aria-pressed={sourcesActive}
                      className={`inline-flex h-8 shrink-0 items-center gap-1.5 rounded-lg px-3 text-[12px] font-extrabold transition ${viewSourceBtnClass}`}
                    >
                      查看来源
                      <span className="tabular-nums text-[11px] font-bold opacity-90">
                        {turn.sourceIds.length}
                      </span>
                      <ChevronRight
                        size={14}
                        strokeWidth={2.5}
                        className="shrink-0 opacity-80"
                        aria-hidden
                      />
                    </button>
                  </div>
                  {dislikeFeedbackOpen ? (
                    <AnswerFeedbackPanel
                      title="感谢反馈。这个回答存在哪些问题？"
                      reasons={DISLIKE_FEEDBACK_REASONS}
                      draft={dislikeFeedbackDraft}
                      onToggleReason={(reasonId) =>
                        toggleDislikeFeedbackReason(turn.id, reasonId)
                      }
                      onOtherTextChange={(text) =>
                        setDislikeFeedbackOtherText(turn.id, text)
                      }
                      onClose={() => closeDislikeFeedbackPanel(turn.id)}
                      onSubmit={() => submitDislikeFeedback(turn.id)}
                    />
                  ) : null}
                  {copyTipTurnId === turn.id ? (
                    <p className="mt-1 text-[11px] font-bold text-emerald-600">
                      已复制到剪贴板
                    </p>
                  ) : null}
                  {activeReportJob && turnReportJobs ? (
                    <div className="mt-4">
                      <SearchReportExecutionPanel
                        job={activeReportJob}
                        taskIndex={turnReportJobs.activeIndex}
                        taskCount={turnReportJobs.jobs.length}
                        onPrevTask={() => shiftReportTask(turn.id, -1)}
                        onNextTask={() => shiftReportTask(turn.id, 1)}
                        reportResultCardVariant={reportResultCardVariant}
                        onOpenDocument={handleOpenReportDocument}
                      />
                    </div>
                  ) : null}
                </div>
                ) : null}
              </div>
            );
          })}

          {!generationByTurnId[INITIAL_TURN_ID] ? (
          <div className="mt-6">
            <p className="mb-2.5 text-[13px] font-extrabold text-slate-800">建议问题</p>
            <div className="space-y-2">
              {suggestedFollowUps.map((question) => (
                <button
                  key={question}
                  type="button"
                  onClick={() => setFollowUp(question)}
                  className="flex w-full items-start gap-2.5 rounded-xl border border-blue-100/90 bg-blue-50/40 px-3.5 py-2.5 text-left text-[13px] font-medium leading-snug text-slate-700 transition hover:border-blue-200 hover:bg-blue-50/80"
                >
                  <span
                    className="mt-[7px] h-1.5 w-1.5 shrink-0 rounded-full bg-blue-500"
                    aria-hidden
                  />
                  <span>{question}</span>
                </button>
              ))}
            </div>
          </div>
          ) : null}
        </div>

        {/* 底部追问 */}
        <div className="flex-shrink-0 border-t border-slate-200 bg-[#f8fafc] px-4 py-3 md:px-6">
          <SearchInput
            value={followUp}
            onChange={setFollowUp}
            onSubmit={handleFollowUpSubmit}
            searchMode={searchMode}
            onSearchModeChange={setSearchMode}
            sources={sources}
            onToggleSource={toggleSource}
            variant="embedded"
            placeholder="您可以继续提出后续的问题"
            selectedReferenceCount={selectedSourceCount}
            onClearSelectedReferences={clearAllSourceSelection}
          />
        </div>
      </section>

      {/* 可拖拽 / 点击切换布局的分割条 */}
      <div
        role="separator"
        aria-orientation="vertical"
        aria-label="点击切换布局，拖动调整宽度；左右方向键微调，按住 Shift 大步调整"
        tabIndex={0}
        onPointerDown={onSplitPointerDown}
        onPointerMove={onSplitPointerMove}
        onPointerUp={onSplitPointerUp}
        onPointerCancel={onSplitPointerUp}
        onKeyDown={(e) => {
          const container = splitContainerRef.current;
          if (!container) return;
          const rect = container.getBoundingClientRect();
          const step = e.shiftKey ? 32 : 12;
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            toggleSplitLayout();
            return;
          }
          if (e.key === 'ArrowLeft') {
            e.preventDefault();
            setSplitAnimating(false);
            setSplitLayoutMode('custom');
            setRightPanelWidth((w) => clampRightWidth(w + step, rect.width));
          } else if (e.key === 'ArrowRight') {
            e.preventDefault();
            setSplitAnimating(false);
            setSplitLayoutMode('custom');
            setRightPanelWidth((w) => clampRightWidth(w - step, rect.width));
          }
        }}
        className="group relative z-10 flex w-[6px] shrink-0 cursor-col-resize touch-none select-none items-stretch justify-center bg-slate-200/80 outline-none transition-colors hover:bg-blue-300/80 focus-visible:bg-blue-300/80 focus-visible:ring-2 focus-visible:ring-blue-400 focus-visible:ring-offset-1"
        style={{ flexBasis: SPLIT_HANDLE_PX, maxWidth: SPLIT_HANDLE_PX }}
      >
        <span
          className="pointer-events-none w-px flex-1 bg-slate-300/90 transition-colors group-hover:bg-blue-500/80 group-focus-visible:bg-blue-500/80"
          aria-hidden
        />
        <span
          className="pointer-events-none absolute left-1/2 top-1/2 flex -translate-x-1/2 -translate-y-1/2 items-center gap-0 rounded-md bg-white/95 px-0.5 py-1 text-slate-400 opacity-0 shadow-md shadow-slate-200/80 ring-1 ring-slate-200/90 transition-[opacity,color] duration-100 group-hover:opacity-100 group-hover:text-blue-600 group-focus-visible:opacity-100 group-focus-visible:text-blue-600"
          aria-hidden
        >
          <ChevronLeft size={11} strokeWidth={2.75} />
          <ChevronRight size={11} strokeWidth={2.75} />
        </span>
        <span
          role="tooltip"
          className="pointer-events-none absolute left-full top-1/2 z-20 ml-2.5 hidden -translate-y-1/2 whitespace-nowrap rounded-md bg-slate-800/95 px-2.5 py-1.5 text-[11px] font-medium leading-none text-white shadow-lg group-hover:block group-focus-visible:block"
        >
          点击切换布局，拖动调整宽度
        </span>
      </div>

      {/* 右侧：参考来源 */}
      <aside
        className="relative flex min-h-0 shrink-0 flex-col overflow-hidden bg-white"
        style={{
          width: rightPanelWidth,
          minWidth: SPLIT_MIN_RIGHT_PX,
          transition: splitAnimating ? `width ${SPLIT_TRANSITION_MS}ms ease` : undefined,
        }}
      >
        <ReferenceSourcesFilterModal
          open={filterOpen && !previewReportDocument}
          onClose={() => setFilterOpen(false)}
          draft={
            sourcePanelTab === 'reference' ? referenceDraftFilters : matchDraftFilters
          }
          setDraft={
            sourcePanelTab === 'reference' ? setReferenceDraftFilters : setMatchDraftFilters
          }
          onConfirm={confirmFilters}
          sourceSnapshot={filterSnapshot}
          filterMode={sourcePanelTab === 'match' ? 'match' : 'reference'}
        />

        {previewReportDocument ? (
          <WpsDocumentEditorPanel
            document={previewReportDocument}
            submittedQuery={submittedQuery}
            onClose={handleCloseReportDocument}
          />
        ) : (
          <>
        <div className="flex min-h-[50px] items-center gap-2 border-b border-slate-100 px-3 py-2">
          <div className="flex min-w-0 shrink-0 items-center gap-2">
            <div
              className="inline-flex shrink-0 rounded-lg bg-slate-100/90 p-0.5 ring-1 ring-slate-200/80"
              role="tablist"
              aria-label="来源面板切换"
            >
              <button
                type="button"
                role="tab"
                aria-selected={sourcePanelTab === 'reference'}
                onClick={() => handleSourcePanelTabChange('reference')}
                className={`inline-flex items-center gap-1 rounded-md px-2.5 py-1 text-[12px] font-extrabold transition ${
                  sourcePanelTab === 'reference'
                    ? 'bg-white text-blue-700 shadow-sm ring-1 ring-blue-100/90'
                    : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                参考来源
                <span className="tabular-nums text-[11px] font-bold opacity-80">
                  {turnMergedSources.length}
                </span>
              </button>
              <button
                type="button"
                role="tab"
                aria-selected={sourcePanelTab === 'match'}
                onClick={() => handleSourcePanelTabChange('match')}
                className={`inline-flex items-center gap-1 rounded-md px-2.5 py-1 text-[12px] font-extrabold transition ${
                  sourcePanelTab === 'match'
                    ? 'bg-white text-blue-700 shadow-sm ring-1 ring-blue-100/90'
                    : 'text-slate-500 hover:text-slate-700'
                }`}
              >
                匹配结果
                <span className="tabular-nums text-[11px] font-bold opacity-80">
                  {turnMatchResults.length}
                </span>
              </button>
            </div>
            {activeTurn ? (
              <span className="shrink-0 text-[10px] font-bold text-blue-600">
                {turnSourceLabel(activeTurn, activeTurnIndex)}
              </span>
            ) : null}
          </div>
          <div className="flex min-w-0 flex-1 items-center justify-end gap-2">
            {activeFilterCount > 0 ? (
              <div
                className="flex min-w-0 flex-1 items-center justify-end gap-1 overflow-hidden [mask-image:linear-gradient(to_left,black_78%,transparent)]"
                title={activeFilterChips.map((c) => c.label).join('、')}
              >
                {activeFilterChips.map((c) => (
                  <span
                    key={c.id}
                    className="inline-flex shrink-0 items-center gap-0.5 rounded-lg bg-slate-100/90 pl-2 pr-0.5 py-0.5 text-[10px] font-extrabold text-slate-700 ring-1 ring-slate-200/80"
                  >
                    {c.label}
                    <button
                      type="button"
                      onClick={() => onRemoveFilterChip(c.id)}
                      className="rounded-md px-1 py-0.5 text-slate-500 transition hover:bg-slate-200/80 hover:text-slate-900"
                      aria-label={`移除筛选 ${c.label}`}
                    >
                      ×
                    </button>
                  </span>
                ))}
              </div>
            ) : null}
            <button
              type="button"
              onClick={openFilterPanel}
              className={`inline-flex shrink-0 items-center gap-1.5 rounded-lg px-2 py-1 text-[12px] font-extrabold transition ${
                filterActive
                  ? 'bg-blue-50 text-blue-700 ring-1 ring-blue-100'
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'
              }`}
            >
              <Filter size={14} strokeWidth={2.25} />
              筛选
              {activeFilterCount > 0 ? (
                <span className="tabular-nums rounded-md bg-blue-600/15 px-1.5 py-0.5 text-[11px] text-blue-800">
                  {activeFilterCount}
                </span>
              ) : null}
            </button>
          </div>
        </div>

        <div className="flex min-h-[44px] items-center justify-between gap-2 border-b border-slate-50 px-3 py-2">
          <p className="min-w-0 text-[11px] font-bold text-slate-500">
            {sourcePanelTab === 'reference' ? (
              selectedSourceCount > 0 ? (
                <>
                  已选{' '}
                  <span className="tabular-nums text-slate-800">{selectedSourceCount}</span>/
                  <span className="tabular-nums text-slate-800">{filteredSorted.length}</span> 个来源
                </>
              ) : (
                <>
                  共 <span className="tabular-nums text-slate-800">{filteredSorted.length}</span> 个来源
                </>
              )
            ) : (
              <>
                共 <span className="tabular-nums text-slate-800">{filteredSortedMatch.length}</span> 个匹配结果
                <span className="text-slate-400">（本轮共执行 </span>
                <span className="tabular-nums text-slate-800">
                  {data.matchConditionGroups.length}
                </span>
                <span className="text-slate-400"> 组检索）</span>
              </>
            )}
            {filterActive ? (
              <span className="ml-1 font-medium text-slate-400">（已筛选）</span>
            ) : null}
          </p>
          {showAsideBatchActions ? (
            <div className="flex shrink-0 items-center gap-2">
              {showSelectedSourceActions ? (
                <>
                  <button
                    type="button"
                    onClick={clearAllSourceSelection}
                    className="rounded-lg border border-slate-200 bg-white px-2.5 py-1 text-[11px] font-extrabold text-slate-600 transition hover:bg-slate-50"
                  >
                    清空选择
                  </button>
                  {actionsCompact ? (
                    <div ref={continueMenuRef} className="relative">
                      <button
                        type="button"
                        onClick={() => setContinueMenuOpen((v) => !v)}
                        aria-expanded={continueMenuOpen}
                        aria-haspopup="menu"
                        className="inline-flex items-center gap-1 rounded-lg bg-blue-50 px-2.5 py-1 text-[11px] font-extrabold text-blue-700 ring-1 ring-blue-100/90 transition hover:bg-blue-100 hover:text-blue-800"
                      >
                        继续
                        <ChevronDown
                          className={`h-3.5 w-3.5 transition ${continueMenuOpen ? 'rotate-180' : ''}`}
                          aria-hidden
                        />
                      </button>
                      {continueMenuOpen ? (
                        <div
                          role="menu"
                          className="absolute right-0 top-[calc(100%+6px)] z-50 flex min-w-[148px] flex-col gap-1.5 rounded-xl border border-slate-200/90 bg-white p-2 shadow-lg shadow-slate-200/80"
                        >
                          <SaveTargetClickMenu
                            label="收录到知识库"
                            items={MOCK_SAVE_KNOWLEDGE_BASES}
                            onConfirm={() => {
                              setContinueMenuOpen(false);
                              showSaveToast('收录成功');
                            }}
                          />
                          <SaveTargetClickMenu
                            label="添加到工作空间"
                            items={MOCK_SAVE_WORKSPACES}
                            selectionMode="single"
                            onConfirm={() => {
                              setContinueMenuOpen(false);
                              showSaveToast('添加成功');
                            }}
                          />
                        </div>
                      ) : null}
                    </div>
                  ) : (
                    <>
                      <SaveTargetClickMenu
                        label="收录到知识库"
                        items={MOCK_SAVE_KNOWLEDGE_BASES}
                        onConfirm={() => showSaveToast('收录成功')}
                      />
                      <SaveTargetClickMenu
                        label="添加到工作空间"
                        items={MOCK_SAVE_WORKSPACES}
                        selectionMode="single"
                        onConfirm={() => showSaveToast('添加成功')}
                      />
                    </>
                  )}
                </>
              ) : (
                <button
                  type="button"
                  onClick={handleAnswerFromFilteredResults}
                  className="shrink-0 rounded-lg bg-blue-50 px-2.5 py-1 text-[11px] font-extrabold text-blue-700 ring-1 ring-blue-100/90 transition hover:bg-blue-100 hover:text-blue-800"
                >
                  基于筛选结果回答
                </button>
              )}
            </div>
          ) : null}
        </div>

        {sourcePanelTab === 'match' && data.matchConditionGroups.length > 0 ? (
          <MatchConditionGroupBar
            groups={data.matchConditionGroups}
            activeGroupId={activeMatchConditionGroupId}
            onSelectGroup={handleSelectMatchConditionGroup}
          />
        ) : null}

        <div className="custom-scrollbar min-h-0 flex-1 overflow-y-auto px-3 py-3">
          <ul className="space-y-3">
            {activePageSlice.map((item) => {
              const userSel = !!item.userPinned;
              const cited = !!item.citedMark;
              const hitPreview = hitDisplayText(item);
              const matchStatusLabel =
                sourcePanelTab === 'match' ? getMatchResultStatusLabel(item) : null;
              const listTitle =
                sourcePanelTab === 'match'
                  ? getSourceListTitle(item, matchStatusLabel)
                  : item.title;

              return (
                <li key={item.id}>
                  <div
                    className={`flex gap-2 rounded-xl px-1 py-1.5 transition ${
                      sourcePanelTab === 'reference' && userSel
                        ? 'border border-blue-100/90 bg-blue-50/45 hover:border-blue-200/85 hover:bg-blue-50/60'
                        : 'border border-transparent hover:border-slate-100 hover:bg-slate-50/90'
                    }`}
                  >
                    {sourcePanelTab === 'reference' ? (
                      <div className="flex shrink-0 pt-0.5">
                        <input
                          type="checkbox"
                          checked={userSel}
                          onChange={() => toggleUserPin(item.id)}
                          className="h-3.5 w-3.5 cursor-pointer rounded border-slate-300 text-blue-600 focus:ring-2 focus:ring-blue-400/40"
                          aria-label={userSel ? '取消已选' : '标记为已选'}
                        />
                      </div>
                    ) : null}
                    <div className="min-w-0 flex-1">
                      <div className="flex items-start justify-between gap-2">
                        <div className="flex min-w-0 flex-1 items-start gap-1">
                          {item.citedMark ? (
                            <span className="shrink-0 pt-0.5 text-[13px] font-medium tabular-nums text-slate-500">
                              {item.citedMark}
                            </span>
                          ) : null}
                          <button
                            type="button"
                            className="min-w-0 flex-1 text-left text-[13px] font-extrabold leading-snug text-slate-900 hover:text-blue-700"
                          >
                            {listTitle}
                          </button>
                        </div>
                        {sourcePanelTab === 'reference' && cited ? (
                          <div className="flex shrink-0 flex-wrap items-center justify-end gap-1">
                            <span className="rounded-md bg-blue-50 px-1.5 py-0.5 text-[10px] font-extrabold text-blue-700 ring-1 ring-blue-100/80">
                              已引用
                            </span>
                          </div>
                        ) : matchStatusLabel ? (
                          <div className="flex shrink-0 flex-wrap items-center justify-end gap-1">
                            <span
                              className={`rounded-md px-1.5 py-0.5 text-[10px] font-extrabold ring-1 ${
                                matchStatusLabel === '已引用'
                                  ? 'bg-blue-50 text-blue-700 ring-blue-100/80'
                                  : 'bg-slate-100 text-slate-600 ring-slate-200/80'
                              }`}
                            >
                              {matchStatusLabel}
                            </span>
                          </div>
                        ) : null}
                      </div>

                      <p className="mt-1 text-[11px] font-medium leading-snug text-slate-500">
                        {buildSourceDetailLine(item)}
                      </p>

                      <HitSnippetPreview
                        matchLabel={matchTypeLabel(item.matchType)}
                        matchLabelClass={matchTypePrefixClass(item.matchType)}
                        text={hitPreview}
                      />
                    </div>
                  </div>
                </li>
              );
            })}
          </ul>
          {activeFilteredList.length === 0 ? (
            <p className="py-8 text-center text-[12px] font-medium leading-relaxed text-slate-400">
              {sourcePanelTab === 'reference'
                ? '当前筛选条件下暂无参考来源，请调整筛选条件。'
                : '当前筛选条件下暂无匹配结果，请调整筛选条件。'}
            </p>
          ) : null}
        </div>

        {activeFilteredList.length > 0 ? (
        <div className="flex flex-wrap items-center justify-center gap-1 border-t border-slate-100 px-2 py-2.5 text-[12px] font-bold text-slate-600">
          <button
            type="button"
            className="rounded-lg p-1 hover:bg-slate-100 disabled:opacity-40"
            disabled={activeSafePage <= 1}
            onClick={() => setActiveListPage(Math.max(1, activeSafePage - 1))}
            aria-label="上一页"
          >
            <ChevronLeft size={16} />
          </button>
          {buildPagination(activeTotalPages, activeSafePage).map((cell, idx) =>
            cell === 'ellipsis' ? (
              <span key={`e-${idx}`} className="px-1 text-slate-400">
                …
              </span>
            ) : (
              <button
                key={cell}
                type="button"
                onClick={() => setActiveListPage(cell)}
                className={`min-w-[28px] rounded-md px-1.5 py-1 tabular-nums transition ${
                  cell === activeSafePage
                    ? 'border border-blue-500 bg-blue-50 text-blue-700'
                    : 'text-slate-500 hover:bg-slate-100'
                }`}
              >
                {cell}
              </button>
            )
          )}
          <button
            type="button"
            className="rounded-lg p-1 hover:bg-slate-100 disabled:opacity-40"
            disabled={activeSafePage >= activeTotalPages}
            onClick={() => setActiveListPage(Math.min(activeTotalPages, activeSafePage + 1))}
            aria-label="下一页"
          >
            <ChevronRight size={16} />
          </button>
        </div>
        ) : null}
          </>
        )}
      </aside>
    </div>

    <SearchReportModal
      open={!!reportModalTurnId && !!reportTurn}
      onClose={() => setReportModalTurnId(null)}
      turn={reportTurn}
      turnLabel={reportTurn ? turnSourceLabel(reportTurn, reportTurnIndex) : ''}
      submittedQuery={submittedQuery}
      allTurnSources={reportTurnSources}
      citedSources={reportCitedSources}
      filteredSources={reportShowFilteredScope ? filteredSorted : null}
      showFilteredScopeOption={reportShowFilteredScope}
      onGenerate={handleGenerateReport}
    />

    {saveToastMsg ? (
      <div className="pointer-events-none fixed left-1/2 top-10 z-[2000] flex -translate-x-1/2 items-center gap-2 rounded-full bg-slate-800 px-6 py-3.5 text-[13px] font-bold text-white shadow-2xl animate-in fade-in slide-in-from-top-4 duration-300">
        <CheckCircle size={16} className="text-emerald-400" strokeWidth={2.5} />
        {saveToastMsg}
      </div>
    ) : null}
    </>
  );
};

export default SearchResultsView;
