/**
 * 合同审查 Playbook 配置问卷
 *
 * 当前仅保留两道题：
 * 1. 审查立场
 * 2. 审查清单 + 清单下审查点
 */

export type QuestionOption = {
  id: string;
  label: string;
};

export type OnboardingQuestion = {
  id: string;
  title: string;
  hint?: string;
  required: boolean;
  /** single：单选；multi：多选；form：结构化表单；checklist：先选清单再选审查点 */
  inputType: 'single' | 'multi' | 'form' | 'checklist';
  options?: QuestionOption[];
  /** form 内附带多选区块的标题 */
  optionsLabel?: string;
  /** form 内多选区块是否排在表单字段之前 */
  optionsBeforeFields?: boolean;
  /** form 类型的字段定义 */
  formFields?: Array<{
    id: string;
    label: string;
    placeholder?: string;
    kind: 'text' | 'select';
    options?: QuestionOption[];
  }>;
  /** 多选时是否允许自定义补充 */
  allowCustom?: boolean;
  customPlaceholder?: string;
};

/** 审查点下的具体审查要求（二级） */
export type ReviewChecklistItem = {
  id: string;
  reviewRequirement: string;
};

/** 审查点分组（一级） */
export type ReviewChecklistPoint = {
  id: string;
  pointName: string;
  itemList: ReviewChecklistItem[];
};

/** 审查清单（第二题：下拉选清单，再勾选两级审查点） */
export type ReviewChecklist = {
  id: string;
  name: string;
  desc?: string;
  points: ReviewChecklistPoint[];
};

