export function getReviewChecklistById(id?: string): ReviewChecklist | undefined {
  if (!id) return undefined;
  return REVIEW_CHECKLISTS.find((c) => c.id === id);
}

export function getChecklistItemIds(checklist: ReviewChecklist): string[] {
  return checklist.points.flatMap((point) => point.itemList.map((item) => item.id));
}

/** 默认选中通用条款审查精选清单，并勾选其下全部审查要求 */
export function buildDefaultChecklistAnswer(): {
  optionIds: string[];
  customText: string;
  formValues: Record<string, string>;
  skipped: boolean;
} {
  const checklist =
    getReviewChecklistById(DEFAULT_REVIEW_CHECKLIST_ID) || REVIEW_CHECKLISTS[0];
  return {
    formValues: { checklistId: checklist.id },
    optionIds: getChecklistItemIds(checklist),
    customText: '',
    skipped: false,
  };
}

