export type PlaybookAnswers = Record<
  string,
  {
    optionIds?: string[];
    customText?: string;
    formValues?: Record<string, string>;
    skipped?: boolean;
  }
>;

export type ContractPlaybook = {
  id: string;
  name: string;
  desc: string;
  createdAt: string;
  updatedAt: string;
  answers: PlaybookAnswers;
  /** true 表示系统默认手册，不可删除 */
  isDefault?: boolean;
};

export const DEFAULT_PLAYBOOK: ContractPlaybook = {
  id: 'default',
  name: '默认审查手册',
  desc: '采用系统默认规则：可配置审查立场与审查清单。点击设置进行配置，或直接开启审查。',
  createdAt: '',
  updatedAt: '',
  answers: {},
  isDefault: true,
};

const REVIEW_STANCE_LABELS: Record<string, string> = {
  buyer_customer: '采购方/客户',
  seller_supplier: '销售方/供货方',
  both_confirm_each_time: '双方都有',
  neutral_structure: '中立结构审查',
};

/** 按问卷规则自动命名审查手册 */
function buildPlaybookName(stanceId?: string): string {
  if (stanceId === 'buyer_customer') return '通用采购审查手册';
  if (stanceId === 'seller_supplier') return '通用销售审查手册';
  if (stanceId === 'both_confirm_each_time') return '通用审查手册';
  if (stanceId === 'neutral_structure') return '中立结构审查手册';
  return '通用审查手册';
}

/** 根据答案生成手册名称与摘要 */
export function buildPlaybookMeta(answers: PlaybookAnswers): { name: string; desc: string } {
  const stanceId = answers.review_stance?.optionIds?.[0];
  const checklistId = answers.review_checklist?.formValues?.checklistId;
  const checklist = getReviewChecklistById(checklistId);
  const pointCount = answers.review_checklist?.optionIds?.length || 0;

  const name = buildPlaybookName(stanceId);

  const parts: string[] = [];
  if (stanceId) parts.push(`审查立场：${REVIEW_STANCE_LABELS[stanceId] || stanceId}`);
  if (checklist) parts.push(`审查清单：${checklist.name}`);
  if (pointCount > 0) parts.push(`已选审查要求 ${pointCount} 项`);
  parts.push('默认输出：Word 批注/修订');

  return {
    name,
    desc: parts.length > 0 ? parts.join(' · ') : '基于问卷回答生成的审查规则手册',
  };
}

function isAnswerFilled(a: PlaybookAnswers[string] | undefined): boolean {
  if (!a || a.skipped) return false;
  if (a.optionIds && a.optionIds.length > 0) return true;
  if (a.customText && a.customText.trim()) return true;
  if (a.formValues && Object.values(a.formValues).some((v) => v && String(v).trim())) return true;
  return false;
}

/** 是否至少回答过一道题（非全部跳过） */
export function hasAnyAnswer(answers: PlaybookAnswers): boolean {
  return Object.values(answers).some(isAnswerFilled);
}

export function countFilledAnswers(answers: PlaybookAnswers): number {
  return Object.values(answers).filter(isAnswerFilled).length;
}

export function createPlaybookFromAnswers(answers: PlaybookAnswers): ContractPlaybook {
  const { name, desc } = buildPlaybookMeta(answers);
  const now = new Date().toISOString();
  return {
    id: `pb_${Date.now()}`,
    name,
    desc,
    createdAt: now,
    updatedAt: now,
    answers,
  };
}

export function updatePlaybookFromAnswers(
  playbook: ContractPlaybook,
  answers: PlaybookAnswers
): ContractPlaybook {
  const { name, desc } = buildPlaybookMeta(answers);
  return {
    ...playbook,
    name,
    desc,
    answers,
    updatedAt: new Date().toISOString(),
  };
}

const STORAGE_KEY = 'lvaiduo_contract_playbooks';
const ONBOARDING_SEEN_KEY = 'lvaiduo_contract_onboarding_seen';
const PREFERRED_PLAYBOOK_KEY = 'lvaiduo_contract_preferred_playbook';
const DEFAULT_ANSWERS_KEY = 'lvaiduo_contract_default_playbook_answers';

export function loadPlaybooks(): ContractPlaybook[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

export function savePlaybooks(playbooks: ContractPlaybook[]) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(playbooks));
}

export function hasSeenOnboarding(): boolean {
  return localStorage.getItem(ONBOARDING_SEEN_KEY) === '1';
}

export function markOnboardingSeen() {
  localStorage.setItem(ONBOARDING_SEEN_KEY, '1');
}

export function loadPreferredPlaybookId(): string {
  return localStorage.getItem(PREFERRED_PLAYBOOK_KEY) || DEFAULT_PLAYBOOK.id;
}

export function savePreferredPlaybookId(id: string) {
  localStorage.setItem(PREFERRED_PLAYBOOK_KEY, id);
}

/** 读取可配置的默认审查手册（含本地已保存答案） */
export function loadDefaultPlaybook(): ContractPlaybook {
  try {
    const raw = localStorage.getItem(DEFAULT_ANSWERS_KEY);
    if (!raw) return { ...DEFAULT_PLAYBOOK };
    const answers = JSON.parse(raw) as PlaybookAnswers;
    if (!answers || typeof answers !== 'object') return { ...DEFAULT_PLAYBOOK };
    const meta = buildPlaybookMeta(answers);
    return {
      ...DEFAULT_PLAYBOOK,
      answers,
      desc: hasAnyAnswer(answers) ? meta.desc : DEFAULT_PLAYBOOK.desc,
    };
  } catch {
    return { ...DEFAULT_PLAYBOOK };
  }
}

/** 保存默认审查手册的配置答案 */
export function saveDefaultPlaybookAnswers(answers: PlaybookAnswers) {
  localStorage.setItem(DEFAULT_ANSWERS_KEY, JSON.stringify(answers));
}

/** 启动审查时快照手册，后续编辑不影响已发起任务 */
export function snapshotPlaybook(playbook: ContractPlaybook): ContractPlaybook {
  return JSON.parse(JSON.stringify(playbook));
}
