import React from 'react';

/**
 * 原型：内嵌「法宝来合同」审查结果页保存快照。
 * 使用 static.html（已剥离 SPA 脚本），避免 Vue 重新挂载清空静态 DOM。
 */
export const LAIHETONG_PROTOTYPE_SRC = `${process.env.PUBLIC_URL || ''}/prototypes/laihetong/static.html`;

type Props = {
  title?: string;
  src?: string;
};

/**
 * 合同审查结果原型预览：以 iframe 嵌入保存的来合同审查结果页
 */
export default function ContractReviewIframePreview({
  title = '合同审查结果（原型）',
  src = LAIHETONG_PROTOTYPE_SRC,
}: Props) {
  return (
    <div className="flex h-full min-h-0 w-full flex-1 flex-col overflow-hidden bg-[#eef1f5]">
      <iframe
        title={title}
        src={src}
        className="h-full w-full flex-1 border-0 bg-white"
        // 原型快照：允许同源脚本与内嵌 WPS 子页面运行
        sandbox="allow-same-origin allow-scripts allow-forms allow-popups allow-downloads"
      />
    </div>
  );
}
