import React, { useEffect, useMemo, useState } from 'react';
import {
  ArrowRight,
  ChevronDown,
  ChevronRight,
  EyeOff,
  ListTree,
  ShieldCheck,
} from 'lucide-react';
import type { MaskResultItem, RecognizeHit } from './desensitizeRecognize';

type RecognizeProps = {
  variant?: 'recognize';
  hits: RecognizeHit[];
  open: boolean;
  activeHitId?: string | null;
  /** 已忽略的命中 id */
  ignoredHitIds?: string[];
  onToggle: () => void;
  onSelectHit: (hitId: string) => void;
  /** 切换单条忽略 */
  onToggleIgnoreHit?: (hitId: string) => void;
  /** 切换同文案全部忽略 / 取消忽略 */
  onToggleIgnoreSame?: (text: string) => void;
};

type MaskedProps = {
  variant: 'masked';
  items: MaskResultItem[];
  open: boolean;
  activeHitId?: string | null;
  onToggle: () => void;
  onSelectHit: (hitId: string) => void;
};

type Props = RecognizeProps | MaskedProps;

type HitGroup<T> = {
  fieldLabel: string;
  items: T[];
};

function groupByField<T extends { fieldLabel: string }>(items: T[]): HitGroup<T>[] {
  const map = new Map<string, T[]>();
  items.forEach((item) => {
    const key = item.fieldLabel || '敏感信息';
    const list = map.get(key);
    if (list) list.push(item);
    else map.set(key, [item]);
  });
  return Array.from(map.entries())
    .map(([fieldLabel, groupItems]) => ({ fieldLabel, items: groupItems }))
    .sort((a, b) => b.items.length - a.items.length || a.fieldLabel.localeCompare(b.fieldLabel, 'zh-CN'));
}

/**
 * 中间预览右下角：识别结果 / 脱敏结果浮层
 */
export default function DesensitizeHitsFloat(props: Props) {
  const isMasked = props.variant === 'masked';
  const recognizeHits = useMemo(
    () => (!isMasked ? props.hits : []),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- discriminated union
    [isMasked, isMasked ? null : props.hits]
  );
  const maskItems = useMemo(
    () => (isMasked ? props.items : []),
    // eslint-disable-next-line react-hooks/exhaustive-deps -- discriminated union
    [isMasked, isMasked ? props.items : null]
  );
  const ignoredSet = useMemo(() => {
    if (isMasked) return new Set<string>();
    return new Set(props.ignoredHitIds || []);
  }, [isMasked, isMasked ? null : props.ignoredHitIds]);

  const sameTextCounts = useMemo(() => {
    const counts = new Map<string, number>();
    recognizeHits.forEach((hit) => {
      counts.set(hit.text, (counts.get(hit.text) || 0) + 1);
    });
    return counts;
  }, [recognizeHits]);

  const totalCount = isMasked ? maskItems.length : recognizeHits.length;
  const ignoredCount = isMasked ? 0 : ignoredSet.size;

  const recognizeGroups = useMemo(() => groupByField(recognizeHits), [recognizeHits]);
  const maskGroups = useMemo(() => groupByField(maskItems), [maskItems]);
  const groups = isMasked ? maskGroups : recognizeGroups;

  const [expandedLabels, setExpandedLabels] = useState<string[]>([]);

  // 识别：默认收起分组；脱敏：默认展开全部分组，便于查看对照
  useEffect(() => {
    if (isMasked) {
      setExpandedLabels(maskGroups.map((g) => g.fieldLabel));
    } else {
      setExpandedLabels([]);
    }
  }, [isMasked, maskGroups]);

  useEffect(() => {
    if (!props.activeHitId) return;
    const group = groups.find((g) =>
      g.items.some((item) => item.id === props.activeHitId)
    );
    if (!group) return;
    setExpandedLabels((prev) =>
      prev.includes(group.fieldLabel) ? prev : [...prev, group.fieldLabel]
    );
  }, [props.activeHitId, groups]);

  const toggleGroup = (fieldLabel: string) => {
    setExpandedLabels((prev) =>
      prev.includes(fieldLabel)
        ? prev.filter((label) => label !== fieldLabel)
        : [...prev, fieldLabel]
    );
  };

  const title = isMasked ? '脱敏结果' : '识别结果';
  const emptyText = isMasked ? '暂无脱敏结果' : '暂无识别结果';

  return (
    <div className="pointer-events-none absolute bottom-5 right-4 z-[35] flex flex-col items-end gap-2 md:bottom-6 md:right-6">
      {props.open ? (
        <div className="pointer-events-auto flex w-[280px] flex-col overflow-hidden rounded-2xl border border-slate-200/90 bg-white/95 shadow-xl shadow-slate-400/20 backdrop-blur-md animate-in fade-in slide-in-from-bottom-2 duration-200">
          <div className="flex shrink-0 items-center justify-between gap-2 border-b border-slate-100 px-3 py-2">
            <div className="min-w-0">
              <p className="text-[12px] font-extrabold text-slate-800">{title}</p>
              <p className="text-[10px] font-bold text-slate-400">
                {groups.length} 类 · 共 {totalCount} 处
                {!isMasked && ignoredCount > 0 ? ` · 已忽略 ${ignoredCount}` : ''}
              </p>
            </div>
            <button
              type="button"
              onClick={props.onToggle}
              className="flex h-7 w-7 items-center justify-center rounded-lg text-slate-400 transition-colors hover:bg-slate-100 hover:text-slate-600"
              title="收起"
              aria-label={`收起${title}`}
            >
              <ChevronDown size={16} strokeWidth={2.5} />
            </button>
          </div>

          <div className="custom-scrollbar max-h-[320px] space-y-1.5 overflow-y-auto p-1.5">
            {groups.length === 0 ? (
              <p className="px-2 py-6 text-center text-[11px] font-bold text-slate-400">
                {emptyText}
              </p>
            ) : isMasked ? (
              maskGroups.map((group) => {
                const expanded = expandedLabels.includes(group.fieldLabel);
                const groupActive = group.items.some((item) => item.id === props.activeHitId);

                return (
                  <div
                    key={group.fieldLabel}
                    className={`overflow-hidden rounded-xl border ${
                      groupActive
                        ? 'border-emerald-200 bg-emerald-50/40'
                        : 'border-slate-200/80 bg-white'
                    }`}
                  >
                    <button
                      type="button"
                      onClick={() => toggleGroup(group.fieldLabel)}
                      aria-expanded={expanded}
                      className="flex w-full items-center gap-1.5 bg-slate-50/80 px-2.5 py-2 text-left transition-colors hover:bg-slate-100"
                    >
                      {expanded ? (
                        <ChevronDown size={14} className="shrink-0 text-slate-400" strokeWidth={2.5} />
                      ) : (
                        <ChevronRight size={14} className="shrink-0 text-slate-400" strokeWidth={2.5} />
                      )}
                      <span className="min-w-0 flex-1 truncate text-[12px] font-extrabold text-slate-700">
                        {group.fieldLabel}
                        <span className="ml-1 font-bold text-slate-400">
                          ({group.items.length}项)
                        </span>
                      </span>
                    </button>

                    {expanded ? (
                      <div className="divide-y divide-slate-100 bg-white">
                        {group.items.map((item) => {
                          const active = props.activeHitId === item.id;
                          return (
                            <button
                              key={item.id}
                              type="button"
                              onClick={() => props.onSelectHit(item.id)}
                              className={`flex w-full items-center gap-1.5 px-2.5 py-2 text-left transition-all ${
                                active
                                  ? 'bg-emerald-50 ring-1 ring-inset ring-emerald-200'
                                  : 'hover:bg-slate-50'
                              }`}
                            >
                              <span
                                className="min-w-0 flex-1 truncate text-[11px] font-bold text-slate-800"
                                title={item.originalText}
                              >
                                {item.originalText}
                              </span>
                              <ArrowRight
                                size={12}
                                className="shrink-0 text-slate-300"
                                strokeWidth={2.5}
                              />
                              <span className="shrink-0 text-[11px] font-extrabold text-[#16a34a]">
                                {item.maskedText}
                              </span>
                            </button>
                          );
                        })}
                      </div>
                    ) : null}
                  </div>
                );
              })
            ) : (
              recognizeGroups.map((group) => {
                const expanded = expandedLabels.includes(group.fieldLabel);
                const groupActive = group.items.some((item) => item.id === props.activeHitId);
                const groupIgnoredCount = group.items.filter((item) =>
                  ignoredSet.has(item.id)
                ).length;

                return (
                  <div
                    key={group.fieldLabel}
                    className={`overflow-hidden rounded-xl border ${
                      groupActive
                        ? 'border-[#e85a2b]/35 bg-[#fffaf7]'
                        : 'border-slate-200/80 bg-white'
                    }`}
                  >
                    <button
                      type="button"
                      onClick={() => toggleGroup(group.fieldLabel)}
                      aria-expanded={expanded}
                      className="flex w-full items-center gap-1.5 bg-slate-50/80 px-2.5 py-2 text-left transition-colors hover:bg-slate-100"
                    >
                      {expanded ? (
                        <ChevronDown size={14} className="shrink-0 text-slate-400" strokeWidth={2.5} />
                      ) : (
                        <ChevronRight size={14} className="shrink-0 text-slate-400" strokeWidth={2.5} />
                      )}
                      <span className="min-w-0 flex-1 truncate text-[12px] font-extrabold text-slate-700">
                        {group.fieldLabel}
                        <span className="ml-1 font-bold text-slate-400">
                          ({group.items.length}项
                          {groupIgnoredCount > 0 ? `·忽略${groupIgnoredCount}` : ''})
                        </span>
                      </span>
                    </button>

                    {expanded ? (
                      <div className="divide-y divide-slate-100 bg-white">
                        {group.items.map((hit) => {
                          const active = props.activeHitId === hit.id;
                          const ignored = ignoredSet.has(hit.id);
                          const hasSame = (sameTextCounts.get(hit.text) || 0) > 1;
                          const sameHits = recognizeHits.filter((h) => h.text === hit.text);
                          const allSameIgnored =
                            hasSame && sameHits.every((h) => ignoredSet.has(h.id));

                          return (
                            <div
                              key={hit.id}
                              className={`group/hit flex items-center gap-1 px-2.5 py-2 transition-all ${
                                active
                                  ? 'bg-[#fde8d8] ring-1 ring-inset ring-[#e85a2b]/30'
                                  : 'hover:bg-slate-50'
                              }`}
                            >
                              <button
                                type="button"
                                onClick={() => props.onSelectHit(hit.id)}
                                className="min-w-0 flex-1 text-left"
                                title={hit.text}
                              >
                                <span
                                  className={`block truncate text-[11px] font-bold leading-snug ${
                                    ignored
                                      ? 'text-slate-400 line-through decoration-slate-300'
                                      : active
                                        ? 'text-[#9a3412]'
                                        : 'text-slate-800'
                                  }`}
                                >
                                  {hit.text}
                                </span>
                              </button>
                              <div
                                className={`flex shrink-0 items-center gap-0.5 transition-opacity ${
                                  ignored
                                    ? 'opacity-100'
                                    : 'opacity-0 group-hover/hit:opacity-100'
                                }`}
                              >
                                <button
                                  type="button"
                                  title={
                                    ignored
                                      ? '取消忽略此项'
                                      : '忽略此项，脱敏时将跳过该字段'
                                  }
                                  aria-label={ignored ? '取消忽略此项' : '忽略此项'}
                                  aria-pressed={ignored}
                                  onClick={(e) => {
                                    e.stopPropagation();
                                    // 取消后若按钮仍聚焦，操作区会一直显示；点击后失焦
                                    (e.currentTarget as HTMLButtonElement).blur();
                                    if (!isMasked) props.onToggleIgnoreHit?.(hit.id);
                                  }}
                                  className={`flex h-6 w-6 items-center justify-center rounded-md transition-colors ${
                                    ignored
                                      ? 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                                      : 'text-blue-500 hover:bg-blue-50 hover:text-blue-600'
                                  }`}
                                >
                                  <EyeOff size={13} strokeWidth={2.5} />
                                </button>
                                {hasSame ? (
                                  <button
                                    type="button"
                                    title={
                                      allSameIgnored
                                        ? '取消忽略同项'
                                        : '忽略同项，脱敏时将跳过所有相同内容'
                                    }
                                    aria-label={allSameIgnored ? '取消忽略同项' : '忽略同项'}
                                    aria-pressed={allSameIgnored}
                                    onClick={(e) => {
                                      e.stopPropagation();
                                      (e.currentTarget as HTMLButtonElement).blur();
                                      if (!isMasked) props.onToggleIgnoreSame?.(hit.text);
                                    }}
                                    className={`rounded-md px-1 py-0.5 text-[10px] font-extrabold whitespace-nowrap transition-colors ${
                                      allSameIgnored
                                        ? 'bg-slate-100 text-slate-500 hover:bg-slate-200'
                                        : 'text-blue-600 hover:bg-blue-50'
                                    }`}
                                  >
                                    忽略同项
                                  </button>
                                ) : null}
                              </div>
                            </div>
                          );
                        })}
                      </div>
                    ) : null}
                  </div>
                );
              })
            )}
          </div>
        </div>
      ) : null}

      <button
        type="button"
        onClick={props.onToggle}
        aria-expanded={props.open}
        aria-label={title}
        className={`pointer-events-auto inline-flex h-10 items-center gap-1.5 rounded-2xl border px-3.5 text-[12px] font-extrabold shadow-xl shadow-slate-400/15 backdrop-blur-md transition-all ${
          props.open
            ? isMasked
              ? 'border-emerald-200 bg-emerald-600 text-white hover:bg-emerald-700'
              : 'border-blue-200 bg-blue-600 text-white hover:bg-blue-700'
            : 'border-slate-200/90 bg-white/95 text-slate-700 hover:border-blue-200 hover:text-blue-600'
        }`}
      >
        {isMasked ? (
          <ShieldCheck size={16} strokeWidth={2.5} />
        ) : (
          <ListTree size={16} strokeWidth={2.5} />
        )}
        {title}
        {totalCount > 0 ? (
          <span
            className={`rounded-md px-1.5 py-0.5 text-[10px] font-extrabold tabular-nums ${
              props.open ? 'bg-white/20 text-white' : 'bg-slate-100 text-slate-500'
            }`}
          >
            {totalCount}
          </span>
        ) : null}
      </button>
    </div>
  );
}
